INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'en','{"title":"PARTICIPANT INFORMATION SHEET","headernames":{"studyTitle":"Study Title","sponsor":"Organiser and Funder","iecApproval":"Ethics Review"},"header":{"studyTitle":"Development of an AI enabled Breast Cancer Risk Prediction Tool for the Indian Population","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"About this study","paragraphs":[{"text":"This study is part of a Ministry of Education funded project to develop Indian AI solutions for Healthcare. TANUH Foundation is a section 8 company hosted by Indian Institute of Science proud to lead this critical national initiative in breast cancer research, recognizing that early, data-driven detection is vital for improving health outcomes. We deeply appreciate your participation and thank you for being an essential part of this effort to advance breast cancer study for the benefit of women across India. Make AI in India and Make AI work for India."}]},{"heading":"What is the purpose of the study?","paragraphs":[{"text":"Development of an AI enabled Breast Cancer Risk Prediction Tool for the Indian Population"}]},{"heading":"Why have I been chosen?","paragraphs":[{"text":"You have been chosen to contribute towards the study of AI enabled breast cancer screening tools because you have been referred to mammography or getting a routine mammography. We are developing an AI enabled breast cancer screening tool that enables identification of breast cancer risk by a few questionnaires."}]},{"heading":"Do I have to take part?","paragraphs":[{"text":"Your participation is completely voluntary. You may opt not to participate in the study and continue with your normal routine."}]},{"heading":"What Will Happen in the Study If you agree to participate, the following will occur?","paragraphs":[{"text":"Survey: You will be asked to fill out a one-time questionnaire (on a tablet/digital device) regarding your demographics, health history, lifestyle, and family history of cancer."},{"text":"Risk Prediction: At the end of the survey, you will be provided with an immediate breast cancer risk prediction (identifying if you are at normal or higher risk)."},{"text":"Guidance: Based on the risk level, you will receive guidance. If you are found to be at higher risk, you may be referred for mammography. If you are at normal/low risk, you will be asked to continue regular checkup protocols."},{"text":"Data Usage: The data collected from you and from the hospital will be used to train an Artificial Intelligence (AI) model to better predict breast cancer risk in Indian women."}]},{"heading":"What will happen to me if I take part?","paragraphs":[{"text":"The personalized risk prediction will help you to be more aware of possible breast cancer symptoms and your individual risk factors for future health monitoring."}]},{"heading":"What do I have to do?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"What are the possible risks of taking part?","paragraphs":[{"text":"There are no known major risks in taking part in this research study."},{"text":"No/Minimal Risk: This study is considered \\"no/minimal risk\\"."},{"text":"Privacy: There is a rare risk regarding privacy, but this is mitigated because we do not collect personally identifiable information, and data is captured anonymously."},{"text":"Voluntary: The questionnaire is completely voluntary; if you are not interested, you may pursue routine clinic care instead."},{"text":"No Invasive Procedures: This is a digital and workflow innovation study; no experimental drugs or invasive therapies are involved in the research component."}]},{"heading":"What are the possible benefits of taking part?","paragraphs":[{"text":"Personal Benefit: There is likely no direct benefit for individual participants. However, you will receive a risk prediction that may help inform your screening strategy."},{"text":"Societal Benefit: Your participation will contribute to scientific benefits, including enhanced early detection of breast cancer and better resource allocation for women across India."}]},{"heading":"Will my taking part in this study be kept confidential?","paragraphs":[{"text":"Yes. All information collected during this study will be kept strictly confidential. All personal data will be anonymized and stored securely in accordance with applicable data protection regulations. Only authorized research team members will have access to the data, and no personally identifiable information will be shared with third parties without your explicit consent. The study results will be presented in aggregate form only, ensuring individual participants cannot be identified."},{"text":"About 20% of the total data, collected in an irreversible anonymised manner, will be part of the benchmarking and open data initiative of TANUH for evaluation of AI algorithms. The data collected will be used in future research, including the development of other foundation models."}]},{"heading":"What is voluntary participation?","paragraphs":[{"text":"Your participation is entirely voluntary. You can refuse to participate or stop the survey at any time without penalty or loss of benefits."}]},{"heading":"Are there any compensation and Medical Care for Research-Related Injury?","paragraphs":[{"text":"Compensation: You will not be paid for participating in this study. No compensation is offered as this is a minimal/no-risk study."},{"text":"Injury: As this is a survey/AI-based screening study involving no invasive interventions, no medical treatment or compensation for injury is planned."},{"text":"Costs: There is no cost to you for participating in this study."}]},{"heading":"What will happen to the results of the research study?","paragraphs":[{"text":"The results of this research study will be used to develop and validate an AI enabled Breast Cancer Risk Prediction tool. Findings may be published in peer-reviewed scientific journals, presented at academic conferences, and shared with healthcare institutions and policymakers to improve breast cancer screening practices in India. All published results will be in aggregate form with no individual identification."}]},{"heading":"Who is organising and funding the research?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"Who has reviewed the study?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"Who can I contact for further information?","paragraphs":[{"text":"Contact Details: Dr. Ashwin RaajKumar, Project Manager"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"If you wish to speak to someone independent of the study, you may contact the:"},{"text":"Institutional Ethics Committee (IEC)"},{"text":"Name: Dr. Sri Vidya Jagadish, Secretary, IEC, TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"Thank you for taking part in the study!"}]}],"checkboxLabel":"I have read and understood the Participant Information Sheet and voluntarily agree to participate in this study.","buttonText":"Accept & Continue"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'hi','{"title":"प्रतिभागी सूचना पत्रक","headernames":{"studyTitle":"अध्ययन का शीर्षक","sponsor":"आयोजक और निधि","iecApproval":"नैतिकता की समीक्षा"},"header":{"studyTitle":"भारतीय आबादी के लिए एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण का विकास","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"इस अध्ययन के बारे में","paragraphs":[{"text":"यह अध्ययन स्वास्थ्य सेवा के लिए भारतीय एआई समाधान विकसित करने के लिए शिक्षा मंत्रालय द्वारा वित्त पोषित एक परियोजना का हिस्सा है। TANUH फाउंडेशन भारतीय विज्ञान संस्थान द्वारा होस्ट की गई एक सेक्शन 8 कंपनी है जो स्तन कैंसर अनुसंधान में इस महत्वपूर्ण राष्ट्रीय पहल का नेतृत्व करने पर गर्व करती है, यह पहचानकर कि स्वास्थ्य परिणामों में सुधार के लिए प्रारंभिक, डेटा-संचालित पता लगाना महत्वपूर्ण है। हम आपकी भागीदारी की गहरी सराहना करते हैं और आपको धन्यवाद देते हैं कि आप पूरे भारत में महिलाओं के लाभ के लिए स्तन कैंसर अध्ययन को आगे बढ़ाने के इस प्रयास का एक आवश्यक हिस्सा हैं। भारत में एआई बनाएं और भारत के लिए एआई काम करें।"}]},{"heading":"अध्ययन का उद्देश्य क्या है?","paragraphs":[{"text":"भारतीय आबादी के लिए एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण का विकास"}]},{"heading":"मुझे क्यों चुना गया है?","paragraphs":[{"text":"आपको एआई सक्षम स्तन कैंसर स्क्रीनिंग टूल के अध्ययन में योगदान देने के लिए चुना गया है क्योंकि आपको स्तन कैंसर स्क्रीनिंग टूल के लिए संदर्भित किया गया है या आपको नियमित स्तन कैंसर स्क्रीनिंग टूल दिया गया है। हम एक एआई सक्षम स्तन कैंसर स्क्रीनिंग टूल विकसित कर रहे हैं जो कुछ प्रश्नावली के माध्यम से स्तन कैंसर के जोखिम की पहचान करने में सक्षम बनाता है।"}]},{"heading":"क्या मुझे भाग लेना है?","paragraphs":[{"text":"आपकी भागीदारी पूरी तरह से स्वैच्छिक है। आप अध्ययन में भाग नहीं लेने का विकल्प चुन सकते हैं और अपनी सामान्य दिनचर्या को जारी रख सकते हैं।"}]},{"heading":"अध्ययन में क्या होगा यदि आप भाग लेने के लिए सहमत हों, तो निम्नलिखित होगा?","paragraphs":[{"text":"सर्वेक्षणः आपको अपने जनसांख्यिकीय, स्वास्थ्य इतिहास, जीवन शैली और परिवार के कैंसर के इतिहास के बारे में एक बार का प्रश्नावली (टैबलेट/डिजिटल डिवाइस पर) भरने के लिए कहा जाएगा।"},{"text":"जोखिम पूर्वानुमानः सर्वेक्षण के अंत में, आपको स्तन कैंसर के जोखिम की तत्काल पूर्वानुमान (यह पहचानने के लिए कि क्या आप सामान्य या उच्च जोखिम में हैं) प्रदान किया जाएगा।"},{"text":"मार्गदर्शनः जोखिम के स्तर के आधार पर आपको मार्गदर्शन प्राप्त होगा। यदि आपको अधिक जोखिम में पाया जाता है, तो आपको मैमोग्राफी के लिए भेजा जा सकता है। यदि आप सामान्य/कम जोखिम में हैं, तो आपको नियमित जांच प्रोटोकॉल जारी रखने के लिए कहा जाएगा।"},{"text":"डेटा उपयोगः आपके और अस्पताल से एकत्र किए गए डेटा का उपयोग भारतीय महिलाओं में स्तन कैंसर के जोखिम की बेहतर भविष्यवाणी करने के लिए आर्टिफिशियल इंटेलिजेंस (एआई) मॉडल को प्रशिक्षित करने के लिए किया जाएगा।"}]},{"heading":"यदि मैं भाग लेता हूँ तो मेरे साथ क्या होगा?","paragraphs":[{"text":"व्यक्तिगत जोखिम पूर्वानुमान आपको स्तन कैंसर के संभावित लक्षणों और भविष्य की स्वास्थ्य निगरानी के लिए अपने व्यक्तिगत जोखिम कारकों के बारे में अधिक जागरूक होने में मदद करेगा।"}]},{"heading":"मुझे क्या करना है?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"इसमें भाग लेने के क्या जोखिम हो सकते हैं?","paragraphs":[{"text":"इस शोध अध्ययन में भाग लेने के कोई प्रमुख जोखिम ज्ञात नहीं हैं।"},{"text":"कोई/ न्यूनतम जोखिम नहींः इस अध्ययन को \\"कोई/ न्यूनतम जोखिम\\" माना जाता है।"},{"text":"गोपनीयताः गोपनीयता के संबंध में एक दुर्लभ जोखिम है, लेकिन यह कम किया जाता है क्योंकि हम व्यक्तिगत रूप से पहचान योग्य जानकारी एकत्र नहीं करते हैं, और डेटा गुमनाम रूप से कैप्चर किया जाता है।"},{"text":"स्वैच्छिक: प्रश्नावली पूरी तरह से स्वैच्छिक है; यदि आप रुचि नहीं रखते हैं, तो आप इसके बजाय नियमित चिकित्सा देखभाल कर सकते हैं।"},{"text":"कोई आक्रामक प्रक्रियाएं नहींः यह एक डिजिटल और वर्कफ़्लो नवाचार अध्ययन है; अनुसंधान घटक में कोई प्रयोगात्मक दवाएं या आक्रामक उपचार शामिल नहीं हैं।"}]},{"heading":"भाग लेने से क्या लाभ हो सकते हैं?","paragraphs":[{"text":"व्यक्तिगत लाभः व्यक्तिगत प्रतिभागियों के लिए कोई प्रत्यक्ष लाभ नहीं है। हालांकि, आपको जोखिम का पूर्वानुमान प्राप्त होगा जो आपकी स्क्रीनिंग रणनीति को सूचित करने में मदद कर सकता है।"},{"text":"सामाजिक लाभ: आपकी भागीदारी से वैज्ञानिक लाभों में योगदान होगा, जिसमें स्तन कैंसर का शीघ्र पता लगाना और भारत भर में महिलाओं के लिए संसाधनों का बेहतर आवंटन शामिल है।"}]},{"heading":"क्या इस अध्ययन में मेरी भागीदारी गोपनीय रहेगी?","paragraphs":[{"text":"हां. इस अध्ययन के दौरान एकत्र की गई सभी जानकारी को सख्ती से गोपनीय रखा जाएगा। सभी व्यक्तिगत डेटा को लागू डेटा संरक्षण नियमों के अनुसार गुमनाम किया जाएगा और सुरक्षित रूप से संग्रहीत किया जाएगा। केवल अधिकृत शोध टीम के सदस्यों को डेटा तक पहुंच होगी, और आपकी स्पष्ट सहमति के बिना किसी तीसरे पक्ष के साथ व्यक्तिगत रूप से पहचान योग्य कोई जानकारी साझा नहीं की जाएगी। अध्ययन के परिणाम केवल समग्र रूप में प्रस्तुत किए जाएंगे, जिससे यह सुनिश्चित होगा कि व्यक्तिगत प्रतिभागियों की पहचान नहीं की जा सके।"},{"text":"कुल आंकड़ों में से लगभग 20 प्रतिशत, जो अपरिवर्तनीय रूप से अज्ञात तरीके से एकत्र किए जाएंगे, AI एल्गोरिदम के मूल्यांकन के लिए TANUH की बेंचमार्किंग और ओपन डेटा पहल का हिस्सा होंगे। एकत्र किए गए डेटा का उपयोग भविष्य के अनुसंधान में किया जाएगा, जिसमें अन्य फाउंडेशन मॉडल के विकास भी शामिल है।"}]},{"heading":"स्वैच्छिक भागीदारी क्या है?","paragraphs":[{"text":"आपकी भागीदारी पूरी तरह से स्वैच्छिक है। आप बिना जुर्माना या लाभों के किसी भी समय सर्वेक्षण में भाग लेने से इनकार कर सकते हैं या रोक सकते हैं।"}]},{"heading":"क्या अनुसंधान से संबंधित चोटों के लिए कोई मुआवजा और चिकित्सा देखभाल है?","paragraphs":[{"text":"मुआवजाः इस अध्ययन में भाग लेने के लिए आपको भुगतान नहीं किया जाएगा। कोई मुआवजा नहीं दिया जाता है क्योंकि यह एक न्यूनतम / जोखिम मुक्त अध्ययन है।"},{"text":"चोटः चूंकि यह एक सर्वेक्षण/एआई आधारित स्क्रीनिंग अध्ययन है जिसमें कोई आक्रामक हस्तक्षेप शामिल नहीं है, इसलिए चोट के लिए कोई चिकित्सा उपचार या क्षतिपूर्ति की योजना नहीं है।"},{"text":"लागतः इस अध्ययन में भाग लेने के लिए आपको कोई लागत नहीं है।"}]},{"heading":"अनुसंधान के परिणामों का क्या होगा?","paragraphs":[{"text":"इस शोध अध्ययन के परिणामों का उपयोग एक एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण विकसित करने और सत्यापित करने के लिए किया जाएगा। निष्कर्षों को पीयर-रिव्यू वैज्ञानिक पत्रिकाओं में प्रकाशित किया जा सकता है, शैक्षणिक सम्मेलनों में प्रस्तुत किया जा सकता है, और भारत में स्तन कैंसर स्क्रीनिंग प्रथाओं में सुधार के लिए स्वास्थ्य देखभाल संस्थानों और नीति निर्माताओं के साथ साझा किया जा सकता है। सभी प्रकाशित परिणाम एक समग्र रूप में होंगे, बिना किसी व्यक्तिगत पहचान के।"}]},{"heading":"शोध का आयोजन और वित्तपोषण कौन कर रहा है?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"इस अध्ययन की समीक्षा किसने की है?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"मैं और जानकारी के लिए किससे संपर्क कर सकता हूँ?","paragraphs":[{"text":"संपर्क विवरणः डॉ. अश्विन राजकुमार, परियोजना प्रबंधक"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"यदि आप अध्ययन से स्वतंत्र किसी व्यक्ति से बात करना चाहते हैं, तो आप निम्न से संपर्क कर सकते हैंः"},{"text":"संस्थागत नैतिकता समिति (IEC)"},{"text":"नाम: डॉ. श्री विद्या जगदीश, सचिव, आईईसी, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"अध्ययन में भाग लेने के लिए धन्यवाद!"}]}],"checkboxLabel":"मैंने प्रतिभागियों की सूचना पत्रिका पढ़ी और समझी है और स्वेच्छा से इस अध्ययन में भाग लेने के लिए सहमत हूं।","buttonText":"स्वीकार करें और आगे बढ़ें"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'bn','{"title":"অংশগ্রহণকারী তথ্য পত্রিকা","headernames":{"studyTitle":"অধ্যয়নের শিরোনাম","sponsor":"সংগঠক ও তহবিল","iecApproval":"নৈতিকতার পর্যালোচনা"},"header":{"studyTitle":"ভারতীয় জনসংখ্যার জন্য একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"এই গবেষণার বিষয়ে","paragraphs":[{"text":"এই গবেষণাটি স্বাস্থ্যসেবা জন্য ভারতীয় এআই সমাধান বিকাশের জন্য শিক্ষা মন্ত্রকের অর্থায়িত প্রকল্পের অংশ। তানুহ ফাউন্ডেশন একটি বিভাগ 8 সংস্থা যা ভারতীয় বিজ্ঞান ইনস্টিটিউট দ্বারা হোস্ট করা হয় এবং স্তন ক্যান্সারের গবেষণায় এই গুরুত্বপূর্ণ জাতীয় উদ্যোগের নেতৃত্ব দিতে গর্বিত, স্বাস্থ্যের ফলাফল উন্নত করতে প্রাথমিক, ডেটা-চালিত সনাক্তকরণ অত্যন্ত গুরুত্বপূর্ণ। আমরা আপনার অংশগ্রহণের গভীর প্রশংসা করি এবং সারা ভারত জুড়ে মহিলাদের সুবিধার্থে স্তন ক্যান্সারের গবেষণাকে এগিয়ে নেওয়ার এই প্রচেষ্টার একটি অপরিহার্য অংশ হওয়ার জন্য আপনাকে ধন্যবাদ জানাই। ভারতে এআই তৈরি করুন এবং ভারতে এআই কাজ করুন।"}]},{"heading":"অধ্যয়নের উদ্দেশ্য কী?","paragraphs":[{"text":"ভারতীয় জনসংখ্যার জন্য একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ"}]},{"heading":"কেন আমাকে বেছে নেওয়া হয়েছে?","paragraphs":[{"text":"আপনি এআই-সক্ষম স্তন ক্যান্সার স্ক্রিনিং সরঞ্জামগুলির গবেষণায় অবদান রাখতে নির্বাচিত হয়েছেন কারণ আপনাকে ম্যামোগ্রাফি বা রুটিন ম্যামোগ্রাফি করার জন্য উল্লেখ করা হয়েছে। আমরা একটি এআই-সক্ষম স্তন ক্যান্সার স্ক্রিনিং সরঞ্জাম বিকাশ করছি যা কয়েকটি প্রশ্নাবলীর মাধ্যমে স্তন ক্যান্সার ঝুঁকি সনাক্ত করতে সক্ষম করে।"}]},{"heading":"আমাকে কি অংশ নিতে হবে?","paragraphs":[{"text":"আপনি স্বেচ্ছায় এই গবেষণায় অংশগ্রহণ করতে পারবেন না এবং আপনার স্বাভাবিক রুটিন অনুসরণ করতে পারেন।"}]},{"heading":"অধ্যয়নে কি ঘটবে যদি আপনি অংশ নিতে রাজি হন, তাহলে নিম্নলিখিত ঘটনা ঘটবে?","paragraphs":[{"text":"জরিপঃ আপনার জনসংখ্যা, স্বাস্থ্য ইতিহাস, জীবনযাত্রা এবং ক্যান্সারের পরিবারের ইতিহাস সম্পর্কে আপনাকে একটি একক প্রশ্নপত্র (ট্যাবলেট/ডিজিটাল ডিভাইসে) পূরণ করতে বলা হবে।"},{"text":"ঝুঁকি পূর্বাভাসঃ সমীক্ষার শেষে, আপনাকে অবিলম্বে স্তন ক্যান্সারের ঝুঁকি পূর্বাভাস দেওয়া হবে (যদি আপনি স্বাভাবিক বা উচ্চ ঝুঁকিতে থাকেন তা সনাক্ত করা হবে) ।"},{"text":"নির্দেশনাঃ ঝুঁকি স্তরের উপর ভিত্তি করে, আপনাকে নির্দেশনা দেওয়া হবে। যদি আপনার ঝুঁকি বেশি থাকে তবে আপনাকে ম্যামোগ্রাফি করার জন্য রেফার করা যেতে পারে। যদি আপনার ঝুঁকি স্বাভাবিক/কম থাকে তবে আপনাকে নিয়মিত চেকআপ প্রোটোকল চালিয়ে যেতে বলা হবে।"},{"text":"ডেটা ব্যবহারঃ আপনার এবং হাসপাতালের কাছ থেকে সংগৃহীত তথ্যগুলি ভারতীয় মহিলাদের স্তন ক্যান্সারের ঝুঁকি আরও ভালভাবে পূর্বাভাস দেওয়ার জন্য একটি কৃত্রিম বুদ্ধিমত্তা (এআই) মডেল প্রশিক্ষণের জন্য ব্যবহৃত হবে।"}]},{"heading":"আমি অংশগ্রহণ করলে আমার কি হবে?","paragraphs":[{"text":"ব্যক্তিগতকৃত ঝুঁকি পূর্বাভাস আপনাকে স্তন ক্যান্সারের সম্ভাব্য লক্ষণ এবং ভবিষ্যতে স্বাস্থ্য পর্যবেক্ষণের জন্য আপনার পৃথক ঝুঁকিপূর্ণ কারণগুলি সম্পর্কে আরও সচেতন হতে সহায়তা করবে।"}]},{"heading":"আমি কি করব?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"অংশগ্রহণের ঝুঁকি কি?","paragraphs":[{"text":"এই গবেষণায় অংশগ্রহণের ক্ষেত্রে কোন বড় ঝুঁকি নেই।"},{"text":"কোন ঝুঁকি নেই/মিনিমাল ঝুঁকিঃ এই গবেষণাটি \\"কোন ঝুঁকি নেই/মিনিমাল ঝুঁকি\\" বলে বিবেচিত হয়।"},{"text":"গোপনীয়তাঃ গোপনীয়তার ক্ষেত্রে একটি বিরল ঝুঁকি রয়েছে, কিন্তু এটি হ্রাস করা হয় কারণ আমরা ব্যক্তিগতভাবে সনাক্তযোগ্য তথ্য সংগ্রহ করি না এবং তথ্য অজানাভাবে সংরক্ষণ করা হয়।"},{"text":"স্বেচ্ছাসেবকঃ এই প্রশ্নাবলীটি সম্পূর্ণ স্বেচ্ছাসেবক; যদি আপনি আগ্রহী না হন, তাহলে আপনি নিয়মিত ক্লিনিকাল যত্ন নিতে পারেন।"},{"text":"কোন আক্রমণাত্মক পদ্ধতি নেইঃ এটি একটি ডিজিটাল এবং কর্মপ্রবাহের উদ্ভাবনী গবেষণা; গবেষণার উপাদানটিতে কোন পরীক্ষামূলক ওষুধ বা আক্রমণাত্মক থেরাপি জড়িত নয়।"}]},{"heading":"অংশগ্রহণের সম্ভাব্য উপকারিতা কি কি?","paragraphs":[{"text":"ব্যক্তিগত উপকারিতাঃ প্রত্যক্ষভাবে অংশগ্রহণকারীদের কোন উপকারিতা নেই। তবে আপনি একটি ঝুঁকি পূর্বাভাস পাবেন যা আপনার স্ক্রিনিং কৌশলকে অবহিত করতে সহায়তা করতে পারে।"},{"text":"সামাজিক সুবিধাঃ আপনার অংশগ্রহণে বৈজ্ঞানিক সুবিধার জন্য অবদান থাকবে, যার মধ্যে রয়েছে স্তন ক্যান্সারের প্রাথমিক সনাক্তকরণ এবং সারা ভারত জুড়ে মহিলাদের জন্য আরও ভাল সম্পদ বরাদ্দ।"}]},{"heading":"এই গবেষণায় আমার অংশগ্রহণ কি গোপন থাকবে?","paragraphs":[{"text":"হ্যাঁ. এই গবেষণার সময় সংগৃহীত সমস্ত তথ্য কঠোরভাবে গোপনীয় রাখা হবে। সমস্ত ব্যক্তিগত তথ্য প্রযোজ্য ডেটা সুরক্ষা বিধি অনুসারে অ্যানোনিমেড এবং সুরক্ষিতভাবে সংরক্ষণ করা হবে। শুধুমাত্র অনুমোদিত গবেষণা দলের সদস্যদের ডেটাতে অ্যাক্সেস থাকবে, এবং আপনার স্পষ্ট সম্মতি ছাড়া কোনও ব্যক্তিগত সনাক্তকরণযোগ্য তথ্য তৃতীয় পক্ষের সাথে ভাগ করা হবে না। গবেষণার ফলাফলগুলি কেবল সামগ্রিক আকারে উপস্থাপন করা হবে, যাতে পৃথক অংশগ্রহণকারীদের সনাক্ত করা যায় না।"},{"text":"মোট তথ্যের প্রায় ২০% অবদান থাকবে, যা অনিবার্যভাবে অ্যানোনিমেটেডভাবে সংগ্রহ করা হবে। এই তথ্যগুলি এআই অ্যালগরিদমগুলির মূল্যায়নের জন্য TANUH এর ব্যানচমার্কিং এবং ওপেন ডেটা ইনিশিয়েটিভের অংশ হবে। সংগ্রহ করা তথ্যগুলি ভবিষ্যতে গবেষণায় ব্যবহার করা হবে, অন্যান্য ভিত্তি মডেলগুলির বিকাশ সহ।"}]},{"heading":"স্বেচ্ছাসেবী অংশগ্রহণ কি?","paragraphs":[{"text":"আপনি যে কোনো সময় জরিপে অংশগ্রহণ করতে অস্বীকার করতে পারেন অথবা বিনা জরিপে বা বেতনের ক্ষতি ছাড়াই এ জরিপে অংশগ্রহণ বন্ধ করতে পারেন।"}]},{"heading":"গবেষণা সংক্রান্ত আঘাতের জন্য কি কোন ক্ষতিপূরণ ও চিকিৎসা আছে?","paragraphs":[{"text":"ক্ষতিপূরণঃ এই গবেষণায় অংশগ্রহণের জন্য আপনাকে কোনো বেতন দেওয়া হবে না। কোন ক্ষতিপূরণ দেওয়া হয় না কারণ এটি একটি ন্যূনতম/নিরাপদ গবেষণা।"},{"text":"আঘাতঃ এটি একটি জরিপ/এআই ভিত্তিক স্ক্রিনিং স্টাডি যা কোনও আক্রমণাত্মক হস্তক্ষেপ জড়িত নয়, আঘাতের জন্য কোনও চিকিৎসা বা ক্ষতিপূরণ পরিকল্পনা করা হয়নি।"},{"text":"খরচঃ এই গবেষণায় অংশগ্রহণের জন্য আপনার কোন খরচ নেই।"}]},{"heading":"গবেষণার ফলাফল কি হবে?","paragraphs":[{"text":"এই গবেষণার ফলাফলগুলি একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ এবং বৈধ করার জন্য ব্যবহৃত হবে। ফলাফলগুলি সমকালীন পর্যালোচনা করা বৈজ্ঞানিক জার্নালগুলিতে প্রকাশিত হতে পারে, একাডেমিক সম্মেলনে উপস্থাপন করা যেতে পারে এবং ভারতে স্তন ক্যান্সার স্ক্রিনিং অনুশীলনগুলি উন্নত করতে স্বাস্থ্যসেবা প্রতিষ্ঠান এবং নীতি নির্ধারকদের সাথে ভাগ করা যেতে পারে। সমস্ত প্রকাশিত ফলাফলগুলি কোনও পৃথক সনাক্তকরণ ছাড়াই সমষ্টিগত আকারে হবে।"}]},{"heading":"গবেষণা কে পরিচালনা করছে এবং কে এর অর্থায়ন করছে?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"কে এই গবেষণাটি পর্যালোচনা করেছে?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"আমি কার সাথে যোগাযোগ করতে পারি?","paragraphs":[{"text":"যোগাযোগের তথ্যঃ প্রকল্প পরিচালক ডাঃ অশ্বিন রাজকুমার"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"আপনি যদি গবেষণার বাইরে কারো সাথে কথা বলতে চান, তাহলে আপনি নিম্নলিখিত বিষয়গুলো নিয়ে যোগাযোগ করতে পারেনঃ"},{"text":"প্রাতিষ্ঠানিক নীতিগত কমিটি (আইইসি)"},{"text":"নামঃ ডঃ শ্রী বিদ্যা জগদীশ, আইইসি, তানুহের সচিব"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"অধ্যয়নে অংশগ্রহণের জন্য আপনাকে ধন্যবাদ!"}]}],"checkboxLabel":"আমি অংশগ্রহণকারীদের তথ্যপত্র পড়েছি এবং বুঝতে পেরেছি এবং স্বেচ্ছায় এই গবেষণায় অংশগ্রহণ করতে রাজি হয়েছি।","buttonText":"গ্রহণ করুন এবং চালিয়ে যান"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'gu','{"title":"સહભાગી માહિતી શીટ","headernames":{"studyTitle":"અભ્યાસનું શીર્ષક","sponsor":"આયોજક અને ફંડ","iecApproval":"નૈતિકતા સમીક્ષા"},"header":{"studyTitle":"ભારતીય વસ્તી માટે એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવું","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"આ અભ્યાસ વિશે","paragraphs":[{"text":"આ અભ્યાસ આરોગ્યસંભાળ માટે ભારતીય એઆઈ ઉકેલો વિકસાવવા માટે શિક્ષણ મંત્રાલય દ્વારા ભંડોળ પૂરું પાડવામાં આવેલા પ્રોજેક્ટનો ભાગ છે. ભારતીય ઇન્સ્ટિટ્યૂટ ઓફ સાયન્સ દ્વારા આયોજિત થનૂહ ફાઉન્ડેશન એક વિભાગ 8 કંપની છે. સ્તન કેન્સર સંશોધન માટે આ મહત્વપૂર્ણ રાષ્ટ્રીય પહેલનું નેતૃત્વ કરવા માટે ગર્વ અનુભવે છે, તે માન્યતા આપે છે કે આરોગ્ય પરિણામોમાં સુધારો કરવા માટે પ્રારંભિક, ડેટા આધારિત શોધ મહત્વપૂર્ણ છે. અમે તમારી ભાગીદારીની ખૂબ પ્રશંસા કરીએ છીએ અને સમગ્ર ભારતમાં મહિલાઓના લાભ માટે સ્તન કેન્સર અભ્યાસને આગળ વધારવા માટે આ પ્રયાસનો આવશ્યક ભાગ હોવા બદલ આભાર. ભારતમાં એઆઈ બનાવો અને ભારત માટે એઆઈ કાર્ય કરો."}]},{"heading":"અભ્યાસનો હેતુ શું છે?","paragraphs":[{"text":"ભારતીય વસ્તી માટે એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવું"}]},{"heading":"મને કેમ પસંદ કરવામાં આવ્યો છે?","paragraphs":[{"text":"તમને એઆઈ સક્ષમ સ્તન કેન્સર સ્ક્રિનિંગ ટૂલ્સના અભ્યાસમાં યોગદાન આપવા માટે પસંદ કરવામાં આવ્યા છે કારણ કે તમને મેમોગ્રાફી અથવા નિયમિત મેમોગ્રાફી આપવામાં આવી છે. અમે એઆઈ સક્ષમ સ્તન કેન્સર સ્ક્રિનિંગ ટૂલ વિકસિત કરી રહ્યા છીએ જે થોડા પ્રશ્નાવલિઓ દ્વારા સ્તન કેન્સરનું જોખમ ઓળખવા માટે સક્ષમ બનાવે છે."}]},{"heading":"શું મારે ભાગ લેવો પડશે?","paragraphs":[{"text":"તમે અભ્યાસમાં ભાગ લેવાનું પસંદ કરી શકો છો અને તમારી સામાન્ય નિયમિતતા સાથે ચાલુ રાખી શકો છો."}]},{"heading":"શું થશે?","paragraphs":[{"text":"સર્વેક્ષણઃ તમને તમારા વસ્તી વિષયક, સ્વાસ્થ્ય ઇતિહાસ, જીવનશૈલી અને કુટુંબના કેન્સર ઇતિહાસ વિશે એક વખતનો પ્રશ્નાવલિ (ટેબ્લેટ / ડિજિટલ ઉપકરણ પર) ભરવા માટે કહેવામાં આવશે."},{"text":"જોખમ આગાહીઃ સર્વેક્ષણના અંતે, તમને સ્તન કેન્સરનું જોખમ તાત્કાલિક આગાહી આપવામાં આવશે (જો તમે સામાન્ય અથવા વધુ જોખમ ધરાવો છો તો ઓળખવા માટે)."},{"text":"માર્ગદર્શનઃ જોખમ સ્તરના આધારે તમને માર્ગદર્શન આપવામાં આવશે. જો તમને વધુ જોખમ હોવાનું જાણવા મળ્યું હોય, તો તમને મેમોગ્રાફી માટે રેફર કરી શકાય છે. જો તમે સામાન્ય / નીચા જોખમ પર છો, તો તમને નિયમિત તપાસ પ્રોટોકોલ ચાલુ રાખવા માટે કહેવામાં આવશે."},{"text":"ડેટા વપરાશઃ તમારા અને હોસ્પિટલમાંથી એકત્રિત કરવામાં આવેલા ડેટાનો ઉપયોગ ભારતીય મહિલાઓમાં સ્તન કેન્સરનું જોખમ વધુ સારી રીતે આગાહી કરવા માટે કૃત્રિમ બુદ્ધિ (AI) મોડેલને તાલીમ આપવા માટે કરવામાં આવશે."}]},{"heading":"જો હું ભાગ લઈશ તો મને શું થશે?","paragraphs":[{"text":"વ્યક્તિગત જોખમ આગાહી તમને ભવિષ્યમાં આરોગ્યની દેખરેખ માટે સંભવિત સ્તન કેન્સર લક્ષણો અને તમારા વ્યક્તિગત જોખમ પરિબળો વિશે વધુ જાગૃત કરવામાં મદદ કરશે."}]},{"heading":"મારે શું કરવું છે?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ભાગ લેવાનું જોખમ શું છે?","paragraphs":[{"text":"આ સંશોધન અભ્યાસમાં ભાગ લેવાથી કોઈ મોટા જોખમો જાણીતા નથી."},{"text":"કોઈ / ન્યૂનતમ જોખમઃ આ અભ્યાસને \\"કોઈ / ન્યૂનતમ જોખમ\\" ગણવામાં આવે છે."},{"text":"ગોપનીયતાઃ ગોપનીયતા સંબંધિત એક દુર્લભ જોખમ છે, પરંતુ આ ઘટાડવામાં આવે છે કારણ કે અમે વ્યક્તિગત રૂપે ઓળખી શકાય તેવી માહિતી એકત્રિત કરતા નથી, અને ડેટા અનામી રીતે મેળવવામાં આવે છે."},{"text":"સ્વૈચ્છિકઃ પ્રશ્નાવલિ સંપૂર્ણપણે સ્વૈચ્છિક છે; જો તમને રસ ન હોય તો, તમે તેના બદલે નિયમિત ક્લિનિકલ સંભાળ મેળવી શકો છો."},{"text":"કોઈ આક્રમક કાર્યવાહી નથીઃ આ ડિજિટલ અને વર્કફ્લો નવીનતા અભ્યાસ છે; સંશોધન ઘટકમાં કોઈ પ્રાયોગિક દવાઓ અથવા આક્રમક ઉપચાર સામેલ નથી."}]},{"heading":"ભાગ લેવાથી શું ફાયદો થઈ શકે?","paragraphs":[{"text":"વ્યક્તિગત લાભઃ વ્યક્તિગત સહભાગીઓ માટે કોઈ સીધો લાભ હોતો નથી. જો કે, તમને જોખમ આગાહી મળશે જે તમારી સ્ક્રીનીંગ વ્યૂહરચનાને જાણવામાં મદદ કરી શકે છે."},{"text":"સામાજિક લાભ: તમારી ભાગીદારીથી વૈજ્ઞાનિક લાભો પ્રાપ્ત થશે, જેમાં સ્તન કેન્સરનું પ્રારંભિક નિદાન વધારવામાં આવશે અને સમગ્ર ભારતમાં મહિલાઓ માટે વધુ સારા સંસાધનોનું ફાળવણી કરવામાં આવશે."}]},{"heading":"શું આ અભ્યાસમાં મારી ભાગીદારી ગુપ્ત રાખવામાં આવશે?","paragraphs":[{"text":"હા. આ અભ્યાસ દરમિયાન એકત્રિત કરવામાં આવેલી તમામ માહિતી સખત ગુપ્ત રાખવામાં આવશે. તમામ વ્યક્તિગત ડેટાને લાગુ ડેટા સંરક્ષણ નિયમો અનુસાર અનામીકરણ કરવામાં આવશે અને સુરક્ષિત રીતે સંગ્રહિત કરવામાં આવશે. ફક્ત અધિકૃત સંશોધન ટીમના સભ્યો જ ડેટાની ઍક્સેસ કરશે, અને તમારી સ્પષ્ટ સંમતિ વિના કોઈ વ્યક્તિગત રૂપે ઓળખી શકાય તેવી માહિતી તૃતીય પક્ષો સાથે શેર કરવામાં આવશે નહીં. અભ્યાસના પરિણામો ફક્ત એકંદર સ્વરૂપમાં રજૂ કરવામાં આવશે, જે વ્યક્તિગત સહભાગીઓની ઓળખ કરી શકાતી નથી તેની ખાતરી કરશે."},{"text":"કુલ ડેટાના આશરે 20% અનિવાર્ય રીતે અનામી રીતે એકત્રિત કરવામાં આવશે, જે AI અલ્ગોરિધમ્સના મૂલ્યાંકન માટે TANUH ની બેંચમાર્કિંગ અને ઓપન ડેટા પહેલનો ભાગ હશે."}]},{"heading":"સ્વૈચ્છિક ભાગીદારી શું છે?","paragraphs":[{"text":"તમારી ભાગીદારી સંપૂર્ણપણે સ્વૈચ્છિક છે. તમે કોઈપણ સમયે દંડ અથવા લાભો ગુમાવ્યા વગર મતદાનમાં ભાગ લેવાનો ઇનકાર કરી શકો છો અથવા બંધ કરી શકો છો."}]},{"heading":"શું સંશોધન સંબંધિત ઈજાઓ માટે કોઈ વળતર અને તબીબી સંભાળ છે?","paragraphs":[{"text":"વળતરઃ આ અભ્યાસમાં ભાગ લેવા માટે તમને ચૂકવણી કરવામાં આવશે નહીં. કોઈ વળતર આપવામાં આવતું નથી કારણ કે આ એક ન્યૂનતમ / કોઈ જોખમ વિનાનું અભ્યાસ છે."},{"text":"ઈજાઃ કારણ કે આ એક સર્વેક્ષણ/AI આધારિત સ્ક્રીનીંગ સ્ટડી છે જેમાં કોઈ આક્રમક હસ્તક્ષેપ સામેલ નથી, ઇજા માટે કોઈ તબીબી સારવાર અથવા વળતરની યોજના નથી."},{"text":"ખર્ચઃ આ અભ્યાસમાં ભાગ લેવા માટે તમને કોઈ ખર્ચ નથી."}]},{"heading":"સંશોધનના પરિણામોનું શું થશે?","paragraphs":[{"text":"આ સંશોધન અભ્યાસના પરિણામોનો ઉપયોગ એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવા અને માન્ય કરવા માટે કરવામાં આવશે. પરિણામો પીઅર-રીવ્યુ કરેલ વૈજ્ઞાનિક સામયિકોમાં પ્રકાશિત થઈ શકે છે, શૈક્ષણિક પરિષદોમાં રજૂ કરી શકાય છે, અને ભારતમાં સ્તન કેન્સર સ્ક્રિનિંગ પદ્ધતિઓમાં સુધારો કરવા માટે આરોગ્યસંભાળ સંસ્થાઓ અને નીતિ ઘડવૈયાઓ સાથે શેર કરી શકાય છે. બધા પ્રકાશિત પરિણામો વ્યક્તિગત ઓળખ વિના એકંદર સ્વરૂપમાં હશે."}]},{"heading":"સંશોધનનું આયોજન અને ભંડોળ કોણ આપે છે?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"કોણે આ અભ્યાસની સમીક્ષા કરી છે?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"વધુ માહિતી માટે હું કોનો સંપર્ક કરી શકું?","paragraphs":[{"text":"સંપર્ક વિગતો: ડૉ. અશ્વિન રજકુમાર, પ્રોજેક્ટ મેનેજર"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"જો તમે અભ્યાસથી સ્વતંત્ર વ્યક્તિ સાથે વાત કરવા માંગતા હો, તો તમે નીચેનાનો સંપર્ક કરી શકો છોઃ"},{"text":"સંસ્થાકીય નીતિશાસ્ત્ર સમિતિ (IEC)"},{"text":"નામઃ ડૉ. શ્રી વિદ્યા જગદીશ, આઇઇસી, તાનૂહના સચિવ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"અભ્યાસમાં ભાગ લેવા બદલ આભાર!"}]}],"checkboxLabel":"મેં સહભાગી માહિતી શીટ વાંચી અને સમજી છે અને આ અભ્યાસમાં ભાગ લેવા માટે સ્વૈચ્છિક રીતે સંમત છું.","buttonText":"સ્વીકારો અને ચાલુ રાખો"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'kn','{"title":"ಭಾಗವಹಿಸುವವರ ಮಾಹಿತಿ ಹಾಳೆ","headernames":{"studyTitle":"ಅಧ್ಯಯನದ ಶೀರ್ಷಿಕೆ","sponsor":"ಸಂಘಟಕ ಮತ್ತು ನಿಧಿ","iecApproval":"ನೈತಿಕತೆ ವಿಮರ್ಶೆ"},"header":{"studyTitle":"ಭಾರತೀಯ ಜನಸಂಖ್ಯೆಗೆ ಎಐ ಸಕ್ರಿಯಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಸಾಧನ ಅಭಿವೃದ್ಧಿ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ಈ ಅಧ್ಯಯನದ ಬಗ್ಗೆ","paragraphs":[{"text":"ಈ ಅಧ್ಯಯನವು ಆರೋಗ್ಯ ರಕ್ಷಣೆಗಾಗಿ ಭಾರತೀಯ AI ಪರಿಹಾರಗಳನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸುವ ಶಿಕ್ಷಣ ಸಚಿವಾಲಯದ ನಿಧಿಸಂಗ್ರಹಿತ ಯೋಜನೆಯ ಭಾಗವಾಗಿದೆ. TANUH ಫೌಂಡೇಶನ್ ಭಾರತೀಯ ವಿಜ್ಞಾನ ಸಂಸ್ಥೆ ಆಯೋಜಿಸಿದ ವಿಭಾಗ 8 ಕಂಪನಿಯಾಗಿದ್ದು, ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸಂಶೋಧನೆಯಲ್ಲಿ ಈ ನಿರ್ಣಾಯಕ ರಾಷ್ಟ್ರೀಯ ಉಪಕ್ರಮವನ್ನು ಮುನ್ನಡೆಸಲು ಹೆಮ್ಮೆಪಡುತ್ತದೆ. ಆರೋಗ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಸುಧಾರಿಸಲು ಆರಂಭಿಕ, ಡೇಟಾ ಆಧಾರಿತ ಪತ್ತೆ ಅತ್ಯಗತ್ಯ ಎಂದು ಗುರುತಿಸುತ್ತದೆ. ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಧ್ಯಯನವನ್ನು ಭಾರತದಾದ್ಯಂತ ಮಹಿಳೆಯರ ಅನುಕೂಲಕ್ಕಾಗಿ ಮುನ್ನಡೆಸಲು ಈ ಪ್ರಯತ್ನದಲ್ಲಿ ನೀವು ಪ್ರಮುಖ ಭಾಗವಾಗಿರುವುದಕ್ಕಾಗಿ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ನಾವು ಆಳವಾಗಿ ಪ್ರಶಂಸಿಸುತ್ತೇವೆ ಮತ್ತು ಧನ್ಯವಾದಗಳು. ಭಾರತದಲ್ಲಿ AI ಅನ್ನು ಮಾಡಿ ಮತ್ತು AI ಅನ್ನು ಭಾರತಕ್ಕಾಗಿ ಕೆಲಸ ಮಾಡಿ."}]},{"heading":"ಅಧ್ಯಯನದ ಉದ್ದೇಶವೇನು?","paragraphs":[{"text":"ಭಾರತೀಯ ಜನಸಂಖ್ಯೆಗೆ ಎಐ ಸಕ್ರಿಯಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಸಾಧನ ಅಭಿವೃದ್ಧಿ"}]},{"heading":"ನನ್ನನ್ನು ಯಾಕೆ ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ?","paragraphs":[{"text":"ನೀವು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಉಪಕರಣಗಳ ಅಧ್ಯಯನಕ್ಕೆ ಕೊಡುಗೆ ನೀಡಲು ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ ಏಕೆಂದರೆ ನಿಮಗೆ ಸ್ತನಗ್ರಹಣ ಅಥವಾ ವಾಡಿಕೆಯ ಸ್ತನಗ್ರಹಣವನ್ನು ಮಾಡಲಾಗಿದೆ. ನಾವು ಕೆಲವು ಪ್ರಶ್ನಾವಳಿಗಳ ಮೂಲಕ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯವನ್ನು ಗುರುತಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುವ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಉಪಕರಣವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸುತ್ತಿದ್ದೇವೆ."}]},{"heading":"ನಾನು ಭಾಗವಹಿಸಬೇಕೇ?","paragraphs":[{"text":"ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸದೆ ನಿಮ್ಮ ಸಾಮಾನ್ಯ ವಾಡಿಕೆಯಂತೆ ಮುಂದುವರಿಯಬಹುದು."}]},{"heading":"ಅಧ್ಯಯನದಲ್ಲಿ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ಸಮೀಕ್ಷೆಃ ನಿಮ್ಮ ಜನಸಂಖ್ಯಾಶಾಸ್ತ್ರ, ಆರೋಗ್ಯ ಇತಿಹಾಸ, ಜೀವನಶೈಲಿ ಮತ್ತು ಕ್ಯಾನ್ಸರ್ನ ಕುಟುಂಬದ ಇತಿಹಾಸದ ಬಗ್ಗೆ ಒಂದು ಬಾರಿ (ಟ್ಯಾಬ್ಲೆಟ್/ಡಿಜಿಟಲ್ ಸಾಧನದಲ್ಲಿ) ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಭರ್ತಿ ಮಾಡಲು ನಿಮ್ಮನ್ನು ಕೇಳಲಾಗುತ್ತದೆ."},{"text":"ಅಪಾಯದ ಮುನ್ಸೂಚನೆಃ ಸಮೀಕ್ಷೆಯ ಕೊನೆಯಲ್ಲಿ, ನಿಮಗೆ ತಕ್ಷಣದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯದ ಮುನ್ಸೂಚನೆ ನೀಡಲಾಗುವುದು (ನೀವು ಸಾಮಾನ್ಯ ಅಥವಾ ಹೆಚ್ಚಿನ ಅಪಾಯದಲ್ಲಿದ್ದರೆ ಗುರುತಿಸುವುದು)."},{"text":"ಮಾರ್ಗದರ್ಶನಃ ಅಪಾಯದ ಮಟ್ಟದ ಆಧಾರದ ಮೇಲೆ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲಾಗುವುದು. ನೀವು ಹೆಚ್ಚಿನ ಅಪಾಯದಲ್ಲಿದ್ದರೆ, ನಿಮಗೆ ಸ್ತನಗ್ರಹಣಕ್ಕೆ ಉಲ್ಲೇಖಿಸಬಹುದು. ನೀವು ಸಾಮಾನ್ಯ / ಕಡಿಮೆ ಅಪಾಯದಲ್ಲಿದ್ದರೆ, ನಿಯಮಿತ ತಪಾಸಣೆ ಪ್ರೋಟೋಕಾಲ್ಗಳನ್ನು ಮುಂದುವರಿಸಲು ನಿಮ್ಮನ್ನು ಕೇಳಲಾಗುತ್ತದೆ."},{"text":"ಡೇಟಾ ಬಳಕೆಃ ನಿಮ್ಮಿಂದ ಮತ್ತು ಆಸ್ಪತ್ರೆಯಿಂದ ಸಂಗ್ರಹಿಸಲಾದ ಡೇಟಾವನ್ನು ಭಾರತೀಯ ಮಹಿಳೆಯರಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯವನ್ನು ಉತ್ತಮವಾಗಿ ಊಹಿಸಲು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ (AI) ಮಾದರಿಯನ್ನು ತರಬೇತಿ ನೀಡಲು ಬಳಸಲಾಗುತ್ತದೆ."}]},{"heading":"ನಾನು ಭಾಗವಹಿಸಿದರೆ ನನಗೆ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ವೈಯಕ್ತಿಕಗೊಳಿಸಿದ ಅಪಾಯ ಮುನ್ಸೂಚನೆಯು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ನ ಸಂಭವನೀಯ ಲಕ್ಷಣಗಳ ಬಗ್ಗೆ ಮತ್ತು ಭವಿಷ್ಯದ ಆರೋಗ್ಯ ಮೇಲ್ವಿಚಾರಣೆಗಾಗಿ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಅಪಾಯಕಾರಿ ಅಂಶಗಳ ಬಗ್ಗೆ ಹೆಚ್ಚು ಜಾಗೃತರಾಗಲು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ."}]},{"heading":"ನಾನು ಏನು ಮಾಡಬೇಕು?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ಭಾಗವಹಿಸುವಿಕೆಯು ಯಾವ ಅಪಾಯಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದು?","paragraphs":[{"text":"ಈ ಸಂಶೋಧನಾ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸುವಿಕೆಯು ಯಾವುದೇ ಪ್ರಮುಖ ಅಪಾಯಗಳನ್ನು ಹೊಂದಿಲ್ಲ."},{"text":"ಯಾವುದೇ/ಕಡಿಮೆ ಅಪಾಯಃ ಈ ಅಧ್ಯಯನವನ್ನು \\"ಯಾವುದೇ/ಕಡಿಮೆ ಅಪಾಯ\\" ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ."},{"text":"ಗೌಪ್ಯತೆಃ ಗೌಪ್ಯತೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಅಪರೂಪದ ಅಪಾಯವಿದೆ, ಆದರೆ ನಾವು ವೈಯಕ್ತಿಕವಾಗಿ ಗುರುತಿಸಬಹುದಾದ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ ಮತ್ತು ಡೇಟಾವನ್ನು ಅನಾಮಧೇಯವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ."},{"text":"ಸ್ವಯಂಪ್ರೇರಿತಃ ಪ್ರಶ್ನಾವಳಿಯು ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ; ನಿಮಗೆ ಆಸಕ್ತಿ ಇಲ್ಲದಿದ್ದರೆ, ನೀವು ಬದಲಾಗಿ ನಿಯಮಿತ ಚಿಕಿತ್ಸಾಲಯದ ಆರೈಕೆಯನ್ನು ಮುಂದುವರಿಸಬಹುದು."},{"text":"ಯಾವುದೇ ಆಕ್ರಮಣಕಾರಿ ಕಾರ್ಯವಿಧಾನಗಳು ಇಲ್ಲಃ ಇದು ಡಿಜಿಟಲ್ ಮತ್ತು ಕೆಲಸದ ಹರಿವಿನ ನಾವೀನ್ಯತೆ ಅಧ್ಯಯನವಾಗಿದೆ; ಸಂಶೋಧನಾ ಘಟಕದಲ್ಲಿ ಯಾವುದೇ ಪ್ರಾಯೋಗಿಕ ಔಷಧಿಗಳು ಅಥವಾ ಆಕ್ರಮಣಕಾರಿ ಚಿಕಿತ್ಸೆಗಳು ಒಳಗೊಂಡಿಲ್ಲ."}]},{"heading":"ಭಾಗವಹಿಸುವಿಕೆ","paragraphs":[{"text":"ವೈಯಕ್ತಿಕ ಪ್ರಯೋಜನಃ ವೈಯಕ್ತಿಕ ಭಾಗವಹಿಸುವವರಿಗೆ ಯಾವುದೇ ನೇರ ಪ್ರಯೋಜನವಿಲ್ಲ. ಆದಾಗ್ಯೂ, ನಿಮ್ಮ ಸ್ಕ್ರೀನಿಂಗ್ ತಂತ್ರವನ್ನು ತಿಳಿಸಲು ಸಹಾಯ ಮಾಡುವ ಅಪಾಯದ ಮುನ್ಸೂಚನೆಯನ್ನು ನೀವು ಸ್ವೀಕರಿಸುತ್ತೀರಿ."},{"text":"ಸಮಾಜ ಪ್ರಯೋಜನಃ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆಯು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ನ ಆರಂಭಿಕ ಪತ್ತೆ ಮತ್ತು ಭಾರತದಾದ್ಯಂತ ಮಹಿಳೆಯರಿಗೆ ಉತ್ತಮ ಸಂಪನ್ಮೂಲ ಹಂಚಿಕೆ ಸೇರಿದಂತೆ ವೈಜ್ಞಾನಿಕ ಪ್ರಯೋಜನಗಳಿಗೆ ಕೊಡುಗೆ ನೀಡುತ್ತದೆ."}]},{"heading":"ಈ ಅಧ್ಯಯನದಲ್ಲಿ ನನ್ನ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಗೌಪ್ಯವಾಗಿ ಇಡಲಾಗುತ್ತದೆಯೇ?","paragraphs":[{"text":"ಹೌದು. ಈ ಅಧ್ಯಯನದ ಸಮಯದಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾದ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಗೌಪ್ಯವಾಗಿಡಲಾಗುತ್ತದೆ. ಎಲ್ಲಾ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಅನ್ವಯವಾಗುವ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ನಿಯಮಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಅನಾಮಧೇಯಗೊಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ. ಅಧಿಕೃತ ಸಂಶೋಧನಾ ತಂಡದ ಸದಸ್ಯರಿಗೆ ಮಾತ್ರ ಡೇಟಾಕ್ಕೆ ಪ್ರವೇಶವಿದೆ, ಮತ್ತು ನಿಮ್ಮ ಸ್ಪಷ್ಟ ಒಪ್ಪಿಗೆಯಿಲ್ಲದೆ ಯಾವುದೇ ವೈಯಕ್ತಿಕವಾಗಿ ಗುರುತಿಸಬಹುದಾದ ಮಾಹಿತಿಯನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿಗಳೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ. ಅಧ್ಯಯನದ ಫಲಿತಾಂಶಗಳನ್ನು ಒಟ್ಟು ರೂಪದಲ್ಲಿ ಮಾತ್ರ ಪ್ರಸ್ತುತಪಡಿಸಲಾಗುತ್ತದೆ, ವೈಯಕ್ತಿಕ ಭಾಗವಹಿಸುವವರನ್ನು ಗುರುತಿಸಲಾಗುವುದಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು."},{"text":"ಒಟ್ಟು ದತ್ತಾಂಶದ ಸುಮಾರು 20% ರಷ್ಟು, ತಿರುವು ತರದ ಅನಾಮಧೇಯ ರೀತಿಯಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುವುದು, ಇದು AI ಅಲ್ಗಾರಿದಮ್ಗಳ ಮೌಲ್ಯಮಾಪನಕ್ಕಾಗಿ TANUH ನ ಬ್ಯಾಂಚ್ಮಾರ್ಕಿಂಗ್ ಮತ್ತು ಮುಕ್ತ ದತ್ತಾಂಶ ಉಪಕ್ರಮದ ಭಾಗವಾಗಿರುತ್ತದೆ. ಸಂಗ್ರಹಿಸಿದ ದತ್ತಾಂಶವನ್ನು ಭವಿಷ್ಯದ ಸಂಶೋಧನೆಯಲ್ಲಿ ಬಳಸಲಾಗುತ್ತದೆ, ಇದರಲ್ಲಿ ಇತರ ಅಡಿಪಾಯ ಮಾದರಿಗಳ ಅಭಿವೃದ್ಧಿ ಸೇರಿವೆ."}]},{"heading":"ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ ಎಂದರೇನು?","paragraphs":[{"text":"ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿರಾಕರಿಸಬಹುದು ಅಥವಾ ಪೆನಾಲ್ಟಿ ಅಥವಾ ಪ್ರಯೋಜನಗಳ ನಷ್ಟವಿಲ್ಲದೆ ಸಮೀಕ್ಷೆಯನ್ನು ನಿಲ್ಲಿಸಬಹುದು."}]},{"heading":"ಸಂಶೋಧನೆಯಿಂದ ಉಂಟಾದ ಗಾಯಗಳಿಗೆ ಪರಿಹಾರ ಮತ್ತು ವೈದ್ಯಕೀಯ ಆರೈಕೆ ಇದೆಯೇ?","paragraphs":[{"text":"ಪರಿಹಾರಃ ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಿದ್ದಕ್ಕಾಗಿ ನಿಮಗೆ ಹಣ ನೀಡಲಾಗುವುದಿಲ್ಲ. ಇದು ಕನಿಷ್ಠ/ಅಪಾಯವಿಲ್ಲದ ಅಧ್ಯಯನವಾದ್ದರಿಂದ ಯಾವುದೇ ಪರಿಹಾರವನ್ನು ನೀಡಲಾಗುವುದಿಲ್ಲ."},{"text":"ಗಾಯಃ ಇದು ಯಾವುದೇ ಆಕ್ರಮಣಕಾರಿ ಹಸ್ತಕ್ಷೇಪಗಳನ್ನು ಒಳಗೊಂಡಿರುವ ಸಮೀಕ್ಷೆ/ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಆಧಾರಿತ ಸ್ಕ್ರೀನಿಂಗ್ ಅಧ್ಯಯನವಾದ್ದರಿಂದ, ಗಾಯಕ್ಕೆ ಯಾವುದೇ ವೈದ್ಯಕೀಯ ಚಿಕಿತ್ಸೆ ಅಥವಾ ಪರಿಹಾರವನ್ನು ಯೋಜಿಸಲಾಗಿಲ್ಲ."},{"text":"ವೆಚ್ಚಗಳುಃ ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿಮಗೆ ಯಾವುದೇ ವೆಚ್ಚವಿಲ್ಲ."}]},{"heading":"ಸಂಶೋಧನೆಯ ಫಲಿತಾಂಶಗಳ ಬಗ್ಗೆ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ಈ ಸಂಶೋಧನಾ ಅಧ್ಯಯನದ ಫಲಿತಾಂಶಗಳನ್ನು AI ಶಕ್ತಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಉಪಕರಣವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ಮತ್ತು ಮೌಲ್ಯೀಕರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ. ಸಂಶೋಧನೆಗಳನ್ನು ಸಹೋದ್ಯೋಗಿಗಳ ಪರಿಶೀಲಿಸಿದ ವೈಜ್ಞಾನಿಕ ನಿಯತಕಾಲಿಕಗಳಲ್ಲಿ ಪ್ರಕಟಿಸಬಹುದು, ಶೈಕ್ಷಣಿಕ ಸಮ್ಮೇಳನಗಳಲ್ಲಿ ಪ್ರಸ್ತುತಪಡಿಸಬಹುದು ಮತ್ತು ಭಾರತದಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಅಭ್ಯಾಸಗಳನ್ನು ಸುಧಾರಿಸಲು ಆರೋಗ್ಯ ಸಂಸ್ಥೆಗಳು ಮತ್ತು ನೀತಿ ನಿರ್ಮಾಪಕರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಬಹುದು. ಪ್ರಕಟವಾದ ಎಲ್ಲಾ ಫಲಿತಾಂಶಗಳು ವೈಯಕ್ತಿಕ ಗುರುತಿಸುವಿಕೆಯಿಲ್ಲದೆ ಒಟ್ಟು ರೂಪದಲ್ಲಿರುತ್ತವೆ."}]},{"heading":"ಸಂಶೋಧನೆಯನ್ನು ಯಾರು ಸಂಘಟಿಸುತ್ತಾರೆ ಮತ್ತು ಹಣಕಾಸು ಒದಗಿಸುತ್ತಾರೆ?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ಈ ಅಧ್ಯಯನವನ್ನು ಯಾರು ಪರಿಶೀಲಿಸಿದ್ದಾರೆ?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಾನು ಯಾರನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು?","paragraphs":[{"text":"ಸಂಪರ್ಕ ವಿವರಗಳುಃ ಡಾ. ಅಶ್ವಿನ್ ರಾಯಜ್ ಕುಮಾರ್, ಪ್ರಾಜೆಕ್ಟ್ ಮ್ಯಾನೇಜರ್"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ನೀವು ಅಧ್ಯಯನದ ಬಗ್ಗೆ ಸ್ವತಂತ್ರವಾಗಿರುವ ಯಾರೊಂದಿಗೂ ಮಾತನಾಡಲು ಬಯಸಿದರೆ, ನೀವು ಈ ಕೆಳಗಿನವರನ್ನು ಸಂಪರ್ಕಿಸಬಹುದುಃ"},{"text":"ಸಾಂಸ್ಥಿಕ ನೀತಿ ಸಮಿತಿ (ಐಇಸಿ)"},{"text":"ಹೆಸರುಃ ಡಾ. ಶ್ರೀ ವಿದ್ಯಾ ಜಗಡಿಶ್, ಐಇಸಿ ಕಾರ್ಯದರ್ಶಿ, ಟ್ಯಾನುಹ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಿದ್ದಕ್ಕಾಗಿ ಧನ್ಯವಾದಗಳು!"}]}],"checkboxLabel":"ನಾನು ಭಾಗವಹಿಸುವವರ ಮಾಹಿತಿ ಚೀಟ್ ಅನ್ನು ಓದಿದ್ದೇನೆ ಮತ್ತು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ಸ್ವಯಂಪ್ರೇರಣೆಯಿಂದ ಒಪ್ಪುತ್ತೇನೆ.","buttonText":"ಒಪ್ಪಿಕೊಳ್ಳು ಮತ್ತು ಮುಂದುವರಿಸು"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'ml','{"title":"പങ്കാളികളുടെ വിവര ഷീറ്റ്","headernames":{"studyTitle":"പഠന ശീർഷകം","sponsor":"സംഘാടകനും ധനസഹായവും","iecApproval":"ധാർമികതയുടെ അവലോകനം"},"header":{"studyTitle":"ഇന്ത്യയിലെ ജനസംഖ്യയ്ക്കായി സ്തനാർബുദം പ്രവചിക്കാനുള്ള AI പ്രാപ്തമായ ഉപകരണം വികസിപ്പിക്കുക","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ഈ പഠനത്തെക്കുറിച്ച്","paragraphs":[{"text":"ആരോഗ്യ പരിരക്ഷയ്ക്കായി ഇന്ത്യൻ ഐ. ഐ. പരിഹാരങ്ങൾ വികസിപ്പിക്കുന്നതിനുള്ള വിദ്യാഭ്യാസ മന്ത്രാലയത്തിന്റെ ധനസഹായമുള്ള പദ്ധതിയുടെ ഭാഗമാണ് ഈ പഠനം. ഇന്ത്യയിലെ സ്ത്രീകളുടെ പ്രയോജനത്തിനായി സ്തനാർബുദം പഠനം മുന്നോട്ട് കൊണ്ടുപോകുന്നതിനുള്ള ഈ ശ്രമത്തിന്റെ സുപ്രധാന ഭാഗമായതിന് നന്ദി. ഇന്ത്യയിലുടനീളം സ്ത്രീകളുടെ പ്രയോജനത്തിനായി ഐ. ഐ. നടത്തുക. ഇന്ത്യയിൽ ഐ. ഐ. പ്രവർത്തിക്കുക."}]},{"heading":"പഠനത്തിന്റെ ഉദ്ദേശ്യം എന്താണ്?","paragraphs":[{"text":"ഇന്ത്യയിലെ ജനസംഖ്യയ്ക്കായി സ്തനാർബുദം പ്രവചിക്കാനുള്ള AI പ്രാപ്തമായ ഉപകരണം വികസിപ്പിക്കുക"}]},{"heading":"എന്തിന് എന്നെ തെരഞ്ഞെടുത്തു?","paragraphs":[{"text":"നിങ്ങൾ മാംമോഗ്രാഫിക്ക് അല്ലെങ്കിൽ ഒരു പതിവ് മാംമോഗ്രാഫിക്ക് വിധേയനാകുന്നതിനാൽ AI പ്രാപ്തമാക്കിയ സ്റ്റെയിൻ കാൻസർ സ്ക്രീനിംഗ് ഉപകരണങ്ങളുടെ പഠനത്തിന് സംഭാവന നൽകാൻ നിങ്ങളെ തിരഞ്ഞെടുത്തു. ഏതാനും ചോദ്യാവലികളിലൂടെ സ്റ്റെയിൻ കാൻസർ സാധ്യത തിരിച്ചറിയാൻ സഹായിക്കുന്ന ഒരു AI പ്രാപ്തമാക്കിയ സ്റ്റെയിൻ കാൻസർ സ്ക്രീനിംഗ് ഉപകരണമാണ് ഞങ്ങൾ വികസിപ്പിക്കുന്നത്."}]},{"heading":"ഞാന് പങ്കെടുക്കേണ്ടതാണോ?","paragraphs":[{"text":"നിങ്ങളുടെ പങ്കാളിത്തം പൂർണമായും സ്വമേധയാ ആണ്. പഠനത്തില് പങ്കെടുക്കാന് നിങ്ങള് ക്ക് സാധിക്കാതെ വരും. നിങ്ങളുടെ സാധാരണ പ്രവര് ത്തനങ്ങള് തുടര് ന്നുപോകും."}]},{"heading":"പഠനത്തിന് റെ ഫലമെന്താണ്? പങ്കെടുക്കാൻ നിങ്ങൾ സമ്മതിച്ചാൽ താഴെ പറയുന്ന കാര്യങ്ങൾ സംഭവിക്കും.","paragraphs":[{"text":"സർവേഃ നിങ്ങളുടെ ജനസംഖ്യാശാസ്ത്രത്തെക്കുറിച്ചും ആരോഗ്യ ചരിത്രത്തെക്കുറിച്ചും ജീവിതശൈലിയെക്കുറിച്ചും കുടുംബത്തിലെ കാൻസർ രോഗത്തെക്കുറിച്ചും ഒരു തവണയോ ഒരു ചോദ്യാവലി പൂരിപ്പിക്കാൻ നിങ്ങളോട് ആവശ്യപ്പെടും."},{"text":"റിസ്ക് പ്രവചനംഃ സർവേയുടെ അവസാനം നിങ്ങൾക്ക് ഉടനടി സ്തനാർബുദം ഉണ്ടാകുന്നതിനെക്കുറിച്ച് പ്രവചനം നൽകും (നിങ്ങൾക്ക് സാധാരണമായതോ ഉയർന്നതോ ആയ അപകടസാധ്യത ഉണ്ടോ എന്ന് തിരിച്ചറിയുക)."},{"text":"മാർഗ്ഗനിർദ്ദേശംഃ അപകടസാധ്യതയുടെ അടിസ്ഥാനത്തിൽ നിങ്ങൾക്ക് മാർഗനിർദ്ദേശം ലഭിക്കും. ഉയർന്ന അപകടസാധ്യതയുണ്ടെന്ന് കണ്ടെത്തിയാൽ, നിങ്ങളെ മാംമോഗ്രഫിക്ക് റഫർ ചെയ്യാം. സാധാരണ / കുറഞ്ഞ അപകടസാധ്യതയുള്ളവരാണെങ്കിൽ, പതിവ് പരിശോധന പ്രോട്ടോക്കോളുകൾ തുടരാൻ നിങ്ങളോട് ആവശ്യപ്പെടും."},{"text":"ഡാറ്റ ഉപയോഗം: നിങ്ങളില് നിന്നും ആശുപത്രിയില് നിന്നും ശേഖരിച്ച ഡാറ്റ ഇന്ത്യയിലെ സ്ത്രീകളില് സ്തനാർബുദം വരാനുള്ള സാധ്യത മെച്ചപ്പെടുത്താന് കൃത്രിമ ബുദ്ധി (AI) മാതൃക പരിശീലിപ്പിക്കുന്നതിന് ഉപയോഗിക്കും."}]},{"heading":"ഞാന് പങ്കെടുക്കുകയാണെങ്കില് എന് റെ അവസ്ഥയെന്ത്?","paragraphs":[{"text":"വ്യക്തിഗതമായ അപകടസാധ്യതാ പ്രവചനങ്ങള് ഭാവിയില് ആരോഗ്യ നിരീക്ഷണത്തില് സാധ്യമായ സ്തനാർബുദ ലക്ഷണങ്ങള് ക്കും നിങ്ങളുടെ വ്യക്തിഗത അപകടസാധ്യതാ ഘടകങ്ങള് ക്കും കൂടുതൽ ബോധവാന്മാരാകാന് നിങ്ങളെ സഹായിക്കും."}]},{"heading":"ഞാനെന്ത് ചെയ്യണം?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"പങ്കെടുക്കുന്നതിലെ അപകടങ്ങള് എന്തൊക്കെയാണ്?","paragraphs":[{"text":"ഈ ഗവേഷണ പഠനത്തില് പങ്കെടുക്കുന്നതില് വലിയ അപകടങ്ങളൊന്നും ഉണ്ടാവില്ല."},{"text":"അപകടസാധ്യതയില്ല / മിനിമംഃ ഈ പഠനം \\"അപകടസാധ്യതയില്ല / മിനിമം\\" എന്ന് കണക്കാക്കപ്പെടുന്നു."},{"text":"സ്വകാര്യതഃ സ്വകാര്യതയെ സംബന്ധിച്ചിടത്തോളം അപൂർവമായ ഒരു അപകടസാധ്യതയുണ്ട്, പക്ഷേ ഇത് കുറയ്ക്കുന്നു, കാരണം വ്യക്തിപരമായി തിരിച്ചറിയാവുന്ന വിവരങ്ങൾ ഞങ്ങൾ ശേഖരിക്കുന്നില്ല, കൂടാതെ ഡാറ്റ അജ്ഞാതമായി പിടിച്ചെടുക്കുന്നു."},{"text":"സ്വമേധയാഃ ഈ ചോദ്യാവലി പൂർണമായും സ്വമേധയാ ആണ്; നിങ്ങൾക്ക് താല്പര്യമില്ലെങ്കിൽ, പകരം ക്ലിനിക്കിൽ പതിവ് പരിചരണം തേടാം."},{"text":"ആക്രമണാത്മക നടപടിക്രമങ്ങളില്ലഃ ഇത് ഡിജിറ്റൽ, വർക്ക്ഫ്ലോ നവീകരണ പഠനമാണ്; പരീക്ഷണാത്മക മരുന്നുകളോ ആക്രമണാത്മക ചികിത്സകളോ ഗവേഷണ ഘടകത്തിൽ ഉൾപ്പെട്ടിട്ടില്ല."}]},{"heading":"പങ്കെടുക്കുന്നതിൽനിന്ന് ലഭിക്കുന്ന നേട്ടങ്ങൾ എന്തൊക്കെയാണ്?","paragraphs":[{"text":"വ്യക്തിപരമായ പ്രയോജനംഃ വ്യക്തിഗത പങ്കാളികൾക്ക് നേരിട്ടുള്ള പ്രയോജനം ഉണ്ടാകില്ല. എന്നിരുന്നാലും, നിങ്ങളുടെ സ്ക്രീനിംഗ് തന്ത്രത്തെ അറിയിക്കുന്നതിന് സഹായിക്കുന്ന ഒരു റിസ്ക് പ്രവചനം നിങ്ങൾക്ക് ലഭിക്കും."},{"text":"സാമൂഹിക പ്രയോജനംഃ നിങ്ങളുടെ പങ്കാളിത്തം ശാസ്ത്രീയ പ്രയോജനങ്ങൾക്ക് സംഭാവന ചെയ്യും."}]},{"heading":"ഈ പഠനത്തില് പങ്കെടുക്കുന്നതില് എന്റെ പങ്കാളിത്തം രഹസ്യമായി സൂക്ഷിക്കപ്പെടുമോ?","paragraphs":[{"text":"അതെ. ഈ പഠനത്തിനിടെ ശേഖരിക്കുന്ന എല്ലാ വിവരങ്ങളും കർശനമായി രഹസ്യാത്മകമായി സൂക്ഷിക്കും. ബാധകമായ ഡാറ്റാ പരിരക്ഷണ നിയമങ്ങൾക്കനുസൃതമായി എല്ലാ സ്വകാര്യ ഡാറ്റയും അജ്ഞാതമാക്കുകയും സുരക്ഷിതമായി സൂക്ഷിക്കുകയും ചെയ്യും. അംഗീകൃത ഗവേഷണ സംഘത്തിലെ അംഗങ്ങൾക്ക് മാത്രമേ ഡാറ്റയിലേക്ക് പ്രവേശനം ലഭിക്കുകയുള്ളൂ, നിങ്ങളുടെ വ്യക്തമായ സമ്മതമില്ലാതെ വ്യക്തിപരമായി തിരിച്ചറിയാവുന്ന വിവരങ്ങളൊന്നും മൂന്നാം കക്ഷികളുമായി പങ്കിടില്ല. പഠന ഫലങ്ങൾ സംയോജിത രൂപത്തിൽ മാത്രമേ അവതരിപ്പിക്കാവൂ, അതിനാൽ വ്യക്തിഗത പങ്കാളികളെ തിരിച്ചറിയാൻ കഴിയില്ലെന്ന് ഉറപ്പാക്കുന്നു."},{"text":"അപ്രത്യക്ഷമായ അജ്ഞാത രീതിയില് ശേഖരിച്ച മൊത്തം ഡാറ്റയുടെ 20% ത്തിലേറെയും AI അല് ഗോരിതങ്ങളുടെ വിലയിരുത്തലിന് വേണ്ടി TANUH യുടെ ബെഞ്ച്മാര് ക്കിങ്, ഓപ്പൺ ഡാറ്റ സംരംഭത്തിന്റെ ഭാഗമാകും. ശേഖരിച്ച ഡാറ്റ ഭാവി ഗവേഷണത്തില് ഉപയോഗിക്കും."}]},{"heading":"സ്വമേധയാ പങ്കെടുക്കുക എന്നതു എന്താണ്?","paragraphs":[{"text":"നിങ്ങളുടെ പങ്കാളിത്തം പൂർണമായും സ്വമേധയാ ആണ്. നിങ്ങൾക്ക് ഏതു സമയത്തും പനാൽസിസിസിനും ആനുകൂല്യങ്ങൾക്കും നഷ്ടപ്പെടാതെ പങ്കെടുക്കാൻ വിസമ്മതിക്കാനോ അല്ലെങ്കിൽ സർവേ അവസാനിപ്പിക്കാനോ കഴിയും."}]},{"heading":"ഗവേഷണവുമായി ബന്ധപ്പെട്ട പരിക്കിന് എന്തെങ്കിലും നഷ്ടപരിഹാരവും വൈദ്യസഹായവും ഉണ്ടോ?","paragraphs":[{"text":"നഷ്ടപരിഹാരംഃ ഈ പഠനത്തില് പങ്കെടുത്താല് നിങ്ങള് ക്ക് പണം ലഭിക്കില്ല. ഇത് ഒരു മിനിമല് / റിസ്ക് രഹിത പഠനമാണെങ്കില് യാതൊരു നഷ്ടപരിഹാരവും വാഗ്ദാനം ചെയ്യപ്പെടുന്നില്ല."},{"text":"പരിക്കുകൾഃ ഇത് ഒരു സർവേ/AI അടിസ്ഥാനമാക്കിയുള്ള സ്ക്രീനിംഗ് പഠനമാണു്. അതിൽ ആക്രമണാത്മക ഇടപെടലുകളില്ല. പരിക്കുകൾക്ക് ചികിത്സയോ നഷ്ടപരിഹാരമോ നൽകാനാവില്ല."},{"text":"ചെലവുകൾഃ ഈ പഠനത്തില് പങ്കെടുക്കാന് നിങ്ങള് ക്ക് യാതൊരു ചെലവുമില്ല."}]},{"heading":"ഗവേഷണ പഠനത്തിന്റെ ഫലങ്ങള് ക്ക് എന്ത് സംഭവിക്കും?","paragraphs":[{"text":"ഈ ഗവേഷണ പഠനത്തിന്റെ ഫലങ്ങൾ ഒരു AI പ്രാപ്തമാക്കിയ ബ്രെസ്റ്റ് കാൻസർ റിസ്ക് പ്രവചന ഉപകരണത്തിന്റെ വികസനത്തിനും പരിശോധനയ്ക്കും ഉപയോഗിക്കും. കണ്ടെത്തലുകൾ സമപ്രായ ശാസ്ത്രീയ ജേണലുകളിൽ പ്രസിദ്ധീകരിക്കാനും അക്കാദമിക് സമ്മേളനങ്ങളിൽ അവതരിപ്പിക്കാനും ഇന്ത്യയിലെ ബ്രെസ്റ്റ് കാൻസർ സ്ക്രീനിംഗ് രീതികൾ മെച്ചപ്പെടുത്തുന്നതിനായി ആരോഗ്യ സംരക്ഷണ സ്ഥാപനങ്ങളുമായും നയരൂപകരുമായും പങ്കിടാനും കഴിയും. പ്രസിദ്ധീകരിച്ച എല്ലാ ഫലങ്ങളും വ്യക്തിഗത തിരിച്ചറിയൽ ഇല്ലാതെ സംയോജിത രൂപത്തിൽ ആയിരിക്കും."}]},{"heading":"ആരാണ് ഗവേഷണം സംഘടിപ്പിക്കുകയും ധനസഹായം നല് കുകയും ചെയ്യുന്നത്?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ആര് ഈ പഠനം അവലോകനം ചെയ്തു?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"കൂടുതൽ വിവരങ്ങള് ക്കായി ഞാന് ആര് ക്ക് ബന്ധപ്പെടാം?","paragraphs":[{"text":"ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾഃ ഡോ. അശ്വിന് റാജ്കുമാർ, പദ്ധതി മേധാവി"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"പഠനത്തില് നിന്ന് സ്വതന്ത്രമായ ഒരാളുമായി സംസാരിക്കണമെങ്കില് താഴെ പറയുന്നവയില് ബന്ധപ്പെടാംഃ"},{"text":"സ്ഥാപനപരമായ ധാർമിക സമിതി (ഐ. ഇ. സി.)"},{"text":"പേര്ഃ ഡോ. ശ്രീ വിദ്യ ജഗാദിഷ്, ഐ. ഇ. സി സെക്രട്ടറി, താനു"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"പഠനത്തില് പങ്കെടുത്തതിന് നന്ദി!"}]}],"checkboxLabel":"പങ്കെടുക്കുന്നവരുടെ വിവരപത്രിക വായിക്കുകയും മനസ്സിലാക്കുകയും ചെയ്ത ഞാന് ഈ പഠനത്തില് പങ്കെടുക്കാന് സ്വമേധയാ സമ്മതിക്കുന്നു.","buttonText":"സ്വീകരിക്കുക & തുടരുക"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'mr','{"title":"भागधारकांची माहिती पत्रक","headernames":{"studyTitle":"अभ्यास शीर्षक","sponsor":"आयोजक आणि निधी","iecApproval":"नैतिकता पुनरावलोकन"},"header":{"studyTitle":"भारतीय लोकसंख्येसाठी एआय सक्षम स्तनाचा कर्करोगाचा धोका अंदाज साधनाचा विकास","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"या अभ्यासाबद्दल","paragraphs":[{"text":"आरोग्यसेवेसाठी भारतीय एआय सोल्यूशन्स विकसित करण्यासाठी शिक्षण मंत्रालयाच्या निधीने आयोजित केलेल्या प्रकल्पाचा हा भाग आहे. भारतीय विज्ञान संस्थेद्वारे आयोजित केलेल्या टॅनुह फाउंडेशन ही एक सेक्शन 8 कंपनी आहे. स्तन कर्करोग संशोधनात या महत्त्वपूर्ण राष्ट्रीय उपक्रमाचे नेतृत्व करण्यास अभिमान आहे. आरोग्य परिणामांमध्ये सुधारणा करण्यासाठी लवकर, डेटा-आधारित शोधणे आवश्यक आहे हे ओळखून. भारतातील महिलांच्या फायद्यासाठी स्तन कर्करोग अभ्यास पुढे नेण्यासाठी या प्रयत्नाचा एक आवश्यक भाग असल्याबद्दल आम्ही आपल्या सहभागाचे कौतुक करतो आणि धन्यवाद."}]},{"heading":"अभ्यास करण्याचे उद्दिष्ट काय आहे?","paragraphs":[{"text":"भारतीय लोकसंख्येसाठी एआय सक्षम स्तनाचा कर्करोगाचा धोका अंदाज साधनाचा विकास"}]},{"heading":"मला का निवडले गेले?","paragraphs":[{"text":"तुम्हाला एआय सक्षम स्तनाचा कर्करोग तपासणी साधनांच्या अभ्यासासाठी पाठिंबा देण्यासाठी निवडण्यात आला आहे कारण तुम्हाला मॅमोग्राफीसाठी किंवा नियमित मॅमोग्राफीसाठी संदर्भित करण्यात आला आहे. आम्ही एआय सक्षम स्तनाचा कर्करोग तपासणी साधनाचा विकास करत आहोत जे काही प्रश्नावलीद्वारे स्तनाचा कर्करोगाचा धोका ओळखण्यास सक्षम करते."}]},{"heading":"मी सहभागी व्हायला हवे का?","paragraphs":[{"text":"तुम्ही या अभ्यासात सहभागी न होण्याचा निर्णय घेऊ शकता आणि तुमच्या सामान्य पद्धतीप्रमाणेच पुढे जाऊ शकता."}]},{"heading":"अभ्यासात काय घडेल तुम्ही सहभागी होण्यास सहमत असाल तर खालील गोष्टी घडतील?","paragraphs":[{"text":"सर्वेक्षण: तुम्हाला तुमच्या लोकसंख्या, आरोग्याच्या इतिहास, जीवनशैली आणि कर्करोगाच्या कौटुंबिक इतिहासाविषयी एकवेळचा प्रश्नावली (टॅब्लेट/डिजिटल डिव्हाइसवर) भरावा लागेल."},{"text":"जोखीम अंदाज: सर्वेक्षण संपल्यावर तुम्हाला स्तन कर्करोगाचा धोका त्वरित अंदाज येईल (तुम्हाला सामान्य किंवा अधिक धोका आहे का हे ओळखून)."},{"text":"मार्गदर्शनः जोखीम पातळीवर आधारित तुम्हाला मार्गदर्शन मिळेल. जर तुम्हाला अधिक धोका असल्याचे आढळले तर तुम्हाला मॅमोग्राफीसाठी संदर्भित केले जाऊ शकते. जर तुम्हाला सामान्य/कमी धोका असेल तर नियमित तपासणी प्रोटोकॉल सुरू ठेवण्यास सांगितले जाईल."},{"text":"डेटा वापर: तुमच्याकडून आणि रुग्णालयातून गोळा केलेला डेटा भारतीय महिलांमध्ये स्तनाचा कर्करोग होण्याचा धोका अधिक चांगल्या प्रकारे अंदाज लावण्यासाठी कृत्रिम बुद्धिमत्तेच्या (AI) मॉडेलचे प्रशिक्षण घेण्यासाठी वापरला जाईल."}]},{"heading":"मी भाग घेतला तर काय होईल?","paragraphs":[{"text":"वैयक्तिकृत धोका अंदाज तुम्हाला स्तन कर्करोगाच्या संभाव्य लक्षणांची अधिक जाणीव ठेवण्यास आणि भविष्यातील आरोग्याची देखरेख करण्यासाठी तुमच्या वैयक्तिक जोखीम घटकांविषयी अधिक जागरूक होण्यास मदत करेल."}]},{"heading":"मी काय करावे?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"यात सहभागी होण्याचे कोणते धोके आहेत?","paragraphs":[{"text":"या संशोधन अभ्यासात सहभागी होणे हा कोणताही मोठा धोका नाही."},{"text":"नाही/ किमान धोकाः हा अभ्यास \\"कोणत्याही/ किमान जोखीम\\" मानला जातो."},{"text":"गोपनीयता: गोपनीयता संबंधित एक दुर्मिळ धोका आहे, परंतु हे कमी केले जाते कारण आम्ही वैयक्तिकरित्या ओळखण्यायोग्य माहिती गोळा करत नाही आणि डेटा अनामिकरित्या गोळा केला जातो."},{"text":"स्वेच्छेने: हा प्रश्नावली पूर्णपणे स्वेच्छेने आहे; जर तुम्हाला स्वारस्य नसेल तर तुम्ही नियमित क्लिनिकमध्ये उपचार घेऊ शकता."},{"text":"कोणतीही आक्रमक प्रक्रिया नाहीः हा एक डिजिटल आणि वर्कफ्लो नावीन्यपूर्ण अभ्यास आहे; संशोधन घटकामध्ये कोणतेही प्रयोगात्मक औषधे किंवा आक्रमक उपचारांचा समावेश नाही."}]},{"heading":"सहभाग घेताना काय फायदे मिळू शकतात?","paragraphs":[{"text":"वैयक्तिक फायदा: वैयक्तिक सहभागींसाठी कोणताही थेट फायदा होण्याची शक्यता नाही. तथापि, तुम्हाला जोखीम अंदाज मिळतो जो तुमच्या तपासणी धोरणाला सूचित करण्यास मदत करू शकतो."},{"text":"सामाजिक लाभ: आपल्या सहभागाने वैज्ञानिक लाभ मिळतील, ज्यात स्तन कर्करोगाचा लवकर निदान वाढेल आणि भारतातील महिलांसाठी अधिक चांगले संसाधने वाटप केले जातील."}]},{"heading":"या अभ्यासामध्ये माझे सहभाग गुप्त ठेवला जाईल का?","paragraphs":[{"text":"या अभ्यासात गोळा केलेली सर्व माहिती पूर्णपणे गोपनीय राहील. सर्व वैयक्तिक डेटा लागू डेटा संरक्षण नियमांच्या अनुषंगाने अनामिक केले जातील आणि सुरक्षितपणे संग्रहित केले जातील. केवळ अधिकृत संशोधन कार्यसंघाच्या सदस्यांनाच डेटामध्ये प्रवेश मिळेल आणि आपल्या स्पष्ट संमतीशिवाय कोणतीही वैयक्तिकरित्या ओळखण्यायोग्य माहिती तृतीय पक्षाशी सामायिक केली जाणार नाही. अभ्यासातील निकाल केवळ एकत्रित स्वरूपात सादर केले जातील, जेणेकरून वैयक्तिक सहभागींची ओळख होऊ शकत नाही."},{"text":"एकूण डेटापैकी सुमारे 20% अपरिवर्तनीयपणे अनामिक पद्धतीने गोळा केलेले हे AI अल्गोरिदमच्या मूल्यांकनासाठी TANUH च्या बेंचमार्किंग आणि ओपन डेटा पुढाकारात समाविष्ट केले जाईल. गोळा केलेले डेटा भविष्यातील संशोधनात वापरले जातील, ज्यात इतर पायाभूत मॉडेल विकसित करणे समाविष्ट आहे."}]},{"heading":"स्वेच्छेने सहभाग म्हणजे काय?","paragraphs":[{"text":"तुम्ही कोणत्याही वेळी न भरता किंवा लाभ गमावल्याशिवाय सर्वेक्षण करण्यास नकार देऊ शकता किंवा थांबवू शकता."}]},{"heading":"संशोधन-संबंधित जखमांसाठी कोणतेही नुकसान भरपाई आणि वैद्यकीय उपचार आहेत का?","paragraphs":[{"text":"भरपाई: या अभ्यासात सहभागी झाल्याबद्दल तुम्हाला पैसे दिले जात नाहीत. या अभ्यासात कमीतकमी/जोखीम नसलेल्या अभ्यासात सहभागी झाल्यामुळे कोणतीही भरपाई देण्यात येत नाही."},{"text":"जखम: हा एक सर्वेक्षण/एआय आधारित स्क्रीनिंग अभ्यास असून त्यात कोणत्याही प्रकारची आक्रमक हस्तक्षेप नाही, त्यामुळे जखमांसाठी वैद्यकीय उपचार किंवा भरपाईची योजना नाही."},{"text":"खर्च: या अभ्यासात सहभागी होण्यासाठी तुम्हाला कोणतेही शुल्क नाही."}]},{"heading":"या संशोधनाच्या निकालांचे काय होईल?","paragraphs":[{"text":"या संशोधन अभ्यासाचे परिणाम एआय सक्षम स्तनाचा कर्करोग अंदाज साधनाचा विकास आणि सत्यापन करण्यासाठी वापरले जातील. निष्कर्ष पीअर-रीव्ह्यू केलेल्या वैज्ञानिक जर्नल्समध्ये प्रकाशित केले जाऊ शकतात, शैक्षणिक परिषदांमध्ये सादर केले जाऊ शकतात आणि आरोग्य संस्था आणि धोरण निर्मात्यांसह शेअर केले जाऊ शकतात."}]},{"heading":"या संशोधनाचे आयोजन आणि वित्तपुरवठा कोण करत आहे?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"या अभ्यासाचा आढावा कोणी घेतला?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"अधिक माहितीसाठी मी कोणाशी संपर्क साधू शकतो?","paragraphs":[{"text":"संपर्क तपशील: डॉ. अश्विन राजकुमार, प्रकल्प व्यवस्थापक"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"जर तुम्हाला अभ्यासातून स्वतंत्र व्यक्तीशी बोलायचे असेल तर तुम्ही खालील व्यक्तीशी संपर्क साधू शकताः"},{"text":"संस्थागत नैतिकता समिती (आयईसी)"},{"text":"नाव: डॉ. श्री विद्या जगदीश, आयईसीचे सचिव, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"अभ्यासात सहभागी झाल्याबद्दल धन्यवाद!"}]}],"checkboxLabel":"मी सहभागी माहिती पत्रक वाचले आणि समजले आहे आणि स्वेच्छेने या अभ्यासात सहभागी होण्यास सहमत आहे.","buttonText":"स्वीकार आणि पुढे जा"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'or','{"title":"ଅଂଶଗ୍ରହଣକାରୀ ସୂଚନା ପତ୍ର","headernames":{"studyTitle":"ଅଧ୍ୟୟନ ନାମ","sponsor":"ସଂଗଠନ ଓ ପାଣ୍ଠି","iecApproval":"ଆଦର୍ଶର ସମୀକ୍ଷା"},"header":{"studyTitle":"ଭାରତୀୟ ଜନସଂଖ୍ୟା ପାଇଁ ଏକ AI ସକ୍ଷମ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣର ବିକାଶ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ଏହି ଅଧ୍ୟୟନ ବିଷୟରେ","paragraphs":[{"text":"ଏହି ଅଧ୍ୟୟନ ଶିକ୍ଷା ମନ୍ତ୍ରଣାଳୟ ଦ୍ୱାରା ଅର୍ଥପ୍ରାପ୍ତ ସ୍ୱାସ୍ଥ୍ୟସେବା ପାଇଁ ଭାରତୀୟ ଏଆଇ ସମାଧାନ ବିକଶିତ କରିବା ପ୍ରକଳ୍ପର ଅଂଶବିଶେଷ । ଭାରତୀୟ ବିଜ୍ଞାନ ପ୍ରତିଷ୍ଠାନ ଦ୍ୱାରା ଆୟୋଜିତ ଏକ ସେକ୍ସନ 8 କମ୍ପାନୀ ହେଉଛି TANUH ଫାଉଣ୍ଡେସନ୍ ଗର୍ବର ସହିତ ସ୍ତନ କର୍କଟ ଗବେଷଣା କ୍ଷେତ୍ରରେ ଏହି ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ଜାତୀୟ ପଦକ୍ଷେପକୁ ନେତୃତ୍ୱ ପ୍ରଦାନ କରୁଛି । ଏହା ସ୍ୱୀକାର କରୁଛି ଯେ ସ୍ୱାସ୍ଥ୍ୟ ଫଳାଫଳକୁ ଉନ୍ନତ କରିବା ପାଇଁ ଆଗୁଆ, ତଥ୍ୟ ଆଧାରିତ ଚିହ୍ନଟ ଅତ୍ୟନ୍ତ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ । ଆମେ ଆପଣଙ୍କ ଅଂଶଗ୍ରହଣକୁ ଗଭୀର ଭାବରେ ପ୍ରଶଂସା କରୁଛୁ ଏବଂ ସାରା ଭାରତରେ ମହିଳାମାନଙ୍କ ଲାଭ ପାଇଁ ସ୍ତନ କର୍କଟ ଅଧ୍ୟୟନକୁ ଆଗକୁ ବଢ଼ାଇବା ପାଇଁ ଏହି ପ୍ରୟାସର ଏକ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ଅଂଶ ହୋଇଥିବାରୁ ଧନ୍ୟବାଦ ଜଣାଉଛୁ । ଭାରତରେ ଏଆଇ ନିର୍ମାଣ କରନ୍ତୁ ଏବଂ ଭାରତ ପାଇଁ ଏଆଇ କାର୍ଯ୍ୟ କରନ୍ତୁ ।"}]},{"heading":"ଅଧ୍ୟୟନ କରିବାର ଉଦ୍ଦେଶ୍ୟ କ''ଣ?","paragraphs":[{"text":"ଭାରତୀୟ ଜନସଂଖ୍ୟା ପାଇଁ ଏକ AI ସକ୍ଷମ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣର ବିକାଶ"}]},{"heading":"ମୋତେ କାହିଁକି ବାଛିଲେ?","paragraphs":[{"text":"ଆପଣମାନେ ଏଆଇ ଦ୍ୱାରା ସକ୍ଷମ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଉପକରଣର ଅଧ୍ୟୟନ ପାଇଁ ଯୋଗଦାନ କରିବା ପାଇଁ ଚୟନ ହୋଇଛନ୍ତି କାରଣ ଆପଣଙ୍କୁ ମାମୋଗ୍ରାଫି କିମ୍ବା ରutine ମାମୋଗ୍ରାଫି ପାଇଁ ପଠାଯାଇଛି । ଆମେ ଏକ ଏଆଇ ଦ୍ୱାରା ସକ୍ଷମ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଉପକରଣ ବିକଶିତ କରୁଛୁ ଯାହା କିଛି ପ୍ରଶ୍ନପତ୍ର ମାଧ୍ୟମରେ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ଚିହ୍ନଟ କରିବାକୁ ସକ୍ଷମ କରେ ।"}]},{"heading":"ମୁଁ ଭାଗ ନେବି କି?","paragraphs":[{"text":"ଆପଣ ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନ ନେଇ ନିଜ ଅଭ୍ୟାସ ଜାରି ରଖିପାରିବେ।"}]},{"heading":"ଅଧ୍ୟୟନ ବେଳେ କ''ଣ ଘଟିବ?","paragraphs":[{"text":"ସର୍ଭେ: ଆପଣଙ୍କୁ ଏକ ଥର ପାଇଁ ଜନସଂଖ୍ୟା, ସ୍ୱାସ୍ଥ୍ୟଗତ ଇତିହାସ, ଜୀବନଶୈଳୀ ଏବଂ କ୍ୟାନସର ସମ୍ବନ୍ଧୀୟ ଏକ ପ୍ରଶ୍ନପତ୍ର (ଟ୍ୟାବଲେଟ୍/ଡିଜିଟାଲ ଉପକରଣରେ) ପୂରଣ କରିବାକୁ କୁହାଯିବ ।"},{"text":"ବିପଦ ପୂର୍ବାନୁମାନଃ ସର୍ଭେ ଶେଷ ହେବା ପରେ ଆପଣଙ୍କୁ ତୁରନ୍ତ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ (ଯଦି ଆପଣ ସୁସ୍ଥ ଅଛନ୍ତି କିମ୍ବା ଅଧିକ ବିପଦ ଅଛନ୍ତି ତାହା ଚିହ୍ନଟ କରିବା) ଦିଆଯିବ ।"},{"text":"ମାର୍ଗଦର୍ଶନଃ ବିପଦ ସ୍ତର ଉପରେ ଆଧାର କରି ଆପଣଙ୍କୁ ମାର୍ଗଦର୍ଶନ ମିଳିବ। ଯଦି ଆପଣ ଅଧିକ ବିପଦଗ୍ରସ୍ତ ବୋଲି ଜଣାପଡ଼େ, ତେବେ ଆପଣଙ୍କୁ ମାମ୍ମୋଗ୍ରାଫି ପାଇଁ ପଠାଯାଇପାରେ। ଯଦି ଆପଣ ସାମାନ୍ୟ / କମ୍ ବିପଦଗ୍ରସ୍ତ ଅଛନ୍ତି, ତେବେ ଆପଣଙ୍କୁ ନିୟମିତ ଯାଞ୍ଚ ପ୍ରୋଟୋକଲ୍ ଜାରି ରଖିବାକୁ କୁହାଯିବ।"},{"text":"ଡାଟା ବ୍ୟବହାର: ଆପଣଙ୍କ ଠାରୁ ଏବଂ ଡାକ୍ତରଖାନାରୁ ସଂଗ୍ରହ କରାଯାଇଥିବା ତଥ୍ୟକୁ ଭାରତୀୟ ମହିଳାଙ୍କ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ବିଷୟରେ ଭଲ ଭାବେ ପୂର୍ବାନୁମାନ କରିବା ପାଇଁ ଏକ କୃତ୍ରିମ ବୁଦ୍ଧିମତା (ଏଆଇ) ମଡେଲକୁ ପ୍ରଶିକ୍ଷଣ ଦେବା ପାଇଁ ବ୍ୟବହାର କରାଯିବ ।"}]},{"heading":"ମୁଁ ଭାଗ ନେଲେ ମୋ ସହିତ କଣ ହେବ?","paragraphs":[{"text":"ବ୍ୟକ୍ତିଗତ ବିପଦ ପୂର୍ବାନୁମାନ ଆପଣଙ୍କୁ ସ୍ତନ କର୍କଟ ଲକ୍ଷଣ ଏବଂ ଭବିଷ୍ୟତରେ ସ୍ୱାସ୍ଥ୍ୟ ନିରୀକ୍ଷଣ ପାଇଁ ଆପଣଙ୍କ ବ୍ୟକ୍ତିଗତ ବିପଦଜନକ କାରକ ବିଷୟରେ ଅଧିକ ସଚେତନ ହେବାକୁ ସାହାଯ୍ୟ କରିବ।"}]},{"heading":"ମୁଁ କ''ଣ କରିବି?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ଭାଗ ନେବା ଦ୍ବାରା କେଉଁ ବିପଦ ରହିଛି?","paragraphs":[{"text":"ଏହି ଗବେଷଣା ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବା ଦ୍ୱାରା କୌଣସି ବଡ଼ ବିପଦ ନାହିଁ ।"},{"text":"କୌଣସି ବିପଦ ନାହିଁ/ ସର୍ବନିମ୍ନ ବିପଦ ନାହିଁ: ଏହି ଅଧ୍ୟୟନକୁ \\"ନିମ୍ନ ବିପଦ ନାହିଁ/ ସର୍ବନିମ୍ନ ବିପଦ\\" ବୋଲି କୁହାଯାଏ ।"},{"text":"ଗୋପନୀୟତା: ଗୋପନୀୟତା ସମ୍ବନ୍ଧରେ ଏକ ବିରଳ ବିପଦ ଅଛି, କିନ୍ତୁ ଏହା ହ୍ରାସ ପାଇଥାଏ କାରଣ ଆମେ ବ୍ୟକ୍ତିଗତ ଭାବରେ ଚିହ୍ନଟଯୋଗ୍ୟ ସୂଚନା ସଂଗ୍ରହ କରୁନାହୁଁ, ଏବଂ ତଥ୍ୟ ଅଜ୍ଞାତ ଭାବରେ ସଂଗ୍ରହ କରାଯାଏ ।"},{"text":"ସ୍ୱେଚ୍ଛାକୃତ: ଏହି ପ୍ରଶ୍ନପତ୍ର ସମ୍ପୂର୍ଣ୍ଣ ସ୍ୱେଚ୍ଛାକୃତ ଅଟେ; ଯଦି ଆପଣ ଆଗ୍ରହୀ ନୁହଁନ୍ତି, ତେବେ ଆପଣ ନିୟମିତ କ୍ଲିନିକ ଚିକିତ୍ସା ଅନୁସରଣ କରିପାରିବେ ।"},{"text":"କୌଣସି ଆକ୍ରୋଶକାରୀ ପ୍ରକ୍ରିୟା ନାହିଁ: ଏହା ଏକ ଡିଜିଟାଲ ଏବଂ କାର୍ଯ୍ୟ ପ୍ରବାହ ନବସୃଜନ ଅଧ୍ୟୟନ; ଗବେଷଣା ଉପାଦାନରେ କୌଣସି ପରୀକ୍ଷଣୀୟ ଔଷଧ କିମ୍ବା ଆକ୍ରୋଶକାରୀ ଚିକିତ୍ସା ସାମିଲ ନାହିଁ ।"}]},{"heading":"ଭାଗ ନେବା ଦ୍ବାରା କ''ଣ ଲାଭ ମିଳିପାରେ?","paragraphs":[{"text":"ବ୍ୟକ୍ତିଗତ ଲାଭ: ବ୍ୟକ୍ତିଗତ ଅଂଶଗ୍ରହଣକାରୀଙ୍କ ପାଇଁ କୌଣସି ପ୍ରତ୍ୟକ୍ଷ ଲାଭ ନାହିଁ । ତଥାପି, ଆପଣ ଏକ ବିପଦ ପୂର୍ବାନୁମାନ ପାଇବେ ଯାହା ଆପଣଙ୍କ ସ୍କ୍ରିନିଂ ରଣନୀତିକୁ ସୂଚିତ କରିବାରେ ସାହାଯ୍ୟ କରିପାରେ ।"},{"text":"ସାମାଜିକ ଲାଭ: ଆପଣଙ୍କ ଅଂଶଗ୍ରହଣ ଦ୍ୱାରା ବୃତ୍ତିଗତ ଲାଭ, ଯେପରିକି ସ୍ତନ କର୍କଟ ରୋଗର ପ୍ରାଥମିକ ଚିହ୍ନଟ ଏବଂ ସାରା ଭାରତରେ ମହିଳାଙ୍କ ପାଇଁ ଉତ୍ତମ ସମ୍ବଳ ଆବଣ୍ଟନ ବୃଦ୍ଧି ପାଇବ ।"}]},{"heading":"ଏହି ଅଧ୍ୟୟନରେ ମୋର ଅଂଶଗ୍ରହଣ ଗୋପନୀୟ ରଖାଯିବ କି?","paragraphs":[{"text":"ହଁ. ଏହି ଅଧ୍ୟୟନ ସମୟରେ ସଂଗ୍ରହ କରାଯାଇଥିବା ସମସ୍ତ ସୂଚନାକୁ ସଂପୂର୍ଣ୍ଣ ଗୋପନୀୟ ରଖାଯିବ । ସମସ୍ତ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟ ପ୍ରଯୁଜ୍ୟ ତଥ୍ୟ ସୁରକ୍ଷା ନିୟମାବଳୀ ଅନୁଯାୟୀ ଗୋପନୀୟ ଭାବରେ ଗୋପନ ରଖାଯିବ । କେବଳ ଅଧିକୃତ ଅନୁସନ୍ଧାନକାରୀ ଦଳର ସଦସ୍ୟମାନେ ତଥ୍ୟକୁ ପ୍ରବେଶ କରିପାରିବେ ଏବଂ ଆପଣଙ୍କ ସ୍ପଷ୍ଟ ସମ୍ମତି ବିନା କୌଣସି ବ୍ୟକ୍ତିଗତ ସୂଚନା ତୃତୀୟ ପକ୍ଷ ସହିତ ଅଂଶୀଦାର କରାଯିବ ନାହିଁ । ଅଧ୍ୟୟନ ଫଳାଫଳ କେବଳ ସମୁଦାୟ ଭାବରେ ଉପସ୍ଥାପନ କରାଯିବ, ଯାହାଦ୍ୱାରା ବ୍ୟକ୍ତିଗତ ଅଂଶଗ୍ରହଣକାରୀଙ୍କୁ ଚିହ୍ନଟ କରାଯାଇପାରିବ ନାହିଁ ।"},{"text":"ଏହି ତଥ୍ୟର ପ୍ରାୟ ୨୦% ଅଚଳ ଭାବେ ଅଜ୍ଞାତସୂତ୍ରରେ ସଂଗ୍ରହ କରାଯିବ ଏବଂ ଏହା ଏଆଇ ଆଲଗୋରିଦମଗୁଡ଼ିକର ମୂଲ୍ୟାଙ୍କନ ଲାଗି TANUHର ବେଞ୍ଚମାର୍କିଂ ଏବଂ ଓପନ ଡାଟା ପଦକ୍ଷେପ ଅନ୍ତର୍ଗତ ରହିବ। ସଂଗ୍ରହ କରାଯାଇଥିବା ତଥ୍ୟକୁ ଭବିଷ୍ୟତରେ ଗବେଷଣା ପାଇଁ ବ୍ୟବହାର କରାଯିବ, ଯେଉଁଥିରେ ଅନ୍ୟ ଫାଉଣ୍ଡେସନ ମଡେଲର ବିକାଶ ମଧ୍ୟ ସାମିଲ ହେବ।"}]},{"heading":"ସ୍ୱେଚ୍ଛାକୃତ ଅଂଶଗ୍ରହଣ କ''ଣ?","paragraphs":[{"text":"ଆପଣମାନେ ଏହି ସର୍ଭେରେ ଭାଗ ନେବା ପାଇଁ ସମ୍ପୂର୍ଣ୍ଣ ଭାବେ ସ୍ୱେଚ୍ଛାକୃତ ଏବଂ ଆପଣମାନେ ବିନା କୌଣସି ଦଣ୍ଡରେ କିମ୍ବା କୌଣସି ଲାଭ ହାନି ବିନା ଯେକୌଣସି ସମୟରେ ଏଥିରେ ଭାଗ ନେବାକୁ ମନା କରିପାରିବେ କିମ୍ବା ଏହାକୁ ବନ୍ଦ କରିପାରିବେ ।"}]},{"heading":"ଗବେଷଣା ସମ୍ବନ୍ଧୀୟ ଆଘାତ ପାଇଁ କୌଣସି କ୍ଷତିପୂରଣ ଏବଂ ଚିକିତ୍ସା ବ୍ୟବସ୍ଥା ରହିଛି କି?","paragraphs":[{"text":"କ୍ଷତିପୂରଣ: ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନେବା ପାଇଁ ଆପଣଙ୍କୁ କୌଣସି ଦେୟ ଦିଆଯିବ ନାହିଁ । କୌଣସି କ୍ଷତିପୂରଣ ପ୍ରଦାନ କରାଯିବ ନାହିଁ କାରଣ ଏହା ଏକ ସର୍ବନିମ୍ନ/ନିଃସଙ୍କଟ ଅଧ୍ୟୟନ ।"},{"text":"ଆହତ: ଏହା ଏକ ସର୍ଭେ/AI ଆଧାରିତ ସ୍କ୍ରିନିଂ ଅଧ୍ୟୟନ, ଯେଉଁଥିରେ କୌଣସି ଆକ୍ରୋଶକାରୀ ହସ୍ତକ୍ଷେପ ନାହିଁ, ତେଣୁ କୌଣସି ଚିକିତ୍ସା କିମ୍ବା ଆଘାତ ପାଇଁ କ୍ଷତିପୂରଣ ଯୋଜନା କରାଯାଇନାହିଁ ।"},{"text":"ବ୍ୟୟ: ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନେବା ପାଇଁ ଆପଣଙ୍କୁ କୌଣସି ବ୍ୟୟ ଦେବାକୁ ପଡ଼ିବ ନାହିଁ।"}]},{"heading":"ଗବେଷଣାର ପରିଣାମ କ''ଣ ହେବ?","paragraphs":[{"text":"ଏହି ଗବେଷଣା ଅଧ୍ୟୟନର ଫଳାଫଳକୁ ଏକ ଏଆଇ ସମର୍ଥିତ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣ ବିକଶିତ ଏବଂ ବୈଧ କରିବା ପାଇଁ ବ୍ୟବହାର କରାଯିବ । ଫଳାଫଳକୁ ସମୀକ୍ଷା କରାଯାଇଥିବା ବୈଜ୍ଞାନିକ ପତ୍ରିକାରେ ପ୍ରକାଶ କରାଯାଇପାରିବ, ଏକାଡେମିକ ସମ୍ମିଳନୀରେ ଉପସ୍ଥାପିତ କରାଯାଇପାରିବ ଏବଂ ଭାରତରେ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଅଭ୍ୟାସକୁ ଉନ୍ନତ କରିବା ପାଇଁ ସ୍ୱାସ୍ଥ୍ୟସେବା ସଂସ୍ଥା ଏବଂ ନୀତି ନିର୍ଦ୍ଧାରକମାନଙ୍କ ସହିତ ଅଂଶୀଦାର କରାଯାଇପାରିବ । ପ୍ରକାଶିତ ସମସ୍ତ ଫଳାଫଳ ଏକ ସମୂହ ସ୍ୱରୂପରେ ହେବ ।"}]},{"heading":"ଗବେଷଣାକୁ କିଏ ଆୟୋଜନ କରୁଛି ଏବଂ କିଏ ଏହାକୁ ଅର୍ଥ ପ୍ରଦାନ କରୁଛି?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"କିଏ ଏହି ଅଧ୍ୟୟନକୁ ସମୀକ୍ଷା କରିଛି?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ଅଧିକ ସୂଚନା ପାଇଁ ମୁଁ କାହାକୁ ଯୋଗାଯୋଗ କରିପାରିବି?","paragraphs":[{"text":"ଯୋଗାଯୋଗ ବିବରଣୀ: ଡଃ ଅଶ୍ୱିନ ରାଜକୁମାର, ପ୍ରକଳ୍ପ ପରିଚାଳକ"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ଯଦି ଆପଣ ଏହି ଅଧ୍ୟୟନରୁ କୌଣସି ସ୍ୱାଧୀନ ବ୍ୟକ୍ତିଙ୍କ ସହିତ କଥା ହେବାକୁ ଚାହୁଁଛନ୍ତି, ତେବେ ଆପଣ ନିମ୍ନଲିଖିତ ବ୍ୟକ୍ତିଙ୍କ ସହିତ ଯୋଗାଯୋଗ କରିପାରିବେଃ"},{"text":"ସଂସ୍ଥାଗତ ନୈତିକତା ସମିତି (ଆଇଇସି)"},{"text":"ନାମ: ଡଃ ଶ୍ରୀ ବିଦ୍ୟା ଜଗଦୀଶ, ଆଇଇସି ସଚିବ, ତନୁ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ଅଧ୍ୟୟନ ପାଇଁ ଧନ୍ୟବାଦ!"}]}],"checkboxLabel":"ମୁଁ ଅଂଶଗ୍ରହଣକାରୀ ସୂଚନା ପତ୍ରକୁ ପଢ଼ିଛି ଏବଂ ବୁଝିଛି ଏବଂ ସ୍ୱେଚ୍ଛାକୃତ ଭାବେ ଏହି ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ରାଜି ହୋଇଛି ।","buttonText":"ଗ୍ରହଣ କର ଏବଂ ଆଗକୁ ବଢ଼"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'pa','{"title":"ਭਾਗੀਦਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਸ਼ੀਟ","headernames":{"studyTitle":"ਅਧਿਐਨ ਦਾ ਸਿਰਲੇਖ","sponsor":"ਸੰਗਠਕ ਅਤੇ ਫੰਡਿੰਗ","iecApproval":"ਨੈਤਿਕਤਾ ਸਮੀਖਿਆ"},"header":{"studyTitle":"ਭਾਰਤੀ ਆਬਾਦੀ ਲਈ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਟੂਲ ਦਾ ਵਿਕਾਸ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ਇਸ ਅਧਿਐਨ ਬਾਰੇ","paragraphs":[{"text":"ਇਹ ਅਧਿਐਨ ਸਿਹਤ ਸੰਭਾਲ ਲਈ ਭਾਰਤੀ ਏਆਈ ਹੱਲ਼ ਵਿਕਸਿਤ ਕਰਨ ਲਈ ਸਿੱਖਿਆ ਮੰਤਰਾਲੇ ਦੁਆਰਾ ਫੰਡ ਕੀਤੇ ਪ੍ਰੋਜੈਕਟ ਦਾ ਹਿੱਸਾ ਹੈ। ਟੈਨੂਹ ਫਾਊਂਡੇਸ਼ਨ ਇੱਕ ਸੈਕਸ਼ਨ 8 ਕੰਪਨੀ ਹੈ ਜਿਸਦੀ ਮੇਜ਼ਬਾਨੀ ਇੰਡੀਅਨ ਇੰਸਟੀਚਿਊਟ ਆਫ ਸਾਇੰਸ ਕਰਦੀ ਹੈ। ਇਹ ਮਾਣ ਨਾਲ ਮੰਨਦੀ ਹੈ ਕਿ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਖੋਜ ਵਿੱਚ ਇਸ ਨਾਜ਼ੁਕ ਰਾਸ਼ਟਰੀ ਪਹਿਲਕਦਮੀ ਦੀ ਅਗਵਾਈ ਕਰਨ ਲਈ, ਛੇਤੀ, ਡਾਟਾ-ਅਧਾਰਿਤ ਖੋਜ ਸਿਹਤ ਨਤੀਜਿਆਂ ਵਿੱਚ ਸੁਧਾਰ ਲਈ ਜ਼ਰੂਰੀ ਹੈ। ਅਸੀਂ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਦੀ ਬਹੁਤ ਪ੍ਰਸ਼ੰਸਾ ਕਰਦੇ ਹਾਂ ਅਤੇ ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਔਰਤਾਂ ਦੇ ਲਾਭ ਲਈ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਅਧਿਐਨ ਨੂੰ ਅੱਗੇ ਵਧਾਉਣ ਦੇ ਇਸ ਯਤਨ ਦਾ ਇੱਕ ਜ਼ਰੂਰੀ ਹਿੱਸਾ ਹੋਣ ਲਈ ਤੁਹਾਡਾ ਧੰਨਵਾਦ ਕਰਦੇ ਹਾਂ। ਭਾਰਤ ਵਿੱਚ ਏਆਈ ਬਣਾਓ ਅਤੇ ਭਾਰਤ ਲਈ ਏਆਈ ਨੂੰ ਕੰਮ ਕਰੋ।"}]},{"heading":"ਅਧਿਐਨ ਦਾ ਮਕਸਦ ਕੀ ਹੈ?","paragraphs":[{"text":"ਭਾਰਤੀ ਆਬਾਦੀ ਲਈ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਟੂਲ ਦਾ ਵਿਕਾਸ"}]},{"heading":"ਮੈਨੂੰ ਕਿਉਂ ਚੁਣਿਆ ਗਿਆ ਹੈ?","paragraphs":[{"text":"ਤੁਹਾਨੂੰ ਏਆਈ ਸਮਰੱਥ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੇ ਸਾਧਨਾਂ ਦੇ ਅਧਿਐਨ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਉਣ ਲਈ ਚੁਣਿਆ ਗਿਆ ਹੈ ਕਿਉਂਕਿ ਤੁਹਾਨੂੰ ਮੈਮੋਗ੍ਰਾਫੀ ਜਾਂ ਰੁਟੀਨ ਮੈਮੋਗ੍ਰਾਫੀ ਲਈ ਭੇਜਿਆ ਗਿਆ ਹੈ। ਅਸੀਂ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੇ ਸਾਧਨ ਦਾ ਵਿਕਾਸ ਕਰ ਰਹੇ ਹਾਂ ਜੋ ਕੁਝ ਪ੍ਰਸ਼ਨਾਵਲੀ ਦੁਆਰਾ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਪਛਾਣ ਕਰਨ ਦੇ ਯੋਗ ਬਣਾਉਂਦਾ ਹੈ।"}]},{"heading":"ਕੀ ਮੈਨੂੰ ਹਿੱਸਾ ਲੈਣਾ ਚਾਹੀਦਾ ਹੈ?","paragraphs":[{"text":"ਤੁਸੀਂ ਆਪਣੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਵਲੰਟੀਅਰਤਾ ਨਾਲ ਇਸ ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਨਹੀਂ ਲੈਣਾ ਅਤੇ ਆਪਣੀ ਆਮ ਰੁਟੀਨ ਨਾਲ ਜਾਰੀ ਰਹਿਣਾ ਚੁਣ ਸਕਦੇ ਹੋ।"}]},{"heading":"ਅਧਿਐਨ ਵਿਚ ਕੀ ਹੋਵੇਗਾ ਜੇ ਤੁਸੀਂ ਹਿੱਸਾ ਲੈਣ ਲਈ ਸਹਿਮਤ ਹੋ, ਤਾਂ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਸਰਵੇਖਣਃ ਤੁਹਾਨੂੰ ਇੱਕ ਵਾਰ ਇੱਕ ਪ੍ਰਸ਼ਨਨਾਮਾ (ਟੈਬਲੇਟ/ਡਿਜੀਟਲ ਉਪਕਰਣ ''ਤੇ) ਭਰਨ ਲਈ ਕਿਹਾ ਜਾਵੇਗਾ ਜਿਸ ਵਿੱਚ ਤੁਹਾਡੀ ਜਨਸੰਖਿਆ, ਸਿਹਤ ਇਤਿਹਾਸ, ਜੀਵਨ ਸ਼ੈਲੀ ਅਤੇ ਪਰਿਵਾਰਕ ਕੈਂਸਰ ਦੇ ਇਤਿਹਾਸ ਬਾਰੇ ਦੱਸਿਆ ਗਿਆ ਹੈ।"},{"text":"ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀਃ ਸਰਵੇਖਣ ਦੇ ਅੰਤ ''ਤੇ, ਤੁਹਾਨੂੰ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਤੁਰੰਤ ਭਵਿੱਖਬਾਣੀ ਦਿੱਤੀ ਜਾਵੇਗੀ (ਜੋ ਇਹ ਪਤਾ ਲਗਾਉਂਦਾ ਹੈ ਕਿ ਕੀ ਤੁਹਾਡਾ ਜੋਖਮ ਆਮ ਜਾਂ ਵਧੇਰੇ ਹੈ)."},{"text":"ਮਾਰਗਦਰਸ਼ਨਃ ਜੋਖਮ ਦੇ ਪੱਧਰ ਦੇ ਆਧਾਰ ਤੇ, ਤੁਹਾਨੂੰ ਮਾਰਗਦਰਸ਼ਨ ਮਿਲੇਗਾ. ਜੇ ਤੁਹਾਨੂੰ ਵਧੇਰੇ ਜੋਖਮ ਪਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਤੁਹਾਨੂੰ ਮੈਮੋਗ੍ਰਾਫੀ ਲਈ ਭੇਜਿਆ ਜਾ ਸਕਦਾ ਹੈ. ਜੇ ਤੁਸੀਂ ਆਮ / ਘੱਟ ਜੋਖਮ ਵਿੱਚ ਹੋ, ਤਾਂ ਤੁਹਾਨੂੰ ਨਿਯਮਤ ਜਾਂਚ ਪ੍ਰੋਟੋਕੋਲ ਜਾਰੀ ਰੱਖਣ ਲਈ ਕਿਹਾ ਜਾਵੇਗਾ."},{"text":"ਡਾਟਾ ਉਪਯੋਗਤਾ: ਤੁਹਾਡੇ ਅਤੇ ਹਸਪਤਾਲ ਤੋਂ ਇਕੱਠਾ ਕੀਤੇ ਗਏ ਡਾਟਾ ਦੀ ਵਰਤੋਂ ਭਾਰਤੀ ਔਰਤਾਂ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਬਿਹਤਰ ਭਵਿੱਖਬਾਣੀ ਕਰਨ ਲਈ ਇੱਕ ਆਰਟੀਫੀਸ਼ੀਅਲ ਇੰਟੈਲੀਜੈਂਸ (ਏਆਈ) ਮਾਡਲ ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਕੀਤੀ ਜਾਵੇਗੀ।"}]},{"heading":"ਜੇ ਮੈਂ ਹਿੱਸਾ ਲੈਂਦਾ ਹਾਂ ਤਾਂ ਮੇਰੇ ਨਾਲ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਵਿਅਕਤੀਗਤ ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀ ਤੁਹਾਨੂੰ ਭਵਿੱਖ ਵਿੱਚ ਸਿਹਤ ਨਿਗਰਾਨੀ ਲਈ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਸੰਭਾਵਿਤ ਲੱਛਣਾਂ ਅਤੇ ਤੁਹਾਡੇ ਵਿਅਕਤੀਗਤ ਜੋਖਮ ਕਾਰਕਾਂ ਬਾਰੇ ਵਧੇਰੇ ਜਾਣੂ ਹੋਣ ਵਿੱਚ ਸਹਾਇਤਾ ਕਰੇਗੀ."}]},{"heading":"ਮੈਨੂੰ ਕੀ ਕਰਨਾ ਹੈ?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ਭਾਗ ਲੈਣ ਦੇ ਕੀ ਖ਼ਤਰੇ ਹਨ?","paragraphs":[{"text":"ਇਸ ਖੋਜ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਵਿੱਚ ਕੋਈ ਵੱਡਾ ਜੋਖਮ ਨਹੀਂ ਹੈ।"},{"text":"ਕੋਈ/ ਘੱਟੋ ਘੱਟ ਜੋਖਮ ਨਹੀਂਃ ਇਹ ਅਧਿਐਨ \\"ਕੋਈ/ ਘੱਟੋ ਘੱਟ ਜੋਖਮ\\" ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ।"},{"text":"ਪਰਦੇਦਾਰੀਃ ਪਰਦੇਦਾਰੀ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਇੱਕ ਬਹੁਤ ਹੀ ਘੱਟ ਜੋਖਮ ਹੈ, ਪਰ ਇਹ ਘੱਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਕਿਉਂਕਿ ਅਸੀਂ ਨਿੱਜੀ ਤੌਰ ''ਤੇ ਪਛਾਣਨ ਯੋਗ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਨਹੀਂ ਕਰਦੇ, ਅਤੇ ਡੇਟਾ ਗੁਮਨਾਮ ਰੂਪ ਵਿੱਚ ਪ੍ਰਾਪਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ."},{"text":"ਸਵੈਇੱਛੁਕ: ਇਹ ਪ੍ਰਸ਼ਨਨਾਮਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਵੈਇੱਛੁਕ ਹੈ; ਜੇਕਰ ਤੁਸੀਂ ਦਿਲਚਸਪੀ ਨਹੀਂ ਰੱਖਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਇਸ ਦੀ ਬਜਾਏ ਰੁਟੀਨ ਕਲਿਨੀਕ ਦੇਖਭਾਲ ਦੀ ਪਾਲਣਾ ਕਰ ਸਕਦੇ ਹੋ।"},{"text":"ਕੋਈ ਹਮਲਾਵਰ ਪ੍ਰਕਿਰਿਆਵਾਂ ਨਹੀਂਃ ਇਹ ਇੱਕ ਡਿਜੀਟਲ ਅਤੇ ਵਰਕਫਲੋ ਇਨੋਵੇਸ਼ਨ ਅਧਿਐਨ ਹੈ; ਖੋਜ ਭਾਗ ਵਿੱਚ ਕੋਈ ਪ੍ਰਯੋਗਾਤਮਕ ਦਵਾਈਆਂ ਜਾਂ ਹਮਲਾਵਰ ਥੈਰੇਪੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹਨ।"}]},{"heading":"ਹਿੱਸਾ ਲੈਣ ਦੇ ਕੀ ਲਾਭ ਹੋ ਸਕਦੇ ਹਨ?","paragraphs":[{"text":"ਨਿੱਜੀ ਲਾਭਃ ਵਿਅਕਤੀਗਤ ਭਾਗੀਦਾਰਾਂ ਲਈ ਸਿੱਧਾ ਲਾਭ ਨਹੀਂ ਹੋਵੇਗਾ। ਹਾਲਾਂਕਿ, ਤੁਹਾਨੂੰ ਇੱਕ ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀ ਮਿਲੇਗੀ ਜੋ ਤੁਹਾਡੀ ਸਕ੍ਰੀਨਿੰਗ ਰਣਨੀਤੀ ਨੂੰ ਸੂਚਿਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦੀ ਹੈ।"},{"text":"ਸਮਾਜਿਕ ਲਾਭਃ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਵਿਗਿਆਨਕ ਲਾਭਾਂ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਏਗੀ, ਜਿਸ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਛੇਤੀ ਖੋਜ ਵਿੱਚ ਸੁਧਾਰ ਅਤੇ ਭਾਰਤ ਭਰ ਵਿੱਚ ਔਰਤਾਂ ਲਈ ਬਿਹਤਰ ਸਰੋਤ ਨਿਰਧਾਰਨ ਸ਼ਾਮਲ ਹੈ।"}]},{"heading":"ਕੀ ਇਸ ਅਧਿਐਨ ਵਿਚ ਮੇਰੀ ਭਾਗੀਦਾਰੀ ਗੁਪਤ ਰੱਖੀ ਜਾਵੇਗੀ?","paragraphs":[{"text":"ਹਾਂ. ਇਸ ਅਧਿਐਨ ਦੌਰਾਨ ਇਕੱਠੀ ਕੀਤੀ ਗਈ ਸਾਰੀ ਜਾਣਕਾਰੀ ਸਖਤੀ ਨਾਲ ਗੁਪਤ ਰੱਖੀ ਜਾਵੇਗੀ. ਸਾਰੇ ਨਿੱਜੀ ਡੇਟਾ ਲਾਗੂ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੇ ਅਨੁਸਾਰ ਅਗਿਆਤ ਕੀਤੇ ਜਾਣਗੇ ਅਤੇ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੇ ਜਾਣਗੇ. ਸਿਰਫ ਅਧਿਕਾਰਤ ਖੋਜ ਟੀਮ ਦੇ ਮੈਂਬਰਾਂ ਨੂੰ ਡੇਟਾ ਤੱਕ ਪਹੁੰਚ ਹੋਵੇਗੀ, ਅਤੇ ਤੁਹਾਡੀ ਸਪੱਸ਼ਟ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਨਿੱਜੀ ਤੌਰ ''ਤੇ ਪਛਾਣਨ ਯੋਗ ਜਾਣਕਾਰੀ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਵੇਗੀ. ਅਧਿਐਨ ਦੇ ਨਤੀਜੇ ਸਿਰਫ ਸਮੁੱਚੇ ਰੂਪ ਵਿੱਚ ਪੇਸ਼ ਕੀਤੇ ਜਾਣਗੇ, ਇਹ ਸੁਨਿਸ਼ਚਿਤ ਕਰਦੇ ਹੋਏ ਕਿ ਵਿਅਕਤੀਗਤ ਭਾਗੀਦਾਰਾਂ ਦੀ ਪਛਾਣ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ."},{"text":"ਕੁੱਲ ਡਾਟਾ ਦਾ ਲਗਭਗ 20%, ਇੱਕ ਅਟੱਲ ਅਗਿਆਤ ਢੰਗ ਨਾਲ ਇਕੱਠਾ ਕੀਤਾ ਜਾਵੇਗਾ, AI ਐਲਗੋਰਿਦਮ ਦੇ ਮੁਲਾਂਕਣ ਲਈ TANUH ਦੇ ਬੈਂਚਮਾਰਕਿੰਗ ਅਤੇ ਓਪਨ ਡਾਟਾ ਪਹਿਲ ਦਾ ਹਿੱਸਾ ਹੋਵੇਗਾ। ਇਕੱਠਾ ਕੀਤਾ ਡਾਟਾ ਭਵਿੱਖ ਵਿੱਚ ਖੋਜ ਵਿੱਚ ਵਰਤਿਆ ਜਾਵੇਗਾ, ਜਿਸ ਵਿੱਚ ਹੋਰ ਫਾਊਂਡੇਸ਼ਨ ਮਾਡਲਾਂ ਦੇ ਵਿਕਾਸ ਵੀ ਸ਼ਾਮਲ ਹੈ।"}]},{"heading":"ਸਵੈਇੱਛੁਕ ਭਾਗੀਦਾਰੀ ਕੀ ਹੈ?","paragraphs":[{"text":"ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਵੈਇੱਛੁਕ ਹੈ। ਤੁਸੀਂ ਬਿਨਾਂ ਕਿਸੇ ਜੁਰਮਾਨੇ ਜਾਂ ਲਾਭਾਂ ਦੇ ਨੁਕਸਾਨ ਦੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸਰਵੇਖਣ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਤੋਂ ਇਨਕਾਰ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਇਸ ਨੂੰ ਰੋਕ ਸਕਦੇ ਹੋ।"}]},{"heading":"ਕੀ ਖੋਜ ਨਾਲ ਜੁੜੇ ਜ਼ਖਮਾਂ ਲਈ ਕੋਈ ਮੁਆਵਜ਼ਾ ਅਤੇ ਡਾਕਟਰੀ ਦੇਖਭਾਲ ਹੈ?","paragraphs":[{"text":"ਮੁਆਵਜ਼ਾਃ ਤੁਹਾਨੂੰ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਭੁਗਤਾਨ ਨਹੀਂ ਕੀਤਾ ਜਾਵੇਗਾ। ਕੋਈ ਮੁਆਵਜ਼ਾ ਨਹੀਂ ਦਿੱਤਾ ਜਾਂਦਾ ਕਿਉਂਕਿ ਇਹ ਇੱਕ ਘੱਟੋ ਘੱਟ/ਕੋਈ ਜੋਖਮ-ਮੁਕਤ ਅਧਿਐਨ ਹੈ।"},{"text":"ਜ਼ਖਮਃ ਕਿਉਂਕਿ ਇਹ ਇੱਕ ਸਰਵੇਖਣ/ਏਆਈ ਅਧਾਰਤ ਸਕ੍ਰੀਨਿੰਗ ਅਧਿਐਨ ਹੈ ਜਿਸ ਵਿੱਚ ਕੋਈ ਹਮਲਾਵਰ ਦਖਲਅੰਦਾਜ਼ੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ, ਜ਼ਖਮ ਲਈ ਕੋਈ ਡਾਕਟਰੀ ਇਲਾਜ ਜਾਂ ਮੁਆਵਜ਼ਾ ਦੀ ਯੋਜਨਾ ਨਹੀਂ ਹੈ।"},{"text":"ਖਰਚੇਃ ਇਸ ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਤੁਹਾਡੇ ਲਈ ਕੋਈ ਖਰਚਾ ਨਹੀਂ ਹੈ।"}]},{"heading":"ਖੋਜ ਅਧਿਐਨ ਦੇ ਨਤੀਜਿਆਂ ਦਾ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਇਸ ਖੋਜ ਅਧਿਐਨ ਦੇ ਨਤੀਜਿਆਂ ਦੀ ਵਰਤੋਂ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਕਰਨ ਵਾਲੇ ਸਾਧਨ ਨੂੰ ਵਿਕਸਤ ਕਰਨ ਅਤੇ ਪ੍ਰਮਾਣਿਤ ਕਰਨ ਲਈ ਕੀਤੀ ਜਾਵੇਗੀ। ਨਤੀਜੇ ਪੀਅਰ-ਰੀਵਿਊ ਕੀਤੇ ਵਿਗਿਆਨਕ ਰਸਾਲਿਆਂ ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਤ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ, ਅਕਾਦਮਿਕ ਕਾਨਫਰੰਸਾਂ ਵਿੱਚ ਪੇਸ਼ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ, ਅਤੇ ਭਾਰਤ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੀਆਂ ਪ੍ਰਥਾਵਾਂ ਵਿੱਚ ਸੁਧਾਰ ਲਈ ਸਿਹਤ ਸੰਭਾਲ ਸੰਸਥਾਵਾਂ ਅਤੇ ਨੀਤੀ ਨਿਰਮਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ। ਸਾਰੇ ਪ੍ਰਕਾਸ਼ਤ ਨਤੀਜੇ ਵਿਅਕਤੀਗਤ ਪਛਾਣ ਦੇ ਬਿਨਾਂ ਸਮੁੱਚੇ ਰੂਪ ਵਿੱਚ ਹੋਣਗੇ।"}]},{"heading":"ਖੋਜ ਦਾ ਪ੍ਰਬੰਧਨ ਅਤੇ ਵਿੱਤ ਕੌਣ ਕਰ ਰਿਹਾ ਹੈ?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ਇਸ ਅਧਿਐਨ ਦੀ ਸਮੀਖਿਆ ਕਿਸਨੇ ਕੀਤੀ ਹੈ?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ਮੈਂ ਹੋਰ ਜਾਣਕਾਰੀ ਲਈ ਕਿਸ ਨਾਲ ਸੰਪਰਕ ਕਰ ਸਕਦਾ ਹਾਂ?","paragraphs":[{"text":"ਸੰਪਰਕ ਵੇਰਵੇਃ ਡਾ. ਅਸ਼ਵਿਨ ਰਾਜਕੁਮਾਰ, ਪ੍ਰੋਜੈਕਟ ਮੈਨੇਜਰ"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ਜੇਕਰ ਤੁਸੀਂ ਅਧਿਐਨ ਤੋਂ ਸੁਤੰਤਰ ਕਿਸੇ ਨਾਲ ਗੱਲ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਹੇਠ ਲਿਖੇ ਨੰਬਰ ''ਤੇ ਸੰਪਰਕ ਕਰ ਸਕਦੇ ਹੋਃ"},{"text":"ਸੰਸਥਾਗਤ ਨੈਤਿਕਤਾ ਕਮੇਟੀ (ਆਈਈਸੀ)"},{"text":"ਨਾਮਃ ਡਾ. ਸ਼੍ਰੀ ਵਿਦਿਆ ਜਗਾਡੀਸ਼, ਆਈਈਸੀ, ਟੈਨੂਹ ਦੇ ਸਕੱਤਰ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਤੁਹਾਡਾ ਧੰਨਵਾਦ!"}]}],"checkboxLabel":"ਮੈਂ ਭਾਗੀਦਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਸ਼ੀਟ ਪੜ੍ਹੀ ਅਤੇ ਸਮਝੀ ਹੈ ਅਤੇ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਸਵੈਇੱਛਤ ਤੌਰ ''ਤੇ ਸਹਿਮਤ ਹਾਂ।","buttonText":"ਸਵੀਕਾਰ ਕਰੋ ਅਤੇ ਜਾਰੀ ਰੱਖੋ"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'ta','{"title":"பங்கேற்பாளர் தகவல் தாள்","headernames":{"studyTitle":"ஆய்வு தலைப்பு","sponsor":"அமைப்பாளர் மற்றும் நிதி","iecApproval":"நெறிமுறைகள்"},"header":{"studyTitle":"இந்திய மக்களுக்கான மார்பக புற்றுநோய் அபாயத்தை கணிக்க AI இயக்கப்பட்ட கருவியை உருவாக்குதல்","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"இந்த ஆய்வு பற்றி","paragraphs":[{"text":"இந்த ஆய்வு சுகாதாரத்துறைக்கான இந்திய AI தீர்வுகளை உருவாக்குவதற்கான கல்வி அமைச்சின் நிதியுதவியுடன் மேற்கொள்ளப்படும் திட்டத்தின் ஒரு பகுதியாகும். இந்திய அறிவியல் நிறுவனத்தால் நடத்தப்படும் TANUH அறக்கட்டளை ஒரு பிரிவு 8 நிறுவனமாகும். மார்பக புற்றுநோய் ஆராய்ச்சியில் இந்த முக்கியமான தேசிய முயற்சியை முன்னெடுத்து வருவதில் பெருமிதம் கொள்கிறது. சுகாதார முடிவுகளை மேம்படுத்துவதற்கு ஆரம்பகால, தரவு அடிப்படையிலான கண்டறிதல் மிக முக்கியமானது என்பதை அங்கீகரிக்கிறது. உங்கள் பங்கேற்பை நாங்கள் மிகவும் பாராட்டுகிறோம், இந்தியா முழுவதும் பெண்களின் நலனுக்காக மார்பக புற்றுநோய் ஆய்வுகளை மேம்படுத்துவதற்கான இந்த முயற்சியின் ஒரு முக்கிய பகுதியாக இருப்பதற்கு நன்றி. இந்தியாவில் AI ஐ உருவாக்குங்கள் மற்றும் AI ஐ இந்தியாவுக்கு வேலை செய்யுங்கள்."}]},{"heading":"ஆய்வின் நோக்கம் என்ன?","paragraphs":[{"text":"இந்திய மக்களுக்கான மார்பக புற்றுநோய் அபாயத்தை கணிக்க AI இயக்கப்பட்ட கருவியை உருவாக்குதல்"}]},{"heading":"ஏன் என்னைத் தேர்ந்தெடுத்தார்கள்?","paragraphs":[{"text":"நீங்கள் மார்பக புற்றுநோய் பரிசோதனை கருவிகள் ஆய்வு செய்ய தேர்ந்தெடுக்கப்பட்டீர்கள், ஏனெனில் நீங்கள் மார்பக புற்றுநோய் பரிசோதனை அல்லது வழக்கமான மார்பக புற்றுநோய் பரிசோதனைக்கு பரிந்துரைக்கப்பட்டீர்கள். சில கேள்வித்தாள்களால் மார்பக புற்றுநோய் அபாயத்தை அடையாளம் காணக்கூடிய ஒரு AI-யை இயக்கிய மார்பக புற்றுநோய் பரிசோதனை கருவியை நாங்கள் உருவாக்கி வருகிறோம்."}]},{"heading":"நான் பங்கேற்க வேண்டுமா?","paragraphs":[{"text":"நீங்கள் முழுமையாக தன்னார்வ ரீதியாகப் பங்கேற்கலாம். நீங்கள் ஆய்வில் பங்கேற்காமல், வழக்கமான வழக்கமான வழக்கத்தை தொடரலாம்."}]},{"heading":"நீங்கள் கலந்து கொள்ள ஒப்புக்கொண்டால், பின்வருவன ஏற்படும்.","paragraphs":[{"text":"ஆய்வுஃ உங்கள் மக்கள்தொகை, உடல்நலம் வரலாறு, வாழ்க்கை முறை மற்றும் குடும்ப வரலாறு ஆகியவற்றைப் பற்றிய ஒரு முறை கேள்வித்தாளை (தொகுப்பு / டிஜிட்டல் சாதனத்தில்) நிரப்ப நீங்கள் கேட்கப்படுவீர்கள்."},{"text":"ஆபத்து கணிப்புஃ ஆய்வு முடிவில், உங்களுக்கு உடனடி மார்பக புற்றுநோய் ஆபத்து கணிப்பு வழங்கப்படும் (நீங்கள் சாதாரணமான அல்லது அதிக ஆபத்தில் இருக்கிறீர்களா என்பதை அடையாளம் காணும்)."},{"text":"வழிகாட்டுதல்ஃ ஆபத்து அளவை அடிப்படையாகக் கொண்டு, உங்களுக்கு வழிகாட்டுதல் வழங்கப்படும். நீங்கள் அதிக ஆபத்தில் இருப்பதாகக் கண்டறியப்பட்டால், நீங்கள் மாம்மோகிராபிக்கு அனுப்பப்படலாம். நீங்கள் சாதாரணமான / குறைந்த ஆபத்தில் இருந்தால், வழக்கமான சோதனை நெறிமுறைகளைத் தொடர வேண்டும்."},{"text":"தரவு பயன்பாடுஃ உங்களிடமிருந்தும் மருத்துவமனையிடமிருந்தும் சேகரிக்கப்பட்ட தரவு, இந்திய பெண்களில் மார்பக புற்றுநோய் அபாயத்தை சிறப்பாக கணிப்பதற்காக செயற்கை நுண்ணறிவு (AI) மாதிரியை பயிற்சி செய்யப் பயன்படுத்தப்படும்."}]},{"heading":"நான் பங்கேற்றால் என்ன நடக்கும்?","paragraphs":[{"text":"தனிப்பட்ட அபாய கணிப்பு உங்களுக்கு மார்பக புற்றுநோய் அறிகுறிகள் மற்றும் எதிர்கால சுகாதார கண்காணிப்புக்கான உங்கள் தனிப்பட்ட ஆபத்து காரணிகளை நன்கு அறிய உதவும்."}]},{"heading":"நான் என்ன செய்ய வேண்டும்?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"பங்கேற்பு என்ன ஆபத்துகளை ஏற்படுத்துகிறது?","paragraphs":[{"text":"இந்த ஆராய்ச்சி ஆய்வில் பங்கேற்பதில் எந்த பெரிய ஆபத்தும் இல்லை."},{"text":"இல்லை/ குறைந்தபட்ச ஆபத்துஃ இந்த ஆய்வு \\"இல்லை/ குறைந்தபட்ச ஆபத்து\\" என்று கருதப்படுகிறது."},{"text":"தனியுரிமைஃ தனியுரிமை தொடர்பாக அரிதான ஆபத்து உள்ளது, ஆனால் இது குறைக்கப்படுகிறது, ஏனெனில் நாங்கள் தனிப்பட்ட முறையில் அடையாளம் காணக்கூடிய தகவல்களை சேகரிக்கவில்லை, மேலும் தரவு அநாமதேயமாகப் பிடிக்கப்படுகிறது."},{"text":"தன்னார்வ: வினாத்தாள் முற்றிலும் தன்னார்வமானது; நீங்கள் ஆர்வம் காட்டவில்லை என்றால், அதற்கு பதிலாக வழக்கமான மருத்துவமனை பராமரிப்பை மேற்கொள்ளலாம்."},{"text":"எந்த ஆக்கிரமிப்பு நடைமுறைகளும் இல்லைஃ இது ஒரு டிஜிட்டல் மற்றும் பணிப்பாய்வு கண்டுபிடிப்பு ஆய்வு; ஆராய்ச்சி கூறுகளில் பரிசோதனை மருந்துகள் அல்லது ஆக்கிரமிப்பு சிகிச்சைகள் எதுவும் ஈடுபடவில்லை."}]},{"heading":"பங்கேற்பதில் என்ன நன்மைகள் உள்ளன?","paragraphs":[{"text":"தனிப்பட்ட நன்மைஃ தனிப்பட்ட பங்கேற்பாளர்களுக்கு நேரடி நன்மை இல்லை. இருப்பினும், உங்கள் புலனாய்வு மூலோபாயத்தை விளக்க உதவும் ஒரு ஆபத்து கணிப்பு உங்களுக்கு வழங்கப்படும்."},{"text":"சமூக நன்மைஃ உங்கள் பங்கேற்பு, மார்பக புற்றுநோயை ஆரம்பகாலமாக கண்டறிதல் மற்றும் இந்தியா முழுவதும் பெண்களுக்கு சிறந்த வள ஒதுக்கீடு உள்ளிட்ட அறிவியல் நன்மைகளுக்கு பங்களிக்கும்."}]},{"heading":"இந்த ஆய்வில் நான் பங்கேற்பது இரகசியமாகவே இருக்கப் போகிறதா?","paragraphs":[{"text":"ஆம். இந்த ஆய்வின் போது சேகரிக்கப்பட்ட அனைத்து தகவல்களும் கண்டிப்பாக ரகசியமாக வைக்கப்படும். அனைத்து தனிப்பட்ட தரவுகளும் பொருந்தக்கூடிய தரவு பாதுகாப்பு ஒழுங்குமுறைகளின்படி அநாமதேயப்படுத்தப்பட்டு பாதுகாப்பாக சேமிக்கப்படும். அங்கீகரிக்கப்பட்ட ஆராய்ச்சி குழு உறுப்பினர்கள் மட்டுமே தரவுகளை அணுக முடியும், மேலும் உங்கள் வெளிப்படையான ஒப்புதல் இல்லாமல் தனிப்பட்ட முறையில் அடையாளம் காணக்கூடிய எந்த தகவலும் மூன்றாம் தரப்பினருடன் பகிரப்படாது. ஆய்வின் முடிவுகள் ஒட்டுமொத்த வடிவத்தில் மட்டுமே வழங்கப்படும், தனிப்பட்ட பங்கேற்பாளர்களை அடையாளம் காண முடியாது என்பதை உறுதிசெய்கிறது."},{"text":"மொத்த தரவுகளில் சுமார் 20% ஐ, மாற்றமுடியாத அநாமதேய முறையில் சேகரிக்கப்படும், இது AI வழிமுறைகளை மதிப்பீடு செய்வதற்கான TANUH இன் ஒப்பீட்டு மதிப்பீடு மற்றும் திறந்த தரவு முன்முயற்சியின் ஒரு பகுதியாக இருக்கும். சேகரிக்கப்பட்ட தரவு எதிர்கால ஆராய்ச்சியில் பயன்படுத்தப்படும், இதில் பிற அடித்தள மாதிரிகள் உருவாக்கப்படும்."}]},{"heading":"தன்னார்வ பங்கேற்பு என்றால் என்ன?","paragraphs":[{"text":"நீங்கள் எந்த நேரத்திலும், எந்தவொரு தண்டனையும் அல்லது நன்மை இழப்பும் இல்லாமல், இந்த ஆய்வில் பங்கேற்க மறுக்கலாம் அல்லது நிறுத்தலாம்."}]},{"heading":"ஆராய்ச்சி தொடர்பான காயங்களுக்கு இழப்பீடு மற்றும் மருத்துவ சிகிச்சைகள் ஏதேனும் உள்ளதா?","paragraphs":[{"text":"இழப்பீடுஃ இந்த ஆய்வில் பங்கேற்பதற்காக உங்களுக்கு பணம் செலுத்தப்படாது. இது குறைந்தபட்ச / எந்த ஆபத்தும் இல்லாத ஆய்வாக இருப்பதால் எந்த இழப்பீடும் வழங்கப்படவில்லை."},{"text":"காயம்ஃ இது ஒரு ஆய்வு/AI அடிப்படையிலான ஆய்வு ஆகும், இதில் எந்த ஆக்கிரமிப்பு நடவடிக்கைகளும் இல்லை, எனவே காயம் தொடர்பான மருத்துவ சிகிச்சை அல்லது இழப்பீடு எதுவும் திட்டமிடப்படவில்லை."},{"text":"செலவுகள்ஃ இந்த ஆய்வில் பங்கேற்பதற்கு நீங்கள் எந்த செலவும் செலுத்த முடியாது."}]},{"heading":"ஆராய்ச்சி முடிவுகள் என்னவாக இருக்கும்?","paragraphs":[{"text":"இந்த ஆராய்ச்சி ஆய்வின் முடிவுகள் AI இயக்கப்பட்ட மார்பக புற்றுநோய் அபாய கணிப்பு கருவியை உருவாக்கவும் சரிபார்க்கவும் பயன்படுத்தப்படும். கண்டுபிடிப்புகள் சமநிலை மதிப்பாய்வு செய்யப்பட்ட அறிவியல் இதழ்களில் வெளியிடப்படலாம், கல்வி மாநாடுகளில் வழங்கப்படலாம், மேலும் இந்தியாவில் மார்பக புற்றுநோய் பரிசோதனை நடைமுறைகளை மேம்படுத்த சுகாதார நிறுவனங்கள் மற்றும் கொள்கை வகுப்பாளர்களுடன் பகிரப்படலாம். வெளியிடப்பட்ட அனைத்து முடிவுகளும் தனிப்பட்ட அடையாளம் காணப்படாமல் கூட்டு வடிவத்தில் இருக்கும்."}]},{"heading":"இந்த ஆராய்ச்சியை யார் ஏற்பாடு செய்து நிதியளிக்கிறார்கள்?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"யார் இந்த ஆய்வை ஆய்வு செய்தார்கள்?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"மேலும் தகவலுக்கு நான் யாரை தொடர்பு கொள்ளலாம்?","paragraphs":[{"text":"தொடர்பு விவரங்கள்ஃ டாக்டர் அஸ்வின் ராகுமார், திட்ட மேலாளர்"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"நீங்கள் ஆய்வுக்கு உட்பட்ட ஒருவரைப் பற்றி பேச விரும்பினால், பின்வரும் முகவரிகளை தொடர்பு கொள்ளலாம்ஃ"},{"text":"நிறுவன நெறிமுறைகள் குழு (IEC)"},{"text":"பெயர்ஃ டாக்டர் ஸ்ரீ வித்யா ஜகதிஷ், ஐ. இ. சி செயலாளர், TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"இந்த ஆய்வில் பங்கேற்றதற்கு நன்றி!"}]}],"checkboxLabel":"பங்கேற்பாளர் தகவல் தாள்களை நான் படித்து புரிந்து கொண்டேன், இந்த ஆய்வில் பங்கேற்க தன்னார்வமாக ஒப்புக்கொண்டேன்.","buttonText":"ஏற்றுக்கொள் & தொடரவும்"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (1,'te','{"title":"పాల్గొనేవారికి సమాచారం","headernames":{"studyTitle":"అధ్యయన శీర్షిక","sponsor":"వ్యవస్థాపకుడు మరియు నిధులు","iecApproval":"నైతికత సమీక్ష"},"header":{"studyTitle":"భారతీయ జనాభాకు కృత్రిమ మేధస్సుతో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి ఒక సాధనం అభివృద్ధి","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ఈ అధ్యయనము గురించి","paragraphs":[{"text":"ఈ అధ్యయనం ఆరోగ్య సంరక్షణ కోసం భారతీయ AI పరిష్కారాలను అభివృద్ధి చేయడానికి విద్యా మంత్రిత్వ శాఖ నిధులతో నిధులు సమకూర్చే ప్రాజెక్టులో భాగం. భారతీయ సైన్స్ ఇన్స్టిట్యూట్ నిర్వహించిన TANUH ఫౌండేషన్ ఈ కీలకమైన జాతీయ చొరవను రొమ్ము క్యాన్సర్ పరిశోధనలో నాయకత్వం వహించడం గర్వంగా ఉంది. ఆరోగ్య ఫలితాలను మెరుగుపరచడానికి ప్రారంభ, డేటా ఆధారిత గుర్తింపు చాలా కీలకం అని గుర్తించింది. భారతదేశం అంతటా మహిళల ప్రయోజనం కోసం రొమ్ము క్యాన్సర్ అధ్యయనాలను ముందుకు తీసుకురావడానికి మీ భాగస్వామ్యాన్ని మేము తీవ్రంగా అభినందిస్తున్నాము మరియు ఈ ప్రయత్నంలో ముఖ్యమైన భాగం కావడం కోసం ధన్యవాదాలు. భారతదేశంలో AI ను తయారు చేయండి మరియు AI ను భారతదేశం కోసం పని చేయండి."}]},{"heading":"అధ్యయనానికి ఉద్దేశ్యం ఏమిటి?","paragraphs":[{"text":"భారతీయ జనాభాకు కృత్రిమ మేధస్సుతో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి ఒక సాధనం అభివృద్ధి"}]},{"heading":"నన్ను ఎందుకు ఎన్నుకున్నారు?","paragraphs":[{"text":"మీరు మామ్మోగ్రఫీకి లేదా సాధారణ మామ్మోగ్రఫీకి పంపబడినందున మీరు AI- ప్రారంభించబడిన రొమ్ము క్యాన్సర్ స్క్రీనింగ్ సాధనాల అధ్యయనానికి సహకరించడానికి ఎంపిక చేయబడ్డారు. కొన్ని ప్రశ్నాపత్రాల ద్వారా రొమ్ము క్యాన్సర్ ప్రమాదాన్ని గుర్తించడానికి వీలు కల్పించే AI- ప్రారంభించబడిన రొమ్ము క్యాన్సర్ స్క్రీనింగ్ సాధనాన్ని మేము అభివృద్ధి చేస్తున్నాము."}]},{"heading":"నేను పాల్గొనవలసి ఉందా?","paragraphs":[{"text":"మీరు పూర్తిగా స్వచ్ఛందంగా పాల్గొనవచ్చు. మీరు అధ్యయనంలో పాల్గొనకుండా మీ సాధారణ దినచర్యను కొనసాగించవచ్చు."}]},{"heading":"మీరు పాల్గొనడానికి అంగీకరిస్తే, ఈ క్రింది సంఘటనలు జరుగుతాయి.","paragraphs":[{"text":"సర్వేః మీ జనాభా, ఆరోగ్య చరిత్ర, జీవనశైలి, కుటుంబ చరిత్రకు సంబంధించిన ఒక ప్రశ్నపత్రాన్ని (టాబ్లెట్/డిజిటల్ పరికరంలో) ఒకసారి పూరించమని అడుగుతారు."},{"text":"ప్రమాదం అంచనాః సర్వే ముగింపులో, మీకు వెంటనే రొమ్ము క్యాన్సర్ ప్రమాదం అంచనా ఇవ్వబడుతుంది (మీరు సాధారణ లేదా అధిక ప్రమాదం ఉన్నారో గుర్తించడం)."},{"text":"మార్గదర్శకత్వంః ప్రమాదం స్థాయి ఆధారంగా మీకు మార్గదర్శకత్వం లభిస్తుంది. మీకు ఎక్కువ ప్రమాదం ఉన్నట్లు గుర్తించినట్లయితే, మీరు మామోగ్రఫీకి పంపబడవచ్చు. మీరు సాధారణ / తక్కువ ప్రమాదం ఉన్నట్లయితే, మీరు సాధారణ తనిఖీ ప్రోటోకాల్లను కొనసాగించమని అడుగుతారు."},{"text":"డేటా వినియోగం: మీ నుండి మరియు ఆసుపత్రి నుండి సేకరించిన డేటా భారతీయ మహిళల్లో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని బాగా అంచనా వేయడానికి కృత్రిమ మేధస్సు (AI) నమూనాను శిక్షణ ఇవ్వడానికి ఉపయోగించబడుతుంది."}]},{"heading":"నేను పాల్గొంటే నాకు ఏమి జరుగుతుంది?","paragraphs":[{"text":"వ్యక్తిగత ప్రమాదం అంచనా మీరు భవిష్యత్తులో ఆరోగ్య పర్యవేక్షణ కోసం సాధ్యం రొమ్ము క్యాన్సర్ లక్షణాలు మరియు మీ వ్యక్తిగత ప్రమాద కారకాలు మరింత తెలుసుకోవడంలో సహాయపడుతుంది."}]},{"heading":"నేను ఏమి చేయాలి?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ఈ కార్యక్రమంలో పాల్గొనడం వల్ల కలిగే నష్టాలు ఏమిటి?","paragraphs":[{"text":"ఈ పరిశోధనలో పాల్గొనడం వల్ల పెద్ద ప్రమాదం లేదు."},{"text":"సంఖ్య/ కనీస ప్రమాదంః ఈ అధ్యయనం \\"నో/ మినిమల్ రిస్క్\\" గా పరిగణించబడుతుంది."},{"text":"గోప్యతః గోప్యతకు సంబంధించి అరుదైన ప్రమాదం ఉంది, కానీ మేము వ్యక్తిగతంగా గుర్తించదగిన సమాచారాన్ని సేకరించడం లేదు మరియు డేటా అనామకంగా సంగ్రహించబడుతుంది."},{"text":"స్వచ్ఛందంగాః ఈ ప్రశ్నాపత్రం పూర్తిగా స్వచ్ఛందంగా ఉంటుంది. మీకు ఆసక్తి లేకపోతే, మీరు సాధారణ క్లినిక్ చికిత్సను కొనసాగించవచ్చు."},{"text":"ఏ ఇన్వాసివ్ విధానాలుః ఇది డిజిటల్ మరియు వర్క్ఫ్లో ఆవిష్కరణ అధ్యయనం; పరిశోధన భాగంలో ప్రయోగాత్మక మందులు లేదా ఇన్వాసివ్ చికిత్సలు పాల్గొనలేదు."}]},{"heading":"పాల్గొనడం వల్ల కలిగే ప్రయోజనాలు ఏమిటి?","paragraphs":[{"text":"వ్యక్తిగత ప్రయోజనంః పాల్గొనేవారికి ప్రత్యక్ష ప్రయోజనం ఉండదు. అయితే, మీ స్క్రీనింగ్ వ్యూహాన్ని తెలియజేయడానికి సహాయపడే ప్రమాదం అంచనాను మీరు అందుకుంటారు."},{"text":"సామాజిక ప్రయోజనం: మీ భాగస్వామ్యం రొమ్ము క్యాన్సర్ ను ప్రారంభంలో గుర్తించడం, భారతదేశం లో మహిళలకు మెరుగైన వనరుల కేటాయింపు వంటి శాస్త్రీయ ప్రయోజనాలకు దోహదం చేస్తుంది."}]},{"heading":"ఈ అధ్యయనంలో నా పాల్గొనడం రహస్యంగా ఉంచుకోబడుతుందా?","paragraphs":[{"text":"అవును. ఈ అధ్యయనంలో సేకరించిన మొత్తం సమాచారం ఖచ్చితంగా గోప్యంగా ఉంటుంది. అన్ని వ్యక్తిగత డేటా వర్తించే డేటా రక్షణ నిబంధనలకు అనుగుణంగా అనామకపరచబడుతుంది మరియు సురక్షితంగా నిల్వ చేయబడుతుంది. అధికారం కలిగిన పరిశోధనా బృందం సభ్యులు మాత్రమే డేటాకు ప్రాప్యత కలిగి ఉంటారు, మరియు మీ వ్యక్తీకరణ అనుమతి లేకుండా వ్యక్తిగత గుర్తింపు సమాచారాన్ని మూడవ పార్టీలతో పంచుకోరు. అధ్యయన ఫలితాలు సంయుక్త రూపంలో మాత్రమే ప్రదర్శించబడతాయి, వ్యక్తిగత పాల్గొనేవారిని గుర్తించలేదని నిర్ధారిస్తుంది."},{"text":"ఐఐ అల్గోరిథంల అంచనా కోసం టానూహే యొక్క బెంచర్మార్కింగ్ మరియు ఓపెన్ డేటా కార్యక్రమంలో భాగంగా, మొత్తం డేటాలో 20% వరకు తిరిగి చెల్లించలేని అనామక పద్ధతిలో సేకరించబడుతుంది. సేకరించిన డేటా భవిష్యత్తులో పరిశోధనలో ఉపయోగించబడుతుంది, ఇందులో ఇతర ఫౌండేషన్ మోడళ్ల అభివృద్ధి కూడా ఉంటుంది."}]},{"heading":"స్వచ్ఛంద భాగస్వామ్యం అంటే ఏమిటి?","paragraphs":[{"text":"మీరు పూర్తిగా స్వచ్ఛందంగా పాల్గొనవచ్చు. మీరు ఎటువంటి జరిమానా లేదా ప్రయోజనాల నష్టం లేకుండా ఎప్పుడైనా పాల్గొనడానికి నిరాకరించవచ్చు లేదా సర్వేను నిలిపివేయవచ్చు."}]},{"heading":"పరిశోధన సంబంధిత గాయాలకు ఏదైనా పరిహారం మరియు వైద్య సంరక్షణ ఉందా?","paragraphs":[{"text":"పరిహారంః ఈ అధ్యయనంలో పాల్గొనడానికి మీకు చెల్లించరు. ఇది కనీస/అపాయం లేని అధ్యయనంగా ఉన్నందున పరిహారం అందించబడదు."},{"text":"గాయంః ఇది సర్వే/AI ఆధారిత స్క్రీనింగ్ అధ్యయనం కాబట్టి, ఇది ఏ విధమైన ఆక్రమణ చర్యలను కలిగి ఉండదు, గాయం కోసం వైద్య చికిత్స లేదా పరిహారం అందించడం ప్రణాళిక చేయబడదు."},{"text":"ఖర్చులుః ఈ అధ్యయనంలో పాల్గొనడానికి మీకు ఎటువంటి ఖర్చు లేదు."}]},{"heading":"పరిశోధన ఫలితాల గురించి ఏమి జరుగుతుంది?","paragraphs":[{"text":"ఈ పరిశోధన అధ్యయనం యొక్క ఫలితాలు AI ప్రారంభించిన రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి సాధనం అభివృద్ధి చేయడానికి మరియు ధృవీకరించడానికి ఉపయోగించబడతాయి. ఫలితాలు పీర్-రివ్యూ చేసిన శాస్త్రీయ పత్రికలలో ప్రచురించబడతాయి, విద్యా సమావేశాలలో ప్రదర్శించబడతాయి మరియు భారతదేశంలో రొమ్ము క్యాన్సర్ స్క్రీనింగ్ పద్ధతులను మెరుగుపరచడానికి ఆరోగ్య సంరక్షణ సంస్థలు మరియు విధాన నిర్మాతలతో పంచుకోవచ్చు. ప్రచురించిన ఫలితాలు ఏ వ్యక్తి గుర్తింపు లేకుండా సంయుక్త రూపంలో ఉంటాయి."}]},{"heading":"పరిశోధన ను ఎవరు నిర్వహిస్తున్నారు, ఎవరు నిధులు సమకూర్చుతున్నారు?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ఈ అధ్యయనాన్ని ఎవరు సమీక్షించారు?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"మరిన్ని సమాచారం కోసం నేను ఎవరిని సంప్రదించగలను?","paragraphs":[{"text":"సంప్రదింపు వివరాలుః ప్రాజెక్ట్ మేనేజర్ డాక్టర్ అశ్విన్ రాజ్ కుమార్"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"మీరు ఈ అధ్యయనానికి సంబంధించి ఒక వ్యక్తితో మాట్లాడాలనుకుంటే, మీరు ఈ క్రింది వాటికి సంప్రదించవచ్చుః"},{"text":"సంస్థాగత నైతిక కమిటీ (ఐఇసి)"},{"text":"పేరు: డాక్టర్ శ్రీ విద్యా జగదీష్, ఐఇసి కార్యదర్శి, తన్యుహ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ఈ అధ్యయనంలో పాల్గొన్నందుకు ధన్యవాదాలు!"}]}],"checkboxLabel":"నేను పాల్గొనేవారి సమాచార పత్రాన్ని చదివాను మరియు అర్థం చేసుకున్నాను మరియు ఈ అధ్యయనంలో పాల్గొనడానికి స్వచ్ఛందంగా అంగీకరిస్తున్నాను.","buttonText":"అంగీకరించు & కొనసాగించు"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'en','{"title":"PARTICIPANT INFORMATION SHEET","headernames":{"studyTitle":"Study Title","sponsor":"Organiser and Funder","iecApproval":"Ethics Review"},"header":{"studyTitle":"Development of an AI enabled Breast Cancer Risk Prediction Tool for the Indian Population","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"About this study","paragraphs":[{"text":"This study is part of a Ministry of Education funded project to develop Indian AI solutions for Healthcare. TANUH Foundation is a section 8 company hosted by Indian Institute of Science proud to lead this critical national initiative in breast cancer research, recognizing that early, data-driven detection is vital for improving health outcomes. We deeply appreciate your participation and thank you for being an essential part of this effort to advance breast cancer study for the benefit of women across India. Make AI in India and Make AI work for India."}]},{"heading":"What is the purpose of the study?","paragraphs":[{"text":"Development of an AI enabled Breast Cancer Risk Prediction Tool for the Indian Population"}]},{"heading":"Why have I been chosen?","paragraphs":[{"text":"You have been chosen to contribute towards the study of AI enabled breast cancer screening tools because you have been referred to mammography or getting a routine mammography. We are developing an AI enabled breast cancer screening tool that enables identification of breast cancer risk by a few questionnaires."}]},{"heading":"Do I have to take part?","paragraphs":[{"text":"Your participation is completely voluntary. You may opt not to participate in the study and continue with your normal routine."}]},{"heading":"What Will Happen in the Study If you agree to participate, the following will occur?","paragraphs":[{"text":"Survey: You will be asked to fill out a one-time questionnaire (on a tablet/digital device) regarding your demographics, health history, lifestyle, and family history of cancer."},{"text":"Risk Prediction: At the end of the survey, you will be provided with an immediate breast cancer risk prediction (identifying if you are at normal or higher risk)."},{"text":"Guidance: Based on the risk level, you will receive guidance. If you are found to be at higher risk, you may be referred for mammography. If you are at normal/low risk, you will be asked to continue regular checkup protocols."},{"text":"Data Usage: The data collected from you and from the hospital will be used to train an Artificial Intelligence (AI) model to better predict breast cancer risk in Indian women."}]},{"heading":"What will happen to me if I take part?","paragraphs":[{"text":"The personalized risk prediction will help you to be more aware of possible breast cancer symptoms and your individual risk factors for future health monitoring."}]},{"heading":"What do I have to do?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"What are the possible risks of taking part?","paragraphs":[{"text":"There are no known major risks in taking part in this research study."},{"text":"No/Minimal Risk: This study is considered \\"no/minimal risk\\"."},{"text":"Privacy: There is a rare risk regarding privacy, but this is mitigated because we do not collect personally identifiable information, and data is captured anonymously."},{"text":"Voluntary: The questionnaire is completely voluntary; if you are not interested, you may pursue routine clinic care instead."},{"text":"No Invasive Procedures: This is a digital and workflow innovation study; no experimental drugs or invasive therapies are involved in the research component."}]},{"heading":"What are the possible benefits of taking part?","paragraphs":[{"text":"Personal Benefit: There is likely no direct benefit for individual participants. However, you will receive a risk prediction that may help inform your screening strategy."},{"text":"Societal Benefit: Your participation will contribute to scientific benefits, including enhanced early detection of breast cancer and better resource allocation for women across India."}]},{"heading":"Will my taking part in this study be kept confidential?","paragraphs":[{"text":"Yes. All information collected during this study will be kept strictly confidential. All personal data will be anonymized and stored securely in accordance with applicable data protection regulations. Only authorized research team members will have access to the data, and no personally identifiable information will be shared with third parties without your explicit consent. The study results will be presented in aggregate form only, ensuring individual participants cannot be identified."},{"text":"About 20% of the total data, collected in an irreversible anonymised manner, will be part of the benchmarking and open data initiative of TANUH for evaluation of AI algorithms. The data collected will be used in future research, including the development of other foundation models."}]},{"heading":"What is voluntary participation?","paragraphs":[{"text":"Your participation is entirely voluntary. You can refuse to participate or stop the survey at any time without penalty or loss of benefits."}]},{"heading":"Are there any compensation and Medical Care for Research-Related Injury?","paragraphs":[{"text":"Compensation: You will not be paid for participating in this study. No compensation is offered as this is a minimal/no-risk study."},{"text":"Injury: As this is a survey/AI-based screening study involving no invasive interventions, no medical treatment or compensation for injury is planned."},{"text":"Costs: There is no cost to you for participating in this study."}]},{"heading":"What will happen to the results of the research study?","paragraphs":[{"text":"The results of this research study will be used to develop and validate an AI enabled Breast Cancer Risk Prediction tool. Findings may be published in peer-reviewed scientific journals, presented at academic conferences, and shared with healthcare institutions and policymakers to improve breast cancer screening practices in India. All published results will be in aggregate form with no individual identification."}]},{"heading":"Who is organising and funding the research?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"Who has reviewed the study?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"Who can I contact for further information?","paragraphs":[{"text":"Contact Details: Dr. Ashwin RaajKumar, Project Manager"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"If you wish to speak to someone independent of the study, you may contact the:"},{"text":"Institutional Ethics Committee (IEC)"},{"text":"Name: Dr. Sri Vidya Jagadish, Secretary, IEC, TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"Thank you for taking part in the study!"}]}],"checkboxLabel":"I have read and understood the Participant Information Sheet and voluntarily agree to participate in this study.","buttonText":"Accept & Continue"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'hi','{"title":"प्रतिभागी सूचना पत्रक","headernames":{"studyTitle":"अध्ययन का शीर्षक","sponsor":"आयोजक और निधि","iecApproval":"नैतिकता की समीक्षा"},"header":{"studyTitle":"भारतीय आबादी के लिए एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण का विकास","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"इस अध्ययन के बारे में","paragraphs":[{"text":"यह अध्ययन स्वास्थ्य सेवा के लिए भारतीय एआई समाधान विकसित करने के लिए शिक्षा मंत्रालय द्वारा वित्त पोषित एक परियोजना का हिस्सा है। TANUH फाउंडेशन भारतीय विज्ञान संस्थान द्वारा होस्ट की गई एक सेक्शन 8 कंपनी है जो स्तन कैंसर अनुसंधान में इस महत्वपूर्ण राष्ट्रीय पहल का नेतृत्व करने पर गर्व करती है, यह पहचानकर कि स्वास्थ्य परिणामों में सुधार के लिए प्रारंभिक, डेटा-संचालित पता लगाना महत्वपूर्ण है। हम आपकी भागीदारी की गहरी सराहना करते हैं और आपको धन्यवाद देते हैं कि आप पूरे भारत में महिलाओं के लाभ के लिए स्तन कैंसर अध्ययन को आगे बढ़ाने के इस प्रयास का एक आवश्यक हिस्सा हैं। भारत में एआई बनाएं और भारत के लिए एआई काम करें।"}]},{"heading":"अध्ययन का उद्देश्य क्या है?","paragraphs":[{"text":"भारतीय आबादी के लिए एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण का विकास"}]},{"heading":"मुझे क्यों चुना गया है?","paragraphs":[{"text":"आपको एआई सक्षम स्तन कैंसर स्क्रीनिंग टूल के अध्ययन में योगदान देने के लिए चुना गया है क्योंकि आपको स्तन कैंसर स्क्रीनिंग टूल के लिए संदर्भित किया गया है या आपको नियमित स्तन कैंसर स्क्रीनिंग टूल दिया गया है। हम एक एआई सक्षम स्तन कैंसर स्क्रीनिंग टूल विकसित कर रहे हैं जो कुछ प्रश्नावली के माध्यम से स्तन कैंसर के जोखिम की पहचान करने में सक्षम बनाता है।"}]},{"heading":"क्या मुझे भाग लेना है?","paragraphs":[{"text":"आपकी भागीदारी पूरी तरह से स्वैच्छिक है। आप अध्ययन में भाग नहीं लेने का विकल्प चुन सकते हैं और अपनी सामान्य दिनचर्या को जारी रख सकते हैं।"}]},{"heading":"अध्ययन में क्या होगा यदि आप भाग लेने के लिए सहमत हों, तो निम्नलिखित होगा?","paragraphs":[{"text":"सर्वेक्षणः आपको अपने जनसांख्यिकीय, स्वास्थ्य इतिहास, जीवन शैली और परिवार के कैंसर के इतिहास के बारे में एक बार का प्रश्नावली (टैबलेट/डिजिटल डिवाइस पर) भरने के लिए कहा जाएगा।"},{"text":"जोखिम पूर्वानुमानः सर्वेक्षण के अंत में, आपको स्तन कैंसर के जोखिम की तत्काल पूर्वानुमान (यह पहचानने के लिए कि क्या आप सामान्य या उच्च जोखिम में हैं) प्रदान किया जाएगा।"},{"text":"मार्गदर्शनः जोखिम के स्तर के आधार पर आपको मार्गदर्शन प्राप्त होगा। यदि आपको अधिक जोखिम में पाया जाता है, तो आपको मैमोग्राफी के लिए भेजा जा सकता है। यदि आप सामान्य/कम जोखिम में हैं, तो आपको नियमित जांच प्रोटोकॉल जारी रखने के लिए कहा जाएगा।"},{"text":"डेटा उपयोगः आपके और अस्पताल से एकत्र किए गए डेटा का उपयोग भारतीय महिलाओं में स्तन कैंसर के जोखिम की बेहतर भविष्यवाणी करने के लिए आर्टिफिशियल इंटेलिजेंस (एआई) मॉडल को प्रशिक्षित करने के लिए किया जाएगा।"}]},{"heading":"यदि मैं भाग लेता हूँ तो मेरे साथ क्या होगा?","paragraphs":[{"text":"व्यक्तिगत जोखिम पूर्वानुमान आपको स्तन कैंसर के संभावित लक्षणों और भविष्य की स्वास्थ्य निगरानी के लिए अपने व्यक्तिगत जोखिम कारकों के बारे में अधिक जागरूक होने में मदद करेगा।"}]},{"heading":"मुझे क्या करना है?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"इसमें भाग लेने के क्या जोखिम हो सकते हैं?","paragraphs":[{"text":"इस शोध अध्ययन में भाग लेने के कोई प्रमुख जोखिम ज्ञात नहीं हैं।"},{"text":"कोई/ न्यूनतम जोखिम नहींः इस अध्ययन को \\"कोई/ न्यूनतम जोखिम\\" माना जाता है।"},{"text":"गोपनीयताः गोपनीयता के संबंध में एक दुर्लभ जोखिम है, लेकिन यह कम किया जाता है क्योंकि हम व्यक्तिगत रूप से पहचान योग्य जानकारी एकत्र नहीं करते हैं, और डेटा गुमनाम रूप से कैप्चर किया जाता है।"},{"text":"स्वैच्छिक: प्रश्नावली पूरी तरह से स्वैच्छिक है; यदि आप रुचि नहीं रखते हैं, तो आप इसके बजाय नियमित चिकित्सा देखभाल कर सकते हैं।"},{"text":"कोई आक्रामक प्रक्रियाएं नहींः यह एक डिजिटल और वर्कफ़्लो नवाचार अध्ययन है; अनुसंधान घटक में कोई प्रयोगात्मक दवाएं या आक्रामक उपचार शामिल नहीं हैं।"}]},{"heading":"भाग लेने से क्या लाभ हो सकते हैं?","paragraphs":[{"text":"व्यक्तिगत लाभः व्यक्तिगत प्रतिभागियों के लिए कोई प्रत्यक्ष लाभ नहीं है। हालांकि, आपको जोखिम का पूर्वानुमान प्राप्त होगा जो आपकी स्क्रीनिंग रणनीति को सूचित करने में मदद कर सकता है।"},{"text":"सामाजिक लाभ: आपकी भागीदारी से वैज्ञानिक लाभों में योगदान होगा, जिसमें स्तन कैंसर का शीघ्र पता लगाना और भारत भर में महिलाओं के लिए संसाधनों का बेहतर आवंटन शामिल है।"}]},{"heading":"क्या इस अध्ययन में मेरी भागीदारी गोपनीय रहेगी?","paragraphs":[{"text":"हां. इस अध्ययन के दौरान एकत्र की गई सभी जानकारी को सख्ती से गोपनीय रखा जाएगा। सभी व्यक्तिगत डेटा को लागू डेटा संरक्षण नियमों के अनुसार गुमनाम किया जाएगा और सुरक्षित रूप से संग्रहीत किया जाएगा। केवल अधिकृत शोध टीम के सदस्यों को डेटा तक पहुंच होगी, और आपकी स्पष्ट सहमति के बिना किसी तीसरे पक्ष के साथ व्यक्तिगत रूप से पहचान योग्य कोई जानकारी साझा नहीं की जाएगी। अध्ययन के परिणाम केवल समग्र रूप में प्रस्तुत किए जाएंगे, जिससे यह सुनिश्चित होगा कि व्यक्तिगत प्रतिभागियों की पहचान नहीं की जा सके।"},{"text":"कुल आंकड़ों में से लगभग 20 प्रतिशत, जो अपरिवर्तनीय रूप से अज्ञात तरीके से एकत्र किए जाएंगे, AI एल्गोरिदम के मूल्यांकन के लिए TANUH की बेंचमार्किंग और ओपन डेटा पहल का हिस्सा होंगे। एकत्र किए गए डेटा का उपयोग भविष्य के अनुसंधान में किया जाएगा, जिसमें अन्य फाउंडेशन मॉडल के विकास भी शामिल है।"}]},{"heading":"स्वैच्छिक भागीदारी क्या है?","paragraphs":[{"text":"आपकी भागीदारी पूरी तरह से स्वैच्छिक है। आप बिना जुर्माना या लाभों के किसी भी समय सर्वेक्षण में भाग लेने से इनकार कर सकते हैं या रोक सकते हैं।"}]},{"heading":"क्या अनुसंधान से संबंधित चोटों के लिए कोई मुआवजा और चिकित्सा देखभाल है?","paragraphs":[{"text":"मुआवजाः इस अध्ययन में भाग लेने के लिए आपको भुगतान नहीं किया जाएगा। कोई मुआवजा नहीं दिया जाता है क्योंकि यह एक न्यूनतम / जोखिम मुक्त अध्ययन है।"},{"text":"चोटः चूंकि यह एक सर्वेक्षण/एआई आधारित स्क्रीनिंग अध्ययन है जिसमें कोई आक्रामक हस्तक्षेप शामिल नहीं है, इसलिए चोट के लिए कोई चिकित्सा उपचार या क्षतिपूर्ति की योजना नहीं है।"},{"text":"लागतः इस अध्ययन में भाग लेने के लिए आपको कोई लागत नहीं है।"}]},{"heading":"अनुसंधान के परिणामों का क्या होगा?","paragraphs":[{"text":"इस शोध अध्ययन के परिणामों का उपयोग एक एआई सक्षम स्तन कैंसर जोखिम पूर्वानुमान उपकरण विकसित करने और सत्यापित करने के लिए किया जाएगा। निष्कर्षों को पीयर-रिव्यू वैज्ञानिक पत्रिकाओं में प्रकाशित किया जा सकता है, शैक्षणिक सम्मेलनों में प्रस्तुत किया जा सकता है, और भारत में स्तन कैंसर स्क्रीनिंग प्रथाओं में सुधार के लिए स्वास्थ्य देखभाल संस्थानों और नीति निर्माताओं के साथ साझा किया जा सकता है। सभी प्रकाशित परिणाम एक समग्र रूप में होंगे, बिना किसी व्यक्तिगत पहचान के।"}]},{"heading":"शोध का आयोजन और वित्तपोषण कौन कर रहा है?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"इस अध्ययन की समीक्षा किसने की है?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"मैं और जानकारी के लिए किससे संपर्क कर सकता हूँ?","paragraphs":[{"text":"संपर्क विवरणः डॉ. अश्विन राजकुमार, परियोजना प्रबंधक"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"यदि आप अध्ययन से स्वतंत्र किसी व्यक्ति से बात करना चाहते हैं, तो आप निम्न से संपर्क कर सकते हैंः"},{"text":"संस्थागत नैतिकता समिति (IEC)"},{"text":"नाम: डॉ. श्री विद्या जगदीश, सचिव, आईईसी, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"अध्ययन में भाग लेने के लिए धन्यवाद!"}]}],"checkboxLabel":"मैंने प्रतिभागियों की सूचना पत्रिका पढ़ी और समझी है और स्वेच्छा से इस अध्ययन में भाग लेने के लिए सहमत हूं।","buttonText":"स्वीकार करें और आगे बढ़ें"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'bn','{"title":"অংশগ্রহণকারী তথ্য পত্রিকা","headernames":{"studyTitle":"অধ্যয়নের শিরোনাম","sponsor":"সংগঠক ও তহবিল","iecApproval":"নৈতিকতার পর্যালোচনা"},"header":{"studyTitle":"ভারতীয় জনসংখ্যার জন্য একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"এই গবেষণার বিষয়ে","paragraphs":[{"text":"এই গবেষণাটি স্বাস্থ্যসেবা জন্য ভারতীয় এআই সমাধান বিকাশের জন্য শিক্ষা মন্ত্রকের অর্থায়িত প্রকল্পের অংশ। তানুহ ফাউন্ডেশন একটি বিভাগ 8 সংস্থা যা ভারতীয় বিজ্ঞান ইনস্টিটিউট দ্বারা হোস্ট করা হয় এবং স্তন ক্যান্সারের গবেষণায় এই গুরুত্বপূর্ণ জাতীয় উদ্যোগের নেতৃত্ব দিতে গর্বিত, স্বাস্থ্যের ফলাফল উন্নত করতে প্রাথমিক, ডেটা-চালিত সনাক্তকরণ অত্যন্ত গুরুত্বপূর্ণ। আমরা আপনার অংশগ্রহণের গভীর প্রশংসা করি এবং সারা ভারত জুড়ে মহিলাদের সুবিধার্থে স্তন ক্যান্সারের গবেষণাকে এগিয়ে নেওয়ার এই প্রচেষ্টার একটি অপরিহার্য অংশ হওয়ার জন্য আপনাকে ধন্যবাদ জানাই। ভারতে এআই তৈরি করুন এবং ভারতে এআই কাজ করুন।"}]},{"heading":"অধ্যয়নের উদ্দেশ্য কী?","paragraphs":[{"text":"ভারতীয় জনসংখ্যার জন্য একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ"}]},{"heading":"কেন আমাকে বেছে নেওয়া হয়েছে?","paragraphs":[{"text":"আপনি এআই-সক্ষম স্তন ক্যান্সার স্ক্রিনিং সরঞ্জামগুলির গবেষণায় অবদান রাখতে নির্বাচিত হয়েছেন কারণ আপনাকে ম্যামোগ্রাফি বা রুটিন ম্যামোগ্রাফি করার জন্য উল্লেখ করা হয়েছে। আমরা একটি এআই-সক্ষম স্তন ক্যান্সার স্ক্রিনিং সরঞ্জাম বিকাশ করছি যা কয়েকটি প্রশ্নাবলীর মাধ্যমে স্তন ক্যান্সার ঝুঁকি সনাক্ত করতে সক্ষম করে।"}]},{"heading":"আমাকে কি অংশ নিতে হবে?","paragraphs":[{"text":"আপনি স্বেচ্ছায় এই গবেষণায় অংশগ্রহণ করতে পারবেন না এবং আপনার স্বাভাবিক রুটিন অনুসরণ করতে পারেন।"}]},{"heading":"অধ্যয়নে কি ঘটবে যদি আপনি অংশ নিতে রাজি হন, তাহলে নিম্নলিখিত ঘটনা ঘটবে?","paragraphs":[{"text":"জরিপঃ আপনার জনসংখ্যা, স্বাস্থ্য ইতিহাস, জীবনযাত্রা এবং ক্যান্সারের পরিবারের ইতিহাস সম্পর্কে আপনাকে একটি একক প্রশ্নপত্র (ট্যাবলেট/ডিজিটাল ডিভাইসে) পূরণ করতে বলা হবে।"},{"text":"ঝুঁকি পূর্বাভাসঃ সমীক্ষার শেষে, আপনাকে অবিলম্বে স্তন ক্যান্সারের ঝুঁকি পূর্বাভাস দেওয়া হবে (যদি আপনি স্বাভাবিক বা উচ্চ ঝুঁকিতে থাকেন তা সনাক্ত করা হবে) ।"},{"text":"নির্দেশনাঃ ঝুঁকি স্তরের উপর ভিত্তি করে, আপনাকে নির্দেশনা দেওয়া হবে। যদি আপনার ঝুঁকি বেশি থাকে তবে আপনাকে ম্যামোগ্রাফি করার জন্য রেফার করা যেতে পারে। যদি আপনার ঝুঁকি স্বাভাবিক/কম থাকে তবে আপনাকে নিয়মিত চেকআপ প্রোটোকল চালিয়ে যেতে বলা হবে।"},{"text":"ডেটা ব্যবহারঃ আপনার এবং হাসপাতালের কাছ থেকে সংগৃহীত তথ্যগুলি ভারতীয় মহিলাদের স্তন ক্যান্সারের ঝুঁকি আরও ভালভাবে পূর্বাভাস দেওয়ার জন্য একটি কৃত্রিম বুদ্ধিমত্তা (এআই) মডেল প্রশিক্ষণের জন্য ব্যবহৃত হবে।"}]},{"heading":"আমি অংশগ্রহণ করলে আমার কি হবে?","paragraphs":[{"text":"ব্যক্তিগতকৃত ঝুঁকি পূর্বাভাস আপনাকে স্তন ক্যান্সারের সম্ভাব্য লক্ষণ এবং ভবিষ্যতে স্বাস্থ্য পর্যবেক্ষণের জন্য আপনার পৃথক ঝুঁকিপূর্ণ কারণগুলি সম্পর্কে আরও সচেতন হতে সহায়তা করবে।"}]},{"heading":"আমি কি করব?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"অংশগ্রহণের ঝুঁকি কি?","paragraphs":[{"text":"এই গবেষণায় অংশগ্রহণের ক্ষেত্রে কোন বড় ঝুঁকি নেই।"},{"text":"কোন ঝুঁকি নেই/মিনিমাল ঝুঁকিঃ এই গবেষণাটি \\"কোন ঝুঁকি নেই/মিনিমাল ঝুঁকি\\" বলে বিবেচিত হয়।"},{"text":"গোপনীয়তাঃ গোপনীয়তার ক্ষেত্রে একটি বিরল ঝুঁকি রয়েছে, কিন্তু এটি হ্রাস করা হয় কারণ আমরা ব্যক্তিগতভাবে সনাক্তযোগ্য তথ্য সংগ্রহ করি না এবং তথ্য অজানাভাবে সংরক্ষণ করা হয়।"},{"text":"স্বেচ্ছাসেবকঃ এই প্রশ্নাবলীটি সম্পূর্ণ স্বেচ্ছাসেবক; যদি আপনি আগ্রহী না হন, তাহলে আপনি নিয়মিত ক্লিনিকাল যত্ন নিতে পারেন।"},{"text":"কোন আক্রমণাত্মক পদ্ধতি নেইঃ এটি একটি ডিজিটাল এবং কর্মপ্রবাহের উদ্ভাবনী গবেষণা; গবেষণার উপাদানটিতে কোন পরীক্ষামূলক ওষুধ বা আক্রমণাত্মক থেরাপি জড়িত নয়।"}]},{"heading":"অংশগ্রহণের সম্ভাব্য উপকারিতা কি কি?","paragraphs":[{"text":"ব্যক্তিগত উপকারিতাঃ প্রত্যক্ষভাবে অংশগ্রহণকারীদের কোন উপকারিতা নেই। তবে আপনি একটি ঝুঁকি পূর্বাভাস পাবেন যা আপনার স্ক্রিনিং কৌশলকে অবহিত করতে সহায়তা করতে পারে।"},{"text":"সামাজিক সুবিধাঃ আপনার অংশগ্রহণে বৈজ্ঞানিক সুবিধার জন্য অবদান থাকবে, যার মধ্যে রয়েছে স্তন ক্যান্সারের প্রাথমিক সনাক্তকরণ এবং সারা ভারত জুড়ে মহিলাদের জন্য আরও ভাল সম্পদ বরাদ্দ।"}]},{"heading":"এই গবেষণায় আমার অংশগ্রহণ কি গোপন থাকবে?","paragraphs":[{"text":"হ্যাঁ. এই গবেষণার সময় সংগৃহীত সমস্ত তথ্য কঠোরভাবে গোপনীয় রাখা হবে। সমস্ত ব্যক্তিগত তথ্য প্রযোজ্য ডেটা সুরক্ষা বিধি অনুসারে অ্যানোনিমেড এবং সুরক্ষিতভাবে সংরক্ষণ করা হবে। শুধুমাত্র অনুমোদিত গবেষণা দলের সদস্যদের ডেটাতে অ্যাক্সেস থাকবে, এবং আপনার স্পষ্ট সম্মতি ছাড়া কোনও ব্যক্তিগত সনাক্তকরণযোগ্য তথ্য তৃতীয় পক্ষের সাথে ভাগ করা হবে না। গবেষণার ফলাফলগুলি কেবল সামগ্রিক আকারে উপস্থাপন করা হবে, যাতে পৃথক অংশগ্রহণকারীদের সনাক্ত করা যায় না।"},{"text":"মোট তথ্যের প্রায় ২০% অবদান থাকবে, যা অনিবার্যভাবে অ্যানোনিমেটেডভাবে সংগ্রহ করা হবে। এই তথ্যগুলি এআই অ্যালগরিদমগুলির মূল্যায়নের জন্য TANUH এর ব্যানচমার্কিং এবং ওপেন ডেটা ইনিশিয়েটিভের অংশ হবে। সংগ্রহ করা তথ্যগুলি ভবিষ্যতে গবেষণায় ব্যবহার করা হবে, অন্যান্য ভিত্তি মডেলগুলির বিকাশ সহ।"}]},{"heading":"স্বেচ্ছাসেবী অংশগ্রহণ কি?","paragraphs":[{"text":"আপনি যে কোনো সময় জরিপে অংশগ্রহণ করতে অস্বীকার করতে পারেন অথবা বিনা জরিপে বা বেতনের ক্ষতি ছাড়াই এ জরিপে অংশগ্রহণ বন্ধ করতে পারেন।"}]},{"heading":"গবেষণা সংক্রান্ত আঘাতের জন্য কি কোন ক্ষতিপূরণ ও চিকিৎসা আছে?","paragraphs":[{"text":"ক্ষতিপূরণঃ এই গবেষণায় অংশগ্রহণের জন্য আপনাকে কোনো বেতন দেওয়া হবে না। কোন ক্ষতিপূরণ দেওয়া হয় না কারণ এটি একটি ন্যূনতম/নিরাপদ গবেষণা।"},{"text":"আঘাতঃ এটি একটি জরিপ/এআই ভিত্তিক স্ক্রিনিং স্টাডি যা কোনও আক্রমণাত্মক হস্তক্ষেপ জড়িত নয়, আঘাতের জন্য কোনও চিকিৎসা বা ক্ষতিপূরণ পরিকল্পনা করা হয়নি।"},{"text":"খরচঃ এই গবেষণায় অংশগ্রহণের জন্য আপনার কোন খরচ নেই।"}]},{"heading":"গবেষণার ফলাফল কি হবে?","paragraphs":[{"text":"এই গবেষণার ফলাফলগুলি একটি এআই সক্ষম স্তন ক্যান্সার ঝুঁকি পূর্বাভাস সরঞ্জাম বিকাশ এবং বৈধ করার জন্য ব্যবহৃত হবে। ফলাফলগুলি সমকালীন পর্যালোচনা করা বৈজ্ঞানিক জার্নালগুলিতে প্রকাশিত হতে পারে, একাডেমিক সম্মেলনে উপস্থাপন করা যেতে পারে এবং ভারতে স্তন ক্যান্সার স্ক্রিনিং অনুশীলনগুলি উন্নত করতে স্বাস্থ্যসেবা প্রতিষ্ঠান এবং নীতি নির্ধারকদের সাথে ভাগ করা যেতে পারে। সমস্ত প্রকাশিত ফলাফলগুলি কোনও পৃথক সনাক্তকরণ ছাড়াই সমষ্টিগত আকারে হবে।"}]},{"heading":"গবেষণা কে পরিচালনা করছে এবং কে এর অর্থায়ন করছে?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"কে এই গবেষণাটি পর্যালোচনা করেছে?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"আমি কার সাথে যোগাযোগ করতে পারি?","paragraphs":[{"text":"যোগাযোগের তথ্যঃ প্রকল্প পরিচালক ডাঃ অশ্বিন রাজকুমার"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"আপনি যদি গবেষণার বাইরে কারো সাথে কথা বলতে চান, তাহলে আপনি নিম্নলিখিত বিষয়গুলো নিয়ে যোগাযোগ করতে পারেনঃ"},{"text":"প্রাতিষ্ঠানিক নীতিগত কমিটি (আইইসি)"},{"text":"নামঃ ডঃ শ্রী বিদ্যা জগদীশ, আইইসি, তানুহের সচিব"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"অধ্যয়নে অংশগ্রহণের জন্য আপনাকে ধন্যবাদ!"}]}],"checkboxLabel":"আমি অংশগ্রহণকারীদের তথ্যপত্র পড়েছি এবং বুঝতে পেরেছি এবং স্বেচ্ছায় এই গবেষণায় অংশগ্রহণ করতে রাজি হয়েছি।","buttonText":"গ্রহণ করুন এবং চালিয়ে যান"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'gu','{"title":"સહભાગી માહિતી શીટ","headernames":{"studyTitle":"અભ્યાસનું શીર્ષક","sponsor":"આયોજક અને ફંડ","iecApproval":"નૈતિકતા સમીક્ષા"},"header":{"studyTitle":"ભારતીય વસ્તી માટે એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવું","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"આ અભ્યાસ વિશે","paragraphs":[{"text":"આ અભ્યાસ આરોગ્યસંભાળ માટે ભારતીય એઆઈ ઉકેલો વિકસાવવા માટે શિક્ષણ મંત્રાલય દ્વારા ભંડોળ પૂરું પાડવામાં આવેલા પ્રોજેક્ટનો ભાગ છે. ભારતીય ઇન્સ્ટિટ્યૂટ ઓફ સાયન્સ દ્વારા આયોજિત થનૂહ ફાઉન્ડેશન એક વિભાગ 8 કંપની છે. સ્તન કેન્સર સંશોધન માટે આ મહત્વપૂર્ણ રાષ્ટ્રીય પહેલનું નેતૃત્વ કરવા માટે ગર્વ અનુભવે છે, તે માન્યતા આપે છે કે આરોગ્ય પરિણામોમાં સુધારો કરવા માટે પ્રારંભિક, ડેટા આધારિત શોધ મહત્વપૂર્ણ છે. અમે તમારી ભાગીદારીની ખૂબ પ્રશંસા કરીએ છીએ અને સમગ્ર ભારતમાં મહિલાઓના લાભ માટે સ્તન કેન્સર અભ્યાસને આગળ વધારવા માટે આ પ્રયાસનો આવશ્યક ભાગ હોવા બદલ આભાર. ભારતમાં એઆઈ બનાવો અને ભારત માટે એઆઈ કાર્ય કરો."}]},{"heading":"અભ્યાસનો હેતુ શું છે?","paragraphs":[{"text":"ભારતીય વસ્તી માટે એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવું"}]},{"heading":"મને કેમ પસંદ કરવામાં આવ્યો છે?","paragraphs":[{"text":"તમને એઆઈ સક્ષમ સ્તન કેન્સર સ્ક્રિનિંગ ટૂલ્સના અભ્યાસમાં યોગદાન આપવા માટે પસંદ કરવામાં આવ્યા છે કારણ કે તમને મેમોગ્રાફી અથવા નિયમિત મેમોગ્રાફી આપવામાં આવી છે. અમે એઆઈ સક્ષમ સ્તન કેન્સર સ્ક્રિનિંગ ટૂલ વિકસિત કરી રહ્યા છીએ જે થોડા પ્રશ્નાવલિઓ દ્વારા સ્તન કેન્સરનું જોખમ ઓળખવા માટે સક્ષમ બનાવે છે."}]},{"heading":"શું મારે ભાગ લેવો પડશે?","paragraphs":[{"text":"તમે અભ્યાસમાં ભાગ લેવાનું પસંદ કરી શકો છો અને તમારી સામાન્ય નિયમિતતા સાથે ચાલુ રાખી શકો છો."}]},{"heading":"શું થશે?","paragraphs":[{"text":"સર્વેક્ષણઃ તમને તમારા વસ્તી વિષયક, સ્વાસ્થ્ય ઇતિહાસ, જીવનશૈલી અને કુટુંબના કેન્સર ઇતિહાસ વિશે એક વખતનો પ્રશ્નાવલિ (ટેબ્લેટ / ડિજિટલ ઉપકરણ પર) ભરવા માટે કહેવામાં આવશે."},{"text":"જોખમ આગાહીઃ સર્વેક્ષણના અંતે, તમને સ્તન કેન્સરનું જોખમ તાત્કાલિક આગાહી આપવામાં આવશે (જો તમે સામાન્ય અથવા વધુ જોખમ ધરાવો છો તો ઓળખવા માટે)."},{"text":"માર્ગદર્શનઃ જોખમ સ્તરના આધારે તમને માર્ગદર્શન આપવામાં આવશે. જો તમને વધુ જોખમ હોવાનું જાણવા મળ્યું હોય, તો તમને મેમોગ્રાફી માટે રેફર કરી શકાય છે. જો તમે સામાન્ય / નીચા જોખમ પર છો, તો તમને નિયમિત તપાસ પ્રોટોકોલ ચાલુ રાખવા માટે કહેવામાં આવશે."},{"text":"ડેટા વપરાશઃ તમારા અને હોસ્પિટલમાંથી એકત્રિત કરવામાં આવેલા ડેટાનો ઉપયોગ ભારતીય મહિલાઓમાં સ્તન કેન્સરનું જોખમ વધુ સારી રીતે આગાહી કરવા માટે કૃત્રિમ બુદ્ધિ (AI) મોડેલને તાલીમ આપવા માટે કરવામાં આવશે."}]},{"heading":"જો હું ભાગ લઈશ તો મને શું થશે?","paragraphs":[{"text":"વ્યક્તિગત જોખમ આગાહી તમને ભવિષ્યમાં આરોગ્યની દેખરેખ માટે સંભવિત સ્તન કેન્સર લક્ષણો અને તમારા વ્યક્તિગત જોખમ પરિબળો વિશે વધુ જાગૃત કરવામાં મદદ કરશે."}]},{"heading":"મારે શું કરવું છે?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ભાગ લેવાનું જોખમ શું છે?","paragraphs":[{"text":"આ સંશોધન અભ્યાસમાં ભાગ લેવાથી કોઈ મોટા જોખમો જાણીતા નથી."},{"text":"કોઈ / ન્યૂનતમ જોખમઃ આ અભ્યાસને \\"કોઈ / ન્યૂનતમ જોખમ\\" ગણવામાં આવે છે."},{"text":"ગોપનીયતાઃ ગોપનીયતા સંબંધિત એક દુર્લભ જોખમ છે, પરંતુ આ ઘટાડવામાં આવે છે કારણ કે અમે વ્યક્તિગત રૂપે ઓળખી શકાય તેવી માહિતી એકત્રિત કરતા નથી, અને ડેટા અનામી રીતે મેળવવામાં આવે છે."},{"text":"સ્વૈચ્છિકઃ પ્રશ્નાવલિ સંપૂર્ણપણે સ્વૈચ્છિક છે; જો તમને રસ ન હોય તો, તમે તેના બદલે નિયમિત ક્લિનિકલ સંભાળ મેળવી શકો છો."},{"text":"કોઈ આક્રમક કાર્યવાહી નથીઃ આ ડિજિટલ અને વર્કફ્લો નવીનતા અભ્યાસ છે; સંશોધન ઘટકમાં કોઈ પ્રાયોગિક દવાઓ અથવા આક્રમક ઉપચાર સામેલ નથી."}]},{"heading":"ભાગ લેવાથી શું ફાયદો થઈ શકે?","paragraphs":[{"text":"વ્યક્તિગત લાભઃ વ્યક્તિગત સહભાગીઓ માટે કોઈ સીધો લાભ હોતો નથી. જો કે, તમને જોખમ આગાહી મળશે જે તમારી સ્ક્રીનીંગ વ્યૂહરચનાને જાણવામાં મદદ કરી શકે છે."},{"text":"સામાજિક લાભ: તમારી ભાગીદારીથી વૈજ્ઞાનિક લાભો પ્રાપ્ત થશે, જેમાં સ્તન કેન્સરનું પ્રારંભિક નિદાન વધારવામાં આવશે અને સમગ્ર ભારતમાં મહિલાઓ માટે વધુ સારા સંસાધનોનું ફાળવણી કરવામાં આવશે."}]},{"heading":"શું આ અભ્યાસમાં મારી ભાગીદારી ગુપ્ત રાખવામાં આવશે?","paragraphs":[{"text":"હા. આ અભ્યાસ દરમિયાન એકત્રિત કરવામાં આવેલી તમામ માહિતી સખત ગુપ્ત રાખવામાં આવશે. તમામ વ્યક્તિગત ડેટાને લાગુ ડેટા સંરક્ષણ નિયમો અનુસાર અનામીકરણ કરવામાં આવશે અને સુરક્ષિત રીતે સંગ્રહિત કરવામાં આવશે. ફક્ત અધિકૃત સંશોધન ટીમના સભ્યો જ ડેટાની ઍક્સેસ કરશે, અને તમારી સ્પષ્ટ સંમતિ વિના કોઈ વ્યક્તિગત રૂપે ઓળખી શકાય તેવી માહિતી તૃતીય પક્ષો સાથે શેર કરવામાં આવશે નહીં. અભ્યાસના પરિણામો ફક્ત એકંદર સ્વરૂપમાં રજૂ કરવામાં આવશે, જે વ્યક્તિગત સહભાગીઓની ઓળખ કરી શકાતી નથી તેની ખાતરી કરશે."},{"text":"કુલ ડેટાના આશરે 20% અનિવાર્ય રીતે અનામી રીતે એકત્રિત કરવામાં આવશે, જે AI અલ્ગોરિધમ્સના મૂલ્યાંકન માટે TANUH ની બેંચમાર્કિંગ અને ઓપન ડેટા પહેલનો ભાગ હશે."}]},{"heading":"સ્વૈચ્છિક ભાગીદારી શું છે?","paragraphs":[{"text":"તમારી ભાગીદારી સંપૂર્ણપણે સ્વૈચ્છિક છે. તમે કોઈપણ સમયે દંડ અથવા લાભો ગુમાવ્યા વગર મતદાનમાં ભાગ લેવાનો ઇનકાર કરી શકો છો અથવા બંધ કરી શકો છો."}]},{"heading":"શું સંશોધન સંબંધિત ઈજાઓ માટે કોઈ વળતર અને તબીબી સંભાળ છે?","paragraphs":[{"text":"વળતરઃ આ અભ્યાસમાં ભાગ લેવા માટે તમને ચૂકવણી કરવામાં આવશે નહીં. કોઈ વળતર આપવામાં આવતું નથી કારણ કે આ એક ન્યૂનતમ / કોઈ જોખમ વિનાનું અભ્યાસ છે."},{"text":"ઈજાઃ કારણ કે આ એક સર્વેક્ષણ/AI આધારિત સ્ક્રીનીંગ સ્ટડી છે જેમાં કોઈ આક્રમક હસ્તક્ષેપ સામેલ નથી, ઇજા માટે કોઈ તબીબી સારવાર અથવા વળતરની યોજના નથી."},{"text":"ખર્ચઃ આ અભ્યાસમાં ભાગ લેવા માટે તમને કોઈ ખર્ચ નથી."}]},{"heading":"સંશોધનના પરિણામોનું શું થશે?","paragraphs":[{"text":"આ સંશોધન અભ્યાસના પરિણામોનો ઉપયોગ એઆઈ સક્ષમ સ્તન કેન્સર જોખમ આગાહી સાધન વિકસાવવા અને માન્ય કરવા માટે કરવામાં આવશે. પરિણામો પીઅર-રીવ્યુ કરેલ વૈજ્ઞાનિક સામયિકોમાં પ્રકાશિત થઈ શકે છે, શૈક્ષણિક પરિષદોમાં રજૂ કરી શકાય છે, અને ભારતમાં સ્તન કેન્સર સ્ક્રિનિંગ પદ્ધતિઓમાં સુધારો કરવા માટે આરોગ્યસંભાળ સંસ્થાઓ અને નીતિ ઘડવૈયાઓ સાથે શેર કરી શકાય છે. બધા પ્રકાશિત પરિણામો વ્યક્તિગત ઓળખ વિના એકંદર સ્વરૂપમાં હશે."}]},{"heading":"સંશોધનનું આયોજન અને ભંડોળ કોણ આપે છે?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"કોણે આ અભ્યાસની સમીક્ષા કરી છે?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"વધુ માહિતી માટે હું કોનો સંપર્ક કરી શકું?","paragraphs":[{"text":"સંપર્ક વિગતો: ડૉ. અશ્વિન રજકુમાર, પ્રોજેક્ટ મેનેજર"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"જો તમે અભ્યાસથી સ્વતંત્ર વ્યક્તિ સાથે વાત કરવા માંગતા હો, તો તમે નીચેનાનો સંપર્ક કરી શકો છોઃ"},{"text":"સંસ્થાકીય નીતિશાસ્ત્ર સમિતિ (IEC)"},{"text":"નામઃ ડૉ. શ્રી વિદ્યા જગદીશ, આઇઇસી, તાનૂહના સચિવ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"અભ્યાસમાં ભાગ લેવા બદલ આભાર!"}]}],"checkboxLabel":"મેં સહભાગી માહિતી શીટ વાંચી અને સમજી છે અને આ અભ્યાસમાં ભાગ લેવા માટે સ્વૈચ્છિક રીતે સંમત છું.","buttonText":"સ્વીકારો અને ચાલુ રાખો"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'kn','{"title":"ಭಾಗವಹಿಸುವವರ ಮಾಹಿತಿ ಹಾಳೆ","headernames":{"studyTitle":"ಅಧ್ಯಯನದ ಶೀರ್ಷಿಕೆ","sponsor":"ಸಂಘಟಕ ಮತ್ತು ನಿಧಿ","iecApproval":"ನೈತಿಕತೆ ವಿಮರ್ಶೆ"},"header":{"studyTitle":"ಭಾರತೀಯ ಜನಸಂಖ್ಯೆಗೆ ಎಐ ಸಕ್ರಿಯಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಸಾಧನ ಅಭಿವೃದ್ಧಿ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ಈ ಅಧ್ಯಯನದ ಬಗ್ಗೆ","paragraphs":[{"text":"ಈ ಅಧ್ಯಯನವು ಆರೋಗ್ಯ ರಕ್ಷಣೆಗಾಗಿ ಭಾರತೀಯ AI ಪರಿಹಾರಗಳನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸುವ ಶಿಕ್ಷಣ ಸಚಿವಾಲಯದ ನಿಧಿಸಂಗ್ರಹಿತ ಯೋಜನೆಯ ಭಾಗವಾಗಿದೆ. TANUH ಫೌಂಡೇಶನ್ ಭಾರತೀಯ ವಿಜ್ಞಾನ ಸಂಸ್ಥೆ ಆಯೋಜಿಸಿದ ವಿಭಾಗ 8 ಕಂಪನಿಯಾಗಿದ್ದು, ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸಂಶೋಧನೆಯಲ್ಲಿ ಈ ನಿರ್ಣಾಯಕ ರಾಷ್ಟ್ರೀಯ ಉಪಕ್ರಮವನ್ನು ಮುನ್ನಡೆಸಲು ಹೆಮ್ಮೆಪಡುತ್ತದೆ. ಆರೋಗ್ಯ ಫಲಿತಾಂಶಗಳನ್ನು ಸುಧಾರಿಸಲು ಆರಂಭಿಕ, ಡೇಟಾ ಆಧಾರಿತ ಪತ್ತೆ ಅತ್ಯಗತ್ಯ ಎಂದು ಗುರುತಿಸುತ್ತದೆ. ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಧ್ಯಯನವನ್ನು ಭಾರತದಾದ್ಯಂತ ಮಹಿಳೆಯರ ಅನುಕೂಲಕ್ಕಾಗಿ ಮುನ್ನಡೆಸಲು ಈ ಪ್ರಯತ್ನದಲ್ಲಿ ನೀವು ಪ್ರಮುಖ ಭಾಗವಾಗಿರುವುದಕ್ಕಾಗಿ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ನಾವು ಆಳವಾಗಿ ಪ್ರಶಂಸಿಸುತ್ತೇವೆ ಮತ್ತು ಧನ್ಯವಾದಗಳು. ಭಾರತದಲ್ಲಿ AI ಅನ್ನು ಮಾಡಿ ಮತ್ತು AI ಅನ್ನು ಭಾರತಕ್ಕಾಗಿ ಕೆಲಸ ಮಾಡಿ."}]},{"heading":"ಅಧ್ಯಯನದ ಉದ್ದೇಶವೇನು?","paragraphs":[{"text":"ಭಾರತೀಯ ಜನಸಂಖ್ಯೆಗೆ ಎಐ ಸಕ್ರಿಯಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಸಾಧನ ಅಭಿವೃದ್ಧಿ"}]},{"heading":"ನನ್ನನ್ನು ಯಾಕೆ ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ?","paragraphs":[{"text":"ನೀವು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಉಪಕರಣಗಳ ಅಧ್ಯಯನಕ್ಕೆ ಕೊಡುಗೆ ನೀಡಲು ಆಯ್ಕೆ ಮಾಡಲಾಗಿದೆ ಏಕೆಂದರೆ ನಿಮಗೆ ಸ್ತನಗ್ರಹಣ ಅಥವಾ ವಾಡಿಕೆಯ ಸ್ತನಗ್ರಹಣವನ್ನು ಮಾಡಲಾಗಿದೆ. ನಾವು ಕೆಲವು ಪ್ರಶ್ನಾವಳಿಗಳ ಮೂಲಕ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯವನ್ನು ಗುರುತಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುವ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಉಪಕರಣವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸುತ್ತಿದ್ದೇವೆ."}]},{"heading":"ನಾನು ಭಾಗವಹಿಸಬೇಕೇ?","paragraphs":[{"text":"ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸದೆ ನಿಮ್ಮ ಸಾಮಾನ್ಯ ವಾಡಿಕೆಯಂತೆ ಮುಂದುವರಿಯಬಹುದು."}]},{"heading":"ಅಧ್ಯಯನದಲ್ಲಿ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ಸಮೀಕ್ಷೆಃ ನಿಮ್ಮ ಜನಸಂಖ್ಯಾಶಾಸ್ತ್ರ, ಆರೋಗ್ಯ ಇತಿಹಾಸ, ಜೀವನಶೈಲಿ ಮತ್ತು ಕ್ಯಾನ್ಸರ್ನ ಕುಟುಂಬದ ಇತಿಹಾಸದ ಬಗ್ಗೆ ಒಂದು ಬಾರಿ (ಟ್ಯಾಬ್ಲೆಟ್/ಡಿಜಿಟಲ್ ಸಾಧನದಲ್ಲಿ) ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಭರ್ತಿ ಮಾಡಲು ನಿಮ್ಮನ್ನು ಕೇಳಲಾಗುತ್ತದೆ."},{"text":"ಅಪಾಯದ ಮುನ್ಸೂಚನೆಃ ಸಮೀಕ್ಷೆಯ ಕೊನೆಯಲ್ಲಿ, ನಿಮಗೆ ತಕ್ಷಣದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯದ ಮುನ್ಸೂಚನೆ ನೀಡಲಾಗುವುದು (ನೀವು ಸಾಮಾನ್ಯ ಅಥವಾ ಹೆಚ್ಚಿನ ಅಪಾಯದಲ್ಲಿದ್ದರೆ ಗುರುತಿಸುವುದು)."},{"text":"ಮಾರ್ಗದರ್ಶನಃ ಅಪಾಯದ ಮಟ್ಟದ ಆಧಾರದ ಮೇಲೆ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲಾಗುವುದು. ನೀವು ಹೆಚ್ಚಿನ ಅಪಾಯದಲ್ಲಿದ್ದರೆ, ನಿಮಗೆ ಸ್ತನಗ್ರಹಣಕ್ಕೆ ಉಲ್ಲೇಖಿಸಬಹುದು. ನೀವು ಸಾಮಾನ್ಯ / ಕಡಿಮೆ ಅಪಾಯದಲ್ಲಿದ್ದರೆ, ನಿಯಮಿತ ತಪಾಸಣೆ ಪ್ರೋಟೋಕಾಲ್ಗಳನ್ನು ಮುಂದುವರಿಸಲು ನಿಮ್ಮನ್ನು ಕೇಳಲಾಗುತ್ತದೆ."},{"text":"ಡೇಟಾ ಬಳಕೆಃ ನಿಮ್ಮಿಂದ ಮತ್ತು ಆಸ್ಪತ್ರೆಯಿಂದ ಸಂಗ್ರಹಿಸಲಾದ ಡೇಟಾವನ್ನು ಭಾರತೀಯ ಮಹಿಳೆಯರಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯವನ್ನು ಉತ್ತಮವಾಗಿ ಊಹಿಸಲು ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ (AI) ಮಾದರಿಯನ್ನು ತರಬೇತಿ ನೀಡಲು ಬಳಸಲಾಗುತ್ತದೆ."}]},{"heading":"ನಾನು ಭಾಗವಹಿಸಿದರೆ ನನಗೆ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ವೈಯಕ್ತಿಕಗೊಳಿಸಿದ ಅಪಾಯ ಮುನ್ಸೂಚನೆಯು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ನ ಸಂಭವನೀಯ ಲಕ್ಷಣಗಳ ಬಗ್ಗೆ ಮತ್ತು ಭವಿಷ್ಯದ ಆರೋಗ್ಯ ಮೇಲ್ವಿಚಾರಣೆಗಾಗಿ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಅಪಾಯಕಾರಿ ಅಂಶಗಳ ಬಗ್ಗೆ ಹೆಚ್ಚು ಜಾಗೃತರಾಗಲು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ."}]},{"heading":"ನಾನು ಏನು ಮಾಡಬೇಕು?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ಭಾಗವಹಿಸುವಿಕೆಯು ಯಾವ ಅಪಾಯಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದು?","paragraphs":[{"text":"ಈ ಸಂಶೋಧನಾ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸುವಿಕೆಯು ಯಾವುದೇ ಪ್ರಮುಖ ಅಪಾಯಗಳನ್ನು ಹೊಂದಿಲ್ಲ."},{"text":"ಯಾವುದೇ/ಕಡಿಮೆ ಅಪಾಯಃ ಈ ಅಧ್ಯಯನವನ್ನು \\"ಯಾವುದೇ/ಕಡಿಮೆ ಅಪಾಯ\\" ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ."},{"text":"ಗೌಪ್ಯತೆಃ ಗೌಪ್ಯತೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಅಪರೂಪದ ಅಪಾಯವಿದೆ, ಆದರೆ ನಾವು ವೈಯಕ್ತಿಕವಾಗಿ ಗುರುತಿಸಬಹುದಾದ ಮಾಹಿತಿಯನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ ಮತ್ತು ಡೇಟಾವನ್ನು ಅನಾಮಧೇಯವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ."},{"text":"ಸ್ವಯಂಪ್ರೇರಿತಃ ಪ್ರಶ್ನಾವಳಿಯು ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ; ನಿಮಗೆ ಆಸಕ್ತಿ ಇಲ್ಲದಿದ್ದರೆ, ನೀವು ಬದಲಾಗಿ ನಿಯಮಿತ ಚಿಕಿತ್ಸಾಲಯದ ಆರೈಕೆಯನ್ನು ಮುಂದುವರಿಸಬಹುದು."},{"text":"ಯಾವುದೇ ಆಕ್ರಮಣಕಾರಿ ಕಾರ್ಯವಿಧಾನಗಳು ಇಲ್ಲಃ ಇದು ಡಿಜಿಟಲ್ ಮತ್ತು ಕೆಲಸದ ಹರಿವಿನ ನಾವೀನ್ಯತೆ ಅಧ್ಯಯನವಾಗಿದೆ; ಸಂಶೋಧನಾ ಘಟಕದಲ್ಲಿ ಯಾವುದೇ ಪ್ರಾಯೋಗಿಕ ಔಷಧಿಗಳು ಅಥವಾ ಆಕ್ರಮಣಕಾರಿ ಚಿಕಿತ್ಸೆಗಳು ಒಳಗೊಂಡಿಲ್ಲ."}]},{"heading":"ಭಾಗವಹಿಸುವಿಕೆ","paragraphs":[{"text":"ವೈಯಕ್ತಿಕ ಪ್ರಯೋಜನಃ ವೈಯಕ್ತಿಕ ಭಾಗವಹಿಸುವವರಿಗೆ ಯಾವುದೇ ನೇರ ಪ್ರಯೋಜನವಿಲ್ಲ. ಆದಾಗ್ಯೂ, ನಿಮ್ಮ ಸ್ಕ್ರೀನಿಂಗ್ ತಂತ್ರವನ್ನು ತಿಳಿಸಲು ಸಹಾಯ ಮಾಡುವ ಅಪಾಯದ ಮುನ್ಸೂಚನೆಯನ್ನು ನೀವು ಸ್ವೀಕರಿಸುತ್ತೀರಿ."},{"text":"ಸಮಾಜ ಪ್ರಯೋಜನಃ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆಯು ಸ್ತನ ಕ್ಯಾನ್ಸರ್ನ ಆರಂಭಿಕ ಪತ್ತೆ ಮತ್ತು ಭಾರತದಾದ್ಯಂತ ಮಹಿಳೆಯರಿಗೆ ಉತ್ತಮ ಸಂಪನ್ಮೂಲ ಹಂಚಿಕೆ ಸೇರಿದಂತೆ ವೈಜ್ಞಾನಿಕ ಪ್ರಯೋಜನಗಳಿಗೆ ಕೊಡುಗೆ ನೀಡುತ್ತದೆ."}]},{"heading":"ಈ ಅಧ್ಯಯನದಲ್ಲಿ ನನ್ನ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಗೌಪ್ಯವಾಗಿ ಇಡಲಾಗುತ್ತದೆಯೇ?","paragraphs":[{"text":"ಹೌದು. ಈ ಅಧ್ಯಯನದ ಸಮಯದಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾದ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಗೌಪ್ಯವಾಗಿಡಲಾಗುತ್ತದೆ. ಎಲ್ಲಾ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಅನ್ವಯವಾಗುವ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ನಿಯಮಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಅನಾಮಧೇಯಗೊಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ. ಅಧಿಕೃತ ಸಂಶೋಧನಾ ತಂಡದ ಸದಸ್ಯರಿಗೆ ಮಾತ್ರ ಡೇಟಾಕ್ಕೆ ಪ್ರವೇಶವಿದೆ, ಮತ್ತು ನಿಮ್ಮ ಸ್ಪಷ್ಟ ಒಪ್ಪಿಗೆಯಿಲ್ಲದೆ ಯಾವುದೇ ವೈಯಕ್ತಿಕವಾಗಿ ಗುರುತಿಸಬಹುದಾದ ಮಾಹಿತಿಯನ್ನು ಮೂರನೇ ವ್ಯಕ್ತಿಗಳೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ. ಅಧ್ಯಯನದ ಫಲಿತಾಂಶಗಳನ್ನು ಒಟ್ಟು ರೂಪದಲ್ಲಿ ಮಾತ್ರ ಪ್ರಸ್ತುತಪಡಿಸಲಾಗುತ್ತದೆ, ವೈಯಕ್ತಿಕ ಭಾಗವಹಿಸುವವರನ್ನು ಗುರುತಿಸಲಾಗುವುದಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು."},{"text":"ಒಟ್ಟು ದತ್ತಾಂಶದ ಸುಮಾರು 20% ರಷ್ಟು, ತಿರುವು ತರದ ಅನಾಮಧೇಯ ರೀತಿಯಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುವುದು, ಇದು AI ಅಲ್ಗಾರಿದಮ್ಗಳ ಮೌಲ್ಯಮಾಪನಕ್ಕಾಗಿ TANUH ನ ಬ್ಯಾಂಚ್ಮಾರ್ಕಿಂಗ್ ಮತ್ತು ಮುಕ್ತ ದತ್ತಾಂಶ ಉಪಕ್ರಮದ ಭಾಗವಾಗಿರುತ್ತದೆ. ಸಂಗ್ರಹಿಸಿದ ದತ್ತಾಂಶವನ್ನು ಭವಿಷ್ಯದ ಸಂಶೋಧನೆಯಲ್ಲಿ ಬಳಸಲಾಗುತ್ತದೆ, ಇದರಲ್ಲಿ ಇತರ ಅಡಿಪಾಯ ಮಾದರಿಗಳ ಅಭಿವೃದ್ಧಿ ಸೇರಿವೆ."}]},{"heading":"ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ ಎಂದರೇನು?","paragraphs":[{"text":"ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿರಾಕರಿಸಬಹುದು ಅಥವಾ ಪೆನಾಲ್ಟಿ ಅಥವಾ ಪ್ರಯೋಜನಗಳ ನಷ್ಟವಿಲ್ಲದೆ ಸಮೀಕ್ಷೆಯನ್ನು ನಿಲ್ಲಿಸಬಹುದು."}]},{"heading":"ಸಂಶೋಧನೆಯಿಂದ ಉಂಟಾದ ಗಾಯಗಳಿಗೆ ಪರಿಹಾರ ಮತ್ತು ವೈದ್ಯಕೀಯ ಆರೈಕೆ ಇದೆಯೇ?","paragraphs":[{"text":"ಪರಿಹಾರಃ ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಿದ್ದಕ್ಕಾಗಿ ನಿಮಗೆ ಹಣ ನೀಡಲಾಗುವುದಿಲ್ಲ. ಇದು ಕನಿಷ್ಠ/ಅಪಾಯವಿಲ್ಲದ ಅಧ್ಯಯನವಾದ್ದರಿಂದ ಯಾವುದೇ ಪರಿಹಾರವನ್ನು ನೀಡಲಾಗುವುದಿಲ್ಲ."},{"text":"ಗಾಯಃ ಇದು ಯಾವುದೇ ಆಕ್ರಮಣಕಾರಿ ಹಸ್ತಕ್ಷೇಪಗಳನ್ನು ಒಳಗೊಂಡಿರುವ ಸಮೀಕ್ಷೆ/ಕೃತಕ ಬುದ್ಧಿಮತ್ತೆ ಆಧಾರಿತ ಸ್ಕ್ರೀನಿಂಗ್ ಅಧ್ಯಯನವಾದ್ದರಿಂದ, ಗಾಯಕ್ಕೆ ಯಾವುದೇ ವೈದ್ಯಕೀಯ ಚಿಕಿತ್ಸೆ ಅಥವಾ ಪರಿಹಾರವನ್ನು ಯೋಜಿಸಲಾಗಿಲ್ಲ."},{"text":"ವೆಚ್ಚಗಳುಃ ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿಮಗೆ ಯಾವುದೇ ವೆಚ್ಚವಿಲ್ಲ."}]},{"heading":"ಸಂಶೋಧನೆಯ ಫಲಿತಾಂಶಗಳ ಬಗ್ಗೆ ಏನಾಗುತ್ತದೆ?","paragraphs":[{"text":"ಈ ಸಂಶೋಧನಾ ಅಧ್ಯಯನದ ಫಲಿತಾಂಶಗಳನ್ನು AI ಶಕ್ತಗೊಳಿಸಿದ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯ ಮುನ್ಸೂಚನೆ ಉಪಕರಣವನ್ನು ಅಭಿವೃದ್ಧಿಪಡಿಸಲು ಮತ್ತು ಮೌಲ್ಯೀಕರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ. ಸಂಶೋಧನೆಗಳನ್ನು ಸಹೋದ್ಯೋಗಿಗಳ ಪರಿಶೀಲಿಸಿದ ವೈಜ್ಞಾನಿಕ ನಿಯತಕಾಲಿಕಗಳಲ್ಲಿ ಪ್ರಕಟಿಸಬಹುದು, ಶೈಕ್ಷಣಿಕ ಸಮ್ಮೇಳನಗಳಲ್ಲಿ ಪ್ರಸ್ತುತಪಡಿಸಬಹುದು ಮತ್ತು ಭಾರತದಲ್ಲಿ ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಸ್ಕ್ರೀನಿಂಗ್ ಅಭ್ಯಾಸಗಳನ್ನು ಸುಧಾರಿಸಲು ಆರೋಗ್ಯ ಸಂಸ್ಥೆಗಳು ಮತ್ತು ನೀತಿ ನಿರ್ಮಾಪಕರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಬಹುದು. ಪ್ರಕಟವಾದ ಎಲ್ಲಾ ಫಲಿತಾಂಶಗಳು ವೈಯಕ್ತಿಕ ಗುರುತಿಸುವಿಕೆಯಿಲ್ಲದೆ ಒಟ್ಟು ರೂಪದಲ್ಲಿರುತ್ತವೆ."}]},{"heading":"ಸಂಶೋಧನೆಯನ್ನು ಯಾರು ಸಂಘಟಿಸುತ್ತಾರೆ ಮತ್ತು ಹಣಕಾಸು ಒದಗಿಸುತ್ತಾರೆ?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ಈ ಅಧ್ಯಯನವನ್ನು ಯಾರು ಪರಿಶೀಲಿಸಿದ್ದಾರೆ?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಾನು ಯಾರನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು?","paragraphs":[{"text":"ಸಂಪರ್ಕ ವಿವರಗಳುಃ ಡಾ. ಅಶ್ವಿನ್ ರಾಯಜ್ ಕುಮಾರ್, ಪ್ರಾಜೆಕ್ಟ್ ಮ್ಯಾನೇಜರ್"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ನೀವು ಅಧ್ಯಯನದ ಬಗ್ಗೆ ಸ್ವತಂತ್ರವಾಗಿರುವ ಯಾರೊಂದಿಗೂ ಮಾತನಾಡಲು ಬಯಸಿದರೆ, ನೀವು ಈ ಕೆಳಗಿನವರನ್ನು ಸಂಪರ್ಕಿಸಬಹುದುಃ"},{"text":"ಸಾಂಸ್ಥಿಕ ನೀತಿ ಸಮಿತಿ (ಐಇಸಿ)"},{"text":"ಹೆಸರುಃ ಡಾ. ಶ್ರೀ ವಿದ್ಯಾ ಜಗಡಿಶ್, ಐಇಸಿ ಕಾರ್ಯದರ್ಶಿ, ಟ್ಯಾನುಹ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಿದ್ದಕ್ಕಾಗಿ ಧನ್ಯವಾದಗಳು!"}]}],"checkboxLabel":"ನಾನು ಭಾಗವಹಿಸುವವರ ಮಾಹಿತಿ ಚೀಟ್ ಅನ್ನು ಓದಿದ್ದೇನೆ ಮತ್ತು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ಸ್ವಯಂಪ್ರೇರಣೆಯಿಂದ ಒಪ್ಪುತ್ತೇನೆ.","buttonText":"ಒಪ್ಪಿಕೊಳ್ಳು ಮತ್ತು ಮುಂದುವರಿಸು"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'ml','{"title":"പങ്കാളികളുടെ വിവര ഷീറ്റ്","headernames":{"studyTitle":"പഠന ശീർഷകം","sponsor":"സംഘാടകനും ധനസഹായവും","iecApproval":"ധാർമികതയുടെ അവലോകനം"},"header":{"studyTitle":"ഇന്ത്യയിലെ ജനസംഖ്യയ്ക്കായി സ്തനാർബുദം പ്രവചിക്കാനുള്ള AI പ്രാപ്തമായ ഉപകരണം വികസിപ്പിക്കുക","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ഈ പഠനത്തെക്കുറിച്ച്","paragraphs":[{"text":"ആരോഗ്യ പരിരക്ഷയ്ക്കായി ഇന്ത്യൻ ഐ. ഐ. പരിഹാരങ്ങൾ വികസിപ്പിക്കുന്നതിനുള്ള വിദ്യാഭ്യാസ മന്ത്രാലയത്തിന്റെ ധനസഹായമുള്ള പദ്ധതിയുടെ ഭാഗമാണ് ഈ പഠനം. ഇന്ത്യയിലെ സ്ത്രീകളുടെ പ്രയോജനത്തിനായി സ്തനാർബുദം പഠനം മുന്നോട്ട് കൊണ്ടുപോകുന്നതിനുള്ള ഈ ശ്രമത്തിന്റെ സുപ്രധാന ഭാഗമായതിന് നന്ദി. ഇന്ത്യയിലുടനീളം സ്ത്രീകളുടെ പ്രയോജനത്തിനായി ഐ. ഐ. നടത്തുക. ഇന്ത്യയിൽ ഐ. ഐ. പ്രവർത്തിക്കുക."}]},{"heading":"പഠനത്തിന്റെ ഉദ്ദേശ്യം എന്താണ്?","paragraphs":[{"text":"ഇന്ത്യയിലെ ജനസംഖ്യയ്ക്കായി സ്തനാർബുദം പ്രവചിക്കാനുള്ള AI പ്രാപ്തമായ ഉപകരണം വികസിപ്പിക്കുക"}]},{"heading":"എന്തിന് എന്നെ തെരഞ്ഞെടുത്തു?","paragraphs":[{"text":"നിങ്ങൾ മാംമോഗ്രാഫിക്ക് അല്ലെങ്കിൽ ഒരു പതിവ് മാംമോഗ്രാഫിക്ക് വിധേയനാകുന്നതിനാൽ AI പ്രാപ്തമാക്കിയ സ്റ്റെയിൻ കാൻസർ സ്ക്രീനിംഗ് ഉപകരണങ്ങളുടെ പഠനത്തിന് സംഭാവന നൽകാൻ നിങ്ങളെ തിരഞ്ഞെടുത്തു. ഏതാനും ചോദ്യാവലികളിലൂടെ സ്റ്റെയിൻ കാൻസർ സാധ്യത തിരിച്ചറിയാൻ സഹായിക്കുന്ന ഒരു AI പ്രാപ്തമാക്കിയ സ്റ്റെയിൻ കാൻസർ സ്ക്രീനിംഗ് ഉപകരണമാണ് ഞങ്ങൾ വികസിപ്പിക്കുന്നത്."}]},{"heading":"ഞാന് പങ്കെടുക്കേണ്ടതാണോ?","paragraphs":[{"text":"നിങ്ങളുടെ പങ്കാളിത്തം പൂർണമായും സ്വമേധയാ ആണ്. പഠനത്തില് പങ്കെടുക്കാന് നിങ്ങള് ക്ക് സാധിക്കാതെ വരും. നിങ്ങളുടെ സാധാരണ പ്രവര് ത്തനങ്ങള് തുടര് ന്നുപോകും."}]},{"heading":"പഠനത്തിന് റെ ഫലമെന്താണ്? പങ്കെടുക്കാൻ നിങ്ങൾ സമ്മതിച്ചാൽ താഴെ പറയുന്ന കാര്യങ്ങൾ സംഭവിക്കും.","paragraphs":[{"text":"സർവേഃ നിങ്ങളുടെ ജനസംഖ്യാശാസ്ത്രത്തെക്കുറിച്ചും ആരോഗ്യ ചരിത്രത്തെക്കുറിച്ചും ജീവിതശൈലിയെക്കുറിച്ചും കുടുംബത്തിലെ കാൻസർ രോഗത്തെക്കുറിച്ചും ഒരു തവണയോ ഒരു ചോദ്യാവലി പൂരിപ്പിക്കാൻ നിങ്ങളോട് ആവശ്യപ്പെടും."},{"text":"റിസ്ക് പ്രവചനംഃ സർവേയുടെ അവസാനം നിങ്ങൾക്ക് ഉടനടി സ്തനാർബുദം ഉണ്ടാകുന്നതിനെക്കുറിച്ച് പ്രവചനം നൽകും (നിങ്ങൾക്ക് സാധാരണമായതോ ഉയർന്നതോ ആയ അപകടസാധ്യത ഉണ്ടോ എന്ന് തിരിച്ചറിയുക)."},{"text":"മാർഗ്ഗനിർദ്ദേശംഃ അപകടസാധ്യതയുടെ അടിസ്ഥാനത്തിൽ നിങ്ങൾക്ക് മാർഗനിർദ്ദേശം ലഭിക്കും. ഉയർന്ന അപകടസാധ്യതയുണ്ടെന്ന് കണ്ടെത്തിയാൽ, നിങ്ങളെ മാംമോഗ്രഫിക്ക് റഫർ ചെയ്യാം. സാധാരണ / കുറഞ്ഞ അപകടസാധ്യതയുള്ളവരാണെങ്കിൽ, പതിവ് പരിശോധന പ്രോട്ടോക്കോളുകൾ തുടരാൻ നിങ്ങളോട് ആവശ്യപ്പെടും."},{"text":"ഡാറ്റ ഉപയോഗം: നിങ്ങളില് നിന്നും ആശുപത്രിയില് നിന്നും ശേഖരിച്ച ഡാറ്റ ഇന്ത്യയിലെ സ്ത്രീകളില് സ്തനാർബുദം വരാനുള്ള സാധ്യത മെച്ചപ്പെടുത്താന് കൃത്രിമ ബുദ്ധി (AI) മാതൃക പരിശീലിപ്പിക്കുന്നതിന് ഉപയോഗിക്കും."}]},{"heading":"ഞാന് പങ്കെടുക്കുകയാണെങ്കില് എന് റെ അവസ്ഥയെന്ത്?","paragraphs":[{"text":"വ്യക്തിഗതമായ അപകടസാധ്യതാ പ്രവചനങ്ങള് ഭാവിയില് ആരോഗ്യ നിരീക്ഷണത്തില് സാധ്യമായ സ്തനാർബുദ ലക്ഷണങ്ങള് ക്കും നിങ്ങളുടെ വ്യക്തിഗത അപകടസാധ്യതാ ഘടകങ്ങള് ക്കും കൂടുതൽ ബോധവാന്മാരാകാന് നിങ്ങളെ സഹായിക്കും."}]},{"heading":"ഞാനെന്ത് ചെയ്യണം?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"പങ്കെടുക്കുന്നതിലെ അപകടങ്ങള് എന്തൊക്കെയാണ്?","paragraphs":[{"text":"ഈ ഗവേഷണ പഠനത്തില് പങ്കെടുക്കുന്നതില് വലിയ അപകടങ്ങളൊന്നും ഉണ്ടാവില്ല."},{"text":"അപകടസാധ്യതയില്ല / മിനിമംഃ ഈ പഠനം \\"അപകടസാധ്യതയില്ല / മിനിമം\\" എന്ന് കണക്കാക്കപ്പെടുന്നു."},{"text":"സ്വകാര്യതഃ സ്വകാര്യതയെ സംബന്ധിച്ചിടത്തോളം അപൂർവമായ ഒരു അപകടസാധ്യതയുണ്ട്, പക്ഷേ ഇത് കുറയ്ക്കുന്നു, കാരണം വ്യക്തിപരമായി തിരിച്ചറിയാവുന്ന വിവരങ്ങൾ ഞങ്ങൾ ശേഖരിക്കുന്നില്ല, കൂടാതെ ഡാറ്റ അജ്ഞാതമായി പിടിച്ചെടുക്കുന്നു."},{"text":"സ്വമേധയാഃ ഈ ചോദ്യാവലി പൂർണമായും സ്വമേധയാ ആണ്; നിങ്ങൾക്ക് താല്പര്യമില്ലെങ്കിൽ, പകരം ക്ലിനിക്കിൽ പതിവ് പരിചരണം തേടാം."},{"text":"ആക്രമണാത്മക നടപടിക്രമങ്ങളില്ലഃ ഇത് ഡിജിറ്റൽ, വർക്ക്ഫ്ലോ നവീകരണ പഠനമാണ്; പരീക്ഷണാത്മക മരുന്നുകളോ ആക്രമണാത്മക ചികിത്സകളോ ഗവേഷണ ഘടകത്തിൽ ഉൾപ്പെട്ടിട്ടില്ല."}]},{"heading":"പങ്കെടുക്കുന്നതിൽനിന്ന് ലഭിക്കുന്ന നേട്ടങ്ങൾ എന്തൊക്കെയാണ്?","paragraphs":[{"text":"വ്യക്തിപരമായ പ്രയോജനംഃ വ്യക്തിഗത പങ്കാളികൾക്ക് നേരിട്ടുള്ള പ്രയോജനം ഉണ്ടാകില്ല. എന്നിരുന്നാലും, നിങ്ങളുടെ സ്ക്രീനിംഗ് തന്ത്രത്തെ അറിയിക്കുന്നതിന് സഹായിക്കുന്ന ഒരു റിസ്ക് പ്രവചനം നിങ്ങൾക്ക് ലഭിക്കും."},{"text":"സാമൂഹിക പ്രയോജനംഃ നിങ്ങളുടെ പങ്കാളിത്തം ശാസ്ത്രീയ പ്രയോജനങ്ങൾക്ക് സംഭാവന ചെയ്യും."}]},{"heading":"ഈ പഠനത്തില് പങ്കെടുക്കുന്നതില് എന്റെ പങ്കാളിത്തം രഹസ്യമായി സൂക്ഷിക്കപ്പെടുമോ?","paragraphs":[{"text":"അതെ. ഈ പഠനത്തിനിടെ ശേഖരിക്കുന്ന എല്ലാ വിവരങ്ങളും കർശനമായി രഹസ്യാത്മകമായി സൂക്ഷിക്കും. ബാധകമായ ഡാറ്റാ പരിരക്ഷണ നിയമങ്ങൾക്കനുസൃതമായി എല്ലാ സ്വകാര്യ ഡാറ്റയും അജ്ഞാതമാക്കുകയും സുരക്ഷിതമായി സൂക്ഷിക്കുകയും ചെയ്യും. അംഗീകൃത ഗവേഷണ സംഘത്തിലെ അംഗങ്ങൾക്ക് മാത്രമേ ഡാറ്റയിലേക്ക് പ്രവേശനം ലഭിക്കുകയുള്ളൂ, നിങ്ങളുടെ വ്യക്തമായ സമ്മതമില്ലാതെ വ്യക്തിപരമായി തിരിച്ചറിയാവുന്ന വിവരങ്ങളൊന്നും മൂന്നാം കക്ഷികളുമായി പങ്കിടില്ല. പഠന ഫലങ്ങൾ സംയോജിത രൂപത്തിൽ മാത്രമേ അവതരിപ്പിക്കാവൂ, അതിനാൽ വ്യക്തിഗത പങ്കാളികളെ തിരിച്ചറിയാൻ കഴിയില്ലെന്ന് ഉറപ്പാക്കുന്നു."},{"text":"അപ്രത്യക്ഷമായ അജ്ഞാത രീതിയില് ശേഖരിച്ച മൊത്തം ഡാറ്റയുടെ 20% ത്തിലേറെയും AI അല് ഗോരിതങ്ങളുടെ വിലയിരുത്തലിന് വേണ്ടി TANUH യുടെ ബെഞ്ച്മാര് ക്കിങ്, ഓപ്പൺ ഡാറ്റ സംരംഭത്തിന്റെ ഭാഗമാകും. ശേഖരിച്ച ഡാറ്റ ഭാവി ഗവേഷണത്തില് ഉപയോഗിക്കും."}]},{"heading":"സ്വമേധയാ പങ്കെടുക്കുക എന്നതു എന്താണ്?","paragraphs":[{"text":"നിങ്ങളുടെ പങ്കാളിത്തം പൂർണമായും സ്വമേധയാ ആണ്. നിങ്ങൾക്ക് ഏതു സമയത്തും പനാൽസിസിസിനും ആനുകൂല്യങ്ങൾക്കും നഷ്ടപ്പെടാതെ പങ്കെടുക്കാൻ വിസമ്മതിക്കാനോ അല്ലെങ്കിൽ സർവേ അവസാനിപ്പിക്കാനോ കഴിയും."}]},{"heading":"ഗവേഷണവുമായി ബന്ധപ്പെട്ട പരിക്കിന് എന്തെങ്കിലും നഷ്ടപരിഹാരവും വൈദ്യസഹായവും ഉണ്ടോ?","paragraphs":[{"text":"നഷ്ടപരിഹാരംഃ ഈ പഠനത്തില് പങ്കെടുത്താല് നിങ്ങള് ക്ക് പണം ലഭിക്കില്ല. ഇത് ഒരു മിനിമല് / റിസ്ക് രഹിത പഠനമാണെങ്കില് യാതൊരു നഷ്ടപരിഹാരവും വാഗ്ദാനം ചെയ്യപ്പെടുന്നില്ല."},{"text":"പരിക്കുകൾഃ ഇത് ഒരു സർവേ/AI അടിസ്ഥാനമാക്കിയുള്ള സ്ക്രീനിംഗ് പഠനമാണു്. അതിൽ ആക്രമണാത്മക ഇടപെടലുകളില്ല. പരിക്കുകൾക്ക് ചികിത്സയോ നഷ്ടപരിഹാരമോ നൽകാനാവില്ല."},{"text":"ചെലവുകൾഃ ഈ പഠനത്തില് പങ്കെടുക്കാന് നിങ്ങള് ക്ക് യാതൊരു ചെലവുമില്ല."}]},{"heading":"ഗവേഷണ പഠനത്തിന്റെ ഫലങ്ങള് ക്ക് എന്ത് സംഭവിക്കും?","paragraphs":[{"text":"ഈ ഗവേഷണ പഠനത്തിന്റെ ഫലങ്ങൾ ഒരു AI പ്രാപ്തമാക്കിയ ബ്രെസ്റ്റ് കാൻസർ റിസ്ക് പ്രവചന ഉപകരണത്തിന്റെ വികസനത്തിനും പരിശോധനയ്ക്കും ഉപയോഗിക്കും. കണ്ടെത്തലുകൾ സമപ്രായ ശാസ്ത്രീയ ജേണലുകളിൽ പ്രസിദ്ധീകരിക്കാനും അക്കാദമിക് സമ്മേളനങ്ങളിൽ അവതരിപ്പിക്കാനും ഇന്ത്യയിലെ ബ്രെസ്റ്റ് കാൻസർ സ്ക്രീനിംഗ് രീതികൾ മെച്ചപ്പെടുത്തുന്നതിനായി ആരോഗ്യ സംരക്ഷണ സ്ഥാപനങ്ങളുമായും നയരൂപകരുമായും പങ്കിടാനും കഴിയും. പ്രസിദ്ധീകരിച്ച എല്ലാ ഫലങ്ങളും വ്യക്തിഗത തിരിച്ചറിയൽ ഇല്ലാതെ സംയോജിത രൂപത്തിൽ ആയിരിക്കും."}]},{"heading":"ആരാണ് ഗവേഷണം സംഘടിപ്പിക്കുകയും ധനസഹായം നല് കുകയും ചെയ്യുന്നത്?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ആര് ഈ പഠനം അവലോകനം ചെയ്തു?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"കൂടുതൽ വിവരങ്ങള് ക്കായി ഞാന് ആര് ക്ക് ബന്ധപ്പെടാം?","paragraphs":[{"text":"ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾഃ ഡോ. അശ്വിന് റാജ്കുമാർ, പദ്ധതി മേധാവി"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"പഠനത്തില് നിന്ന് സ്വതന്ത്രമായ ഒരാളുമായി സംസാരിക്കണമെങ്കില് താഴെ പറയുന്നവയില് ബന്ധപ്പെടാംഃ"},{"text":"സ്ഥാപനപരമായ ധാർമിക സമിതി (ഐ. ഇ. സി.)"},{"text":"പേര്ഃ ഡോ. ശ്രീ വിദ്യ ജഗാദിഷ്, ഐ. ഇ. സി സെക്രട്ടറി, താനു"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"പഠനത്തില് പങ്കെടുത്തതിന് നന്ദി!"}]}],"checkboxLabel":"പങ്കെടുക്കുന്നവരുടെ വിവരപത്രിക വായിക്കുകയും മനസ്സിലാക്കുകയും ചെയ്ത ഞാന് ഈ പഠനത്തില് പങ്കെടുക്കാന് സ്വമേധയാ സമ്മതിക്കുന്നു.","buttonText":"സ്വീകരിക്കുക & തുടരുക"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'mr','{"title":"भागधारकांची माहिती पत्रक","headernames":{"studyTitle":"अभ्यास शीर्षक","sponsor":"आयोजक आणि निधी","iecApproval":"नैतिकता पुनरावलोकन"},"header":{"studyTitle":"भारतीय लोकसंख्येसाठी एआय सक्षम स्तनाचा कर्करोगाचा धोका अंदाज साधनाचा विकास","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"या अभ्यासाबद्दल","paragraphs":[{"text":"आरोग्यसेवेसाठी भारतीय एआय सोल्यूशन्स विकसित करण्यासाठी शिक्षण मंत्रालयाच्या निधीने आयोजित केलेल्या प्रकल्पाचा हा भाग आहे. भारतीय विज्ञान संस्थेद्वारे आयोजित केलेल्या टॅनुह फाउंडेशन ही एक सेक्शन 8 कंपनी आहे. स्तन कर्करोग संशोधनात या महत्त्वपूर्ण राष्ट्रीय उपक्रमाचे नेतृत्व करण्यास अभिमान आहे. आरोग्य परिणामांमध्ये सुधारणा करण्यासाठी लवकर, डेटा-आधारित शोधणे आवश्यक आहे हे ओळखून. भारतातील महिलांच्या फायद्यासाठी स्तन कर्करोग अभ्यास पुढे नेण्यासाठी या प्रयत्नाचा एक आवश्यक भाग असल्याबद्दल आम्ही आपल्या सहभागाचे कौतुक करतो आणि धन्यवाद."}]},{"heading":"अभ्यास करण्याचे उद्दिष्ट काय आहे?","paragraphs":[{"text":"भारतीय लोकसंख्येसाठी एआय सक्षम स्तनाचा कर्करोगाचा धोका अंदाज साधनाचा विकास"}]},{"heading":"मला का निवडले गेले?","paragraphs":[{"text":"तुम्हाला एआय सक्षम स्तनाचा कर्करोग तपासणी साधनांच्या अभ्यासासाठी पाठिंबा देण्यासाठी निवडण्यात आला आहे कारण तुम्हाला मॅमोग्राफीसाठी किंवा नियमित मॅमोग्राफीसाठी संदर्भित करण्यात आला आहे. आम्ही एआय सक्षम स्तनाचा कर्करोग तपासणी साधनाचा विकास करत आहोत जे काही प्रश्नावलीद्वारे स्तनाचा कर्करोगाचा धोका ओळखण्यास सक्षम करते."}]},{"heading":"मी सहभागी व्हायला हवे का?","paragraphs":[{"text":"तुम्ही या अभ्यासात सहभागी न होण्याचा निर्णय घेऊ शकता आणि तुमच्या सामान्य पद्धतीप्रमाणेच पुढे जाऊ शकता."}]},{"heading":"अभ्यासात काय घडेल तुम्ही सहभागी होण्यास सहमत असाल तर खालील गोष्टी घडतील?","paragraphs":[{"text":"सर्वेक्षण: तुम्हाला तुमच्या लोकसंख्या, आरोग्याच्या इतिहास, जीवनशैली आणि कर्करोगाच्या कौटुंबिक इतिहासाविषयी एकवेळचा प्रश्नावली (टॅब्लेट/डिजिटल डिव्हाइसवर) भरावा लागेल."},{"text":"जोखीम अंदाज: सर्वेक्षण संपल्यावर तुम्हाला स्तन कर्करोगाचा धोका त्वरित अंदाज येईल (तुम्हाला सामान्य किंवा अधिक धोका आहे का हे ओळखून)."},{"text":"मार्गदर्शनः जोखीम पातळीवर आधारित तुम्हाला मार्गदर्शन मिळेल. जर तुम्हाला अधिक धोका असल्याचे आढळले तर तुम्हाला मॅमोग्राफीसाठी संदर्भित केले जाऊ शकते. जर तुम्हाला सामान्य/कमी धोका असेल तर नियमित तपासणी प्रोटोकॉल सुरू ठेवण्यास सांगितले जाईल."},{"text":"डेटा वापर: तुमच्याकडून आणि रुग्णालयातून गोळा केलेला डेटा भारतीय महिलांमध्ये स्तनाचा कर्करोग होण्याचा धोका अधिक चांगल्या प्रकारे अंदाज लावण्यासाठी कृत्रिम बुद्धिमत्तेच्या (AI) मॉडेलचे प्रशिक्षण घेण्यासाठी वापरला जाईल."}]},{"heading":"मी भाग घेतला तर काय होईल?","paragraphs":[{"text":"वैयक्तिकृत धोका अंदाज तुम्हाला स्तन कर्करोगाच्या संभाव्य लक्षणांची अधिक जाणीव ठेवण्यास आणि भविष्यातील आरोग्याची देखरेख करण्यासाठी तुमच्या वैयक्तिक जोखीम घटकांविषयी अधिक जागरूक होण्यास मदत करेल."}]},{"heading":"मी काय करावे?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"यात सहभागी होण्याचे कोणते धोके आहेत?","paragraphs":[{"text":"या संशोधन अभ्यासात सहभागी होणे हा कोणताही मोठा धोका नाही."},{"text":"नाही/ किमान धोकाः हा अभ्यास \\"कोणत्याही/ किमान जोखीम\\" मानला जातो."},{"text":"गोपनीयता: गोपनीयता संबंधित एक दुर्मिळ धोका आहे, परंतु हे कमी केले जाते कारण आम्ही वैयक्तिकरित्या ओळखण्यायोग्य माहिती गोळा करत नाही आणि डेटा अनामिकरित्या गोळा केला जातो."},{"text":"स्वेच्छेने: हा प्रश्नावली पूर्णपणे स्वेच्छेने आहे; जर तुम्हाला स्वारस्य नसेल तर तुम्ही नियमित क्लिनिकमध्ये उपचार घेऊ शकता."},{"text":"कोणतीही आक्रमक प्रक्रिया नाहीः हा एक डिजिटल आणि वर्कफ्लो नावीन्यपूर्ण अभ्यास आहे; संशोधन घटकामध्ये कोणतेही प्रयोगात्मक औषधे किंवा आक्रमक उपचारांचा समावेश नाही."}]},{"heading":"सहभाग घेताना काय फायदे मिळू शकतात?","paragraphs":[{"text":"वैयक्तिक फायदा: वैयक्तिक सहभागींसाठी कोणताही थेट फायदा होण्याची शक्यता नाही. तथापि, तुम्हाला जोखीम अंदाज मिळतो जो तुमच्या तपासणी धोरणाला सूचित करण्यास मदत करू शकतो."},{"text":"सामाजिक लाभ: आपल्या सहभागाने वैज्ञानिक लाभ मिळतील, ज्यात स्तन कर्करोगाचा लवकर निदान वाढेल आणि भारतातील महिलांसाठी अधिक चांगले संसाधने वाटप केले जातील."}]},{"heading":"या अभ्यासामध्ये माझे सहभाग गुप्त ठेवला जाईल का?","paragraphs":[{"text":"या अभ्यासात गोळा केलेली सर्व माहिती पूर्णपणे गोपनीय राहील. सर्व वैयक्तिक डेटा लागू डेटा संरक्षण नियमांच्या अनुषंगाने अनामिक केले जातील आणि सुरक्षितपणे संग्रहित केले जातील. केवळ अधिकृत संशोधन कार्यसंघाच्या सदस्यांनाच डेटामध्ये प्रवेश मिळेल आणि आपल्या स्पष्ट संमतीशिवाय कोणतीही वैयक्तिकरित्या ओळखण्यायोग्य माहिती तृतीय पक्षाशी सामायिक केली जाणार नाही. अभ्यासातील निकाल केवळ एकत्रित स्वरूपात सादर केले जातील, जेणेकरून वैयक्तिक सहभागींची ओळख होऊ शकत नाही."},{"text":"एकूण डेटापैकी सुमारे 20% अपरिवर्तनीयपणे अनामिक पद्धतीने गोळा केलेले हे AI अल्गोरिदमच्या मूल्यांकनासाठी TANUH च्या बेंचमार्किंग आणि ओपन डेटा पुढाकारात समाविष्ट केले जाईल. गोळा केलेले डेटा भविष्यातील संशोधनात वापरले जातील, ज्यात इतर पायाभूत मॉडेल विकसित करणे समाविष्ट आहे."}]},{"heading":"स्वेच्छेने सहभाग म्हणजे काय?","paragraphs":[{"text":"तुम्ही कोणत्याही वेळी न भरता किंवा लाभ गमावल्याशिवाय सर्वेक्षण करण्यास नकार देऊ शकता किंवा थांबवू शकता."}]},{"heading":"संशोधन-संबंधित जखमांसाठी कोणतेही नुकसान भरपाई आणि वैद्यकीय उपचार आहेत का?","paragraphs":[{"text":"भरपाई: या अभ्यासात सहभागी झाल्याबद्दल तुम्हाला पैसे दिले जात नाहीत. या अभ्यासात कमीतकमी/जोखीम नसलेल्या अभ्यासात सहभागी झाल्यामुळे कोणतीही भरपाई देण्यात येत नाही."},{"text":"जखम: हा एक सर्वेक्षण/एआय आधारित स्क्रीनिंग अभ्यास असून त्यात कोणत्याही प्रकारची आक्रमक हस्तक्षेप नाही, त्यामुळे जखमांसाठी वैद्यकीय उपचार किंवा भरपाईची योजना नाही."},{"text":"खर्च: या अभ्यासात सहभागी होण्यासाठी तुम्हाला कोणतेही शुल्क नाही."}]},{"heading":"या संशोधनाच्या निकालांचे काय होईल?","paragraphs":[{"text":"या संशोधन अभ्यासाचे परिणाम एआय सक्षम स्तनाचा कर्करोग अंदाज साधनाचा विकास आणि सत्यापन करण्यासाठी वापरले जातील. निष्कर्ष पीअर-रीव्ह्यू केलेल्या वैज्ञानिक जर्नल्समध्ये प्रकाशित केले जाऊ शकतात, शैक्षणिक परिषदांमध्ये सादर केले जाऊ शकतात आणि आरोग्य संस्था आणि धोरण निर्मात्यांसह शेअर केले जाऊ शकतात."}]},{"heading":"या संशोधनाचे आयोजन आणि वित्तपुरवठा कोण करत आहे?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"या अभ्यासाचा आढावा कोणी घेतला?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"अधिक माहितीसाठी मी कोणाशी संपर्क साधू शकतो?","paragraphs":[{"text":"संपर्क तपशील: डॉ. अश्विन राजकुमार, प्रकल्प व्यवस्थापक"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"जर तुम्हाला अभ्यासातून स्वतंत्र व्यक्तीशी बोलायचे असेल तर तुम्ही खालील व्यक्तीशी संपर्क साधू शकताः"},{"text":"संस्थागत नैतिकता समिती (आयईसी)"},{"text":"नाव: डॉ. श्री विद्या जगदीश, आयईसीचे सचिव, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"अभ्यासात सहभागी झाल्याबद्दल धन्यवाद!"}]}],"checkboxLabel":"मी सहभागी माहिती पत्रक वाचले आणि समजले आहे आणि स्वेच्छेने या अभ्यासात सहभागी होण्यास सहमत आहे.","buttonText":"स्वीकार आणि पुढे जा"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'or','{"title":"ଅଂଶଗ୍ରହଣକାରୀ ସୂଚନା ପତ୍ର","headernames":{"studyTitle":"ଅଧ୍ୟୟନ ନାମ","sponsor":"ସଂଗଠନ ଓ ପାଣ୍ଠି","iecApproval":"ଆଦର୍ଶର ସମୀକ୍ଷା"},"header":{"studyTitle":"ଭାରତୀୟ ଜନସଂଖ୍ୟା ପାଇଁ ଏକ AI ସକ୍ଷମ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣର ବିକାଶ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ଏହି ଅଧ୍ୟୟନ ବିଷୟରେ","paragraphs":[{"text":"ଏହି ଅଧ୍ୟୟନ ଶିକ୍ଷା ମନ୍ତ୍ରଣାଳୟ ଦ୍ୱାରା ଅର୍ଥପ୍ରାପ୍ତ ସ୍ୱାସ୍ଥ୍ୟସେବା ପାଇଁ ଭାରତୀୟ ଏଆଇ ସମାଧାନ ବିକଶିତ କରିବା ପ୍ରକଳ୍ପର ଅଂଶବିଶେଷ । ଭାରତୀୟ ବିଜ୍ଞାନ ପ୍ରତିଷ୍ଠାନ ଦ୍ୱାରା ଆୟୋଜିତ ଏକ ସେକ୍ସନ 8 କମ୍ପାନୀ ହେଉଛି TANUH ଫାଉଣ୍ଡେସନ୍ ଗର୍ବର ସହିତ ସ୍ତନ କର୍କଟ ଗବେଷଣା କ୍ଷେତ୍ରରେ ଏହି ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ଜାତୀୟ ପଦକ୍ଷେପକୁ ନେତୃତ୍ୱ ପ୍ରଦାନ କରୁଛି । ଏହା ସ୍ୱୀକାର କରୁଛି ଯେ ସ୍ୱାସ୍ଥ୍ୟ ଫଳାଫଳକୁ ଉନ୍ନତ କରିବା ପାଇଁ ଆଗୁଆ, ତଥ୍ୟ ଆଧାରିତ ଚିହ୍ନଟ ଅତ୍ୟନ୍ତ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ । ଆମେ ଆପଣଙ୍କ ଅଂଶଗ୍ରହଣକୁ ଗଭୀର ଭାବରେ ପ୍ରଶଂସା କରୁଛୁ ଏବଂ ସାରା ଭାରତରେ ମହିଳାମାନଙ୍କ ଲାଭ ପାଇଁ ସ୍ତନ କର୍କଟ ଅଧ୍ୟୟନକୁ ଆଗକୁ ବଢ଼ାଇବା ପାଇଁ ଏହି ପ୍ରୟାସର ଏକ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ଅଂଶ ହୋଇଥିବାରୁ ଧନ୍ୟବାଦ ଜଣାଉଛୁ । ଭାରତରେ ଏଆଇ ନିର୍ମାଣ କରନ୍ତୁ ଏବଂ ଭାରତ ପାଇଁ ଏଆଇ କାର୍ଯ୍ୟ କରନ୍ତୁ ।"}]},{"heading":"ଅଧ୍ୟୟନ କରିବାର ଉଦ୍ଦେଶ୍ୟ କ''ଣ?","paragraphs":[{"text":"ଭାରତୀୟ ଜନସଂଖ୍ୟା ପାଇଁ ଏକ AI ସକ୍ଷମ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣର ବିକାଶ"}]},{"heading":"ମୋତେ କାହିଁକି ବାଛିଲେ?","paragraphs":[{"text":"ଆପଣମାନେ ଏଆଇ ଦ୍ୱାରା ସକ୍ଷମ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଉପକରଣର ଅଧ୍ୟୟନ ପାଇଁ ଯୋଗଦାନ କରିବା ପାଇଁ ଚୟନ ହୋଇଛନ୍ତି କାରଣ ଆପଣଙ୍କୁ ମାମୋଗ୍ରାଫି କିମ୍ବା ରutine ମାମୋଗ୍ରାଫି ପାଇଁ ପଠାଯାଇଛି । ଆମେ ଏକ ଏଆଇ ଦ୍ୱାରା ସକ୍ଷମ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଉପକରଣ ବିକଶିତ କରୁଛୁ ଯାହା କିଛି ପ୍ରଶ୍ନପତ୍ର ମାଧ୍ୟମରେ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ଚିହ୍ନଟ କରିବାକୁ ସକ୍ଷମ କରେ ।"}]},{"heading":"ମୁଁ ଭାଗ ନେବି କି?","paragraphs":[{"text":"ଆପଣ ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନ ନେଇ ନିଜ ଅଭ୍ୟାସ ଜାରି ରଖିପାରିବେ।"}]},{"heading":"ଅଧ୍ୟୟନ ବେଳେ କ''ଣ ଘଟିବ?","paragraphs":[{"text":"ସର୍ଭେ: ଆପଣଙ୍କୁ ଏକ ଥର ପାଇଁ ଜନସଂଖ୍ୟା, ସ୍ୱାସ୍ଥ୍ୟଗତ ଇତିହାସ, ଜୀବନଶୈଳୀ ଏବଂ କ୍ୟାନସର ସମ୍ବନ୍ଧୀୟ ଏକ ପ୍ରଶ୍ନପତ୍ର (ଟ୍ୟାବଲେଟ୍/ଡିଜିଟାଲ ଉପକରଣରେ) ପୂରଣ କରିବାକୁ କୁହାଯିବ ।"},{"text":"ବିପଦ ପୂର୍ବାନୁମାନଃ ସର୍ଭେ ଶେଷ ହେବା ପରେ ଆପଣଙ୍କୁ ତୁରନ୍ତ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ (ଯଦି ଆପଣ ସୁସ୍ଥ ଅଛନ୍ତି କିମ୍ବା ଅଧିକ ବିପଦ ଅଛନ୍ତି ତାହା ଚିହ୍ନଟ କରିବା) ଦିଆଯିବ ।"},{"text":"ମାର୍ଗଦର୍ଶନଃ ବିପଦ ସ୍ତର ଉପରେ ଆଧାର କରି ଆପଣଙ୍କୁ ମାର୍ଗଦର୍ଶନ ମିଳିବ। ଯଦି ଆପଣ ଅଧିକ ବିପଦଗ୍ରସ୍ତ ବୋଲି ଜଣାପଡ଼େ, ତେବେ ଆପଣଙ୍କୁ ମାମ୍ମୋଗ୍ରାଫି ପାଇଁ ପଠାଯାଇପାରେ। ଯଦି ଆପଣ ସାମାନ୍ୟ / କମ୍ ବିପଦଗ୍ରସ୍ତ ଅଛନ୍ତି, ତେବେ ଆପଣଙ୍କୁ ନିୟମିତ ଯାଞ୍ଚ ପ୍ରୋଟୋକଲ୍ ଜାରି ରଖିବାକୁ କୁହାଯିବ।"},{"text":"ଡାଟା ବ୍ୟବହାର: ଆପଣଙ୍କ ଠାରୁ ଏବଂ ଡାକ୍ତରଖାନାରୁ ସଂଗ୍ରହ କରାଯାଇଥିବା ତଥ୍ୟକୁ ଭାରତୀୟ ମହିଳାଙ୍କ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ବିଷୟରେ ଭଲ ଭାବେ ପୂର୍ବାନୁମାନ କରିବା ପାଇଁ ଏକ କୃତ୍ରିମ ବୁଦ୍ଧିମତା (ଏଆଇ) ମଡେଲକୁ ପ୍ରଶିକ୍ଷଣ ଦେବା ପାଇଁ ବ୍ୟବହାର କରାଯିବ ।"}]},{"heading":"ମୁଁ ଭାଗ ନେଲେ ମୋ ସହିତ କଣ ହେବ?","paragraphs":[{"text":"ବ୍ୟକ୍ତିଗତ ବିପଦ ପୂର୍ବାନୁମାନ ଆପଣଙ୍କୁ ସ୍ତନ କର୍କଟ ଲକ୍ଷଣ ଏବଂ ଭବିଷ୍ୟତରେ ସ୍ୱାସ୍ଥ୍ୟ ନିରୀକ୍ଷଣ ପାଇଁ ଆପଣଙ୍କ ବ୍ୟକ୍ତିଗତ ବିପଦଜନକ କାରକ ବିଷୟରେ ଅଧିକ ସଚେତନ ହେବାକୁ ସାହାଯ୍ୟ କରିବ।"}]},{"heading":"ମୁଁ କ''ଣ କରିବି?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ଭାଗ ନେବା ଦ୍ବାରା କେଉଁ ବିପଦ ରହିଛି?","paragraphs":[{"text":"ଏହି ଗବେଷଣା ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବା ଦ୍ୱାରା କୌଣସି ବଡ଼ ବିପଦ ନାହିଁ ।"},{"text":"କୌଣସି ବିପଦ ନାହିଁ/ ସର୍ବନିମ୍ନ ବିପଦ ନାହିଁ: ଏହି ଅଧ୍ୟୟନକୁ \\"ନିମ୍ନ ବିପଦ ନାହିଁ/ ସର୍ବନିମ୍ନ ବିପଦ\\" ବୋଲି କୁହାଯାଏ ।"},{"text":"ଗୋପନୀୟତା: ଗୋପନୀୟତା ସମ୍ବନ୍ଧରେ ଏକ ବିରଳ ବିପଦ ଅଛି, କିନ୍ତୁ ଏହା ହ୍ରାସ ପାଇଥାଏ କାରଣ ଆମେ ବ୍ୟକ୍ତିଗତ ଭାବରେ ଚିହ୍ନଟଯୋଗ୍ୟ ସୂଚନା ସଂଗ୍ରହ କରୁନାହୁଁ, ଏବଂ ତଥ୍ୟ ଅଜ୍ଞାତ ଭାବରେ ସଂଗ୍ରହ କରାଯାଏ ।"},{"text":"ସ୍ୱେଚ୍ଛାକୃତ: ଏହି ପ୍ରଶ୍ନପତ୍ର ସମ୍ପୂର୍ଣ୍ଣ ସ୍ୱେଚ୍ଛାକୃତ ଅଟେ; ଯଦି ଆପଣ ଆଗ୍ରହୀ ନୁହଁନ୍ତି, ତେବେ ଆପଣ ନିୟମିତ କ୍ଲିନିକ ଚିକିତ୍ସା ଅନୁସରଣ କରିପାରିବେ ।"},{"text":"କୌଣସି ଆକ୍ରୋଶକାରୀ ପ୍ରକ୍ରିୟା ନାହିଁ: ଏହା ଏକ ଡିଜିଟାଲ ଏବଂ କାର୍ଯ୍ୟ ପ୍ରବାହ ନବସୃଜନ ଅଧ୍ୟୟନ; ଗବେଷଣା ଉପାଦାନରେ କୌଣସି ପରୀକ୍ଷଣୀୟ ଔଷଧ କିମ୍ବା ଆକ୍ରୋଶକାରୀ ଚିକିତ୍ସା ସାମିଲ ନାହିଁ ।"}]},{"heading":"ଭାଗ ନେବା ଦ୍ବାରା କ''ଣ ଲାଭ ମିଳିପାରେ?","paragraphs":[{"text":"ବ୍ୟକ୍ତିଗତ ଲାଭ: ବ୍ୟକ୍ତିଗତ ଅଂଶଗ୍ରହଣକାରୀଙ୍କ ପାଇଁ କୌଣସି ପ୍ରତ୍ୟକ୍ଷ ଲାଭ ନାହିଁ । ତଥାପି, ଆପଣ ଏକ ବିପଦ ପୂର୍ବାନୁମାନ ପାଇବେ ଯାହା ଆପଣଙ୍କ ସ୍କ୍ରିନିଂ ରଣନୀତିକୁ ସୂଚିତ କରିବାରେ ସାହାଯ୍ୟ କରିପାରେ ।"},{"text":"ସାମାଜିକ ଲାଭ: ଆପଣଙ୍କ ଅଂଶଗ୍ରହଣ ଦ୍ୱାରା ବୃତ୍ତିଗତ ଲାଭ, ଯେପରିକି ସ୍ତନ କର୍କଟ ରୋଗର ପ୍ରାଥମିକ ଚିହ୍ନଟ ଏବଂ ସାରା ଭାରତରେ ମହିଳାଙ୍କ ପାଇଁ ଉତ୍ତମ ସମ୍ବଳ ଆବଣ୍ଟନ ବୃଦ୍ଧି ପାଇବ ।"}]},{"heading":"ଏହି ଅଧ୍ୟୟନରେ ମୋର ଅଂଶଗ୍ରହଣ ଗୋପନୀୟ ରଖାଯିବ କି?","paragraphs":[{"text":"ହଁ. ଏହି ଅଧ୍ୟୟନ ସମୟରେ ସଂଗ୍ରହ କରାଯାଇଥିବା ସମସ୍ତ ସୂଚନାକୁ ସଂପୂର୍ଣ୍ଣ ଗୋପନୀୟ ରଖାଯିବ । ସମସ୍ତ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟ ପ୍ରଯୁଜ୍ୟ ତଥ୍ୟ ସୁରକ୍ଷା ନିୟମାବଳୀ ଅନୁଯାୟୀ ଗୋପନୀୟ ଭାବରେ ଗୋପନ ରଖାଯିବ । କେବଳ ଅଧିକୃତ ଅନୁସନ୍ଧାନକାରୀ ଦଳର ସଦସ୍ୟମାନେ ତଥ୍ୟକୁ ପ୍ରବେଶ କରିପାରିବେ ଏବଂ ଆପଣଙ୍କ ସ୍ପଷ୍ଟ ସମ୍ମତି ବିନା କୌଣସି ବ୍ୟକ୍ତିଗତ ସୂଚନା ତୃତୀୟ ପକ୍ଷ ସହିତ ଅଂଶୀଦାର କରାଯିବ ନାହିଁ । ଅଧ୍ୟୟନ ଫଳାଫଳ କେବଳ ସମୁଦାୟ ଭାବରେ ଉପସ୍ଥାପନ କରାଯିବ, ଯାହାଦ୍ୱାରା ବ୍ୟକ୍ତିଗତ ଅଂଶଗ୍ରହଣକାରୀଙ୍କୁ ଚିହ୍ନଟ କରାଯାଇପାରିବ ନାହିଁ ।"},{"text":"ଏହି ତଥ୍ୟର ପ୍ରାୟ ୨୦% ଅଚଳ ଭାବେ ଅଜ୍ଞାତସୂତ୍ରରେ ସଂଗ୍ରହ କରାଯିବ ଏବଂ ଏହା ଏଆଇ ଆଲଗୋରିଦମଗୁଡ଼ିକର ମୂଲ୍ୟାଙ୍କନ ଲାଗି TANUHର ବେଞ୍ଚମାର୍କିଂ ଏବଂ ଓପନ ଡାଟା ପଦକ୍ଷେପ ଅନ୍ତର୍ଗତ ରହିବ। ସଂଗ୍ରହ କରାଯାଇଥିବା ତଥ୍ୟକୁ ଭବିଷ୍ୟତରେ ଗବେଷଣା ପାଇଁ ବ୍ୟବହାର କରାଯିବ, ଯେଉଁଥିରେ ଅନ୍ୟ ଫାଉଣ୍ଡେସନ ମଡେଲର ବିକାଶ ମଧ୍ୟ ସାମିଲ ହେବ।"}]},{"heading":"ସ୍ୱେଚ୍ଛାକୃତ ଅଂଶଗ୍ରହଣ କ''ଣ?","paragraphs":[{"text":"ଆପଣମାନେ ଏହି ସର୍ଭେରେ ଭାଗ ନେବା ପାଇଁ ସମ୍ପୂର୍ଣ୍ଣ ଭାବେ ସ୍ୱେଚ୍ଛାକୃତ ଏବଂ ଆପଣମାନେ ବିନା କୌଣସି ଦଣ୍ଡରେ କିମ୍ବା କୌଣସି ଲାଭ ହାନି ବିନା ଯେକୌଣସି ସମୟରେ ଏଥିରେ ଭାଗ ନେବାକୁ ମନା କରିପାରିବେ କିମ୍ବା ଏହାକୁ ବନ୍ଦ କରିପାରିବେ ।"}]},{"heading":"ଗବେଷଣା ସମ୍ବନ୍ଧୀୟ ଆଘାତ ପାଇଁ କୌଣସି କ୍ଷତିପୂରଣ ଏବଂ ଚିକିତ୍ସା ବ୍ୟବସ୍ଥା ରହିଛି କି?","paragraphs":[{"text":"କ୍ଷତିପୂରଣ: ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନେବା ପାଇଁ ଆପଣଙ୍କୁ କୌଣସି ଦେୟ ଦିଆଯିବ ନାହିଁ । କୌଣସି କ୍ଷତିପୂରଣ ପ୍ରଦାନ କରାଯିବ ନାହିଁ କାରଣ ଏହା ଏକ ସର୍ବନିମ୍ନ/ନିଃସଙ୍କଟ ଅଧ୍ୟୟନ ।"},{"text":"ଆହତ: ଏହା ଏକ ସର୍ଭେ/AI ଆଧାରିତ ସ୍କ୍ରିନିଂ ଅଧ୍ୟୟନ, ଯେଉଁଥିରେ କୌଣସି ଆକ୍ରୋଶକାରୀ ହସ୍ତକ୍ଷେପ ନାହିଁ, ତେଣୁ କୌଣସି ଚିକିତ୍ସା କିମ୍ବା ଆଘାତ ପାଇଁ କ୍ଷତିପୂରଣ ଯୋଜନା କରାଯାଇନାହିଁ ।"},{"text":"ବ୍ୟୟ: ଏହି ଅଧ୍ୟୟନରେ ଭାଗ ନେବା ପାଇଁ ଆପଣଙ୍କୁ କୌଣସି ବ୍ୟୟ ଦେବାକୁ ପଡ଼ିବ ନାହିଁ।"}]},{"heading":"ଗବେଷଣାର ପରିଣାମ କ''ଣ ହେବ?","paragraphs":[{"text":"ଏହି ଗବେଷଣା ଅଧ୍ୟୟନର ଫଳାଫଳକୁ ଏକ ଏଆଇ ସମର୍ଥିତ ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ପୂର୍ବାନୁମାନ ଉପକରଣ ବିକଶିତ ଏବଂ ବୈଧ କରିବା ପାଇଁ ବ୍ୟବହାର କରାଯିବ । ଫଳାଫଳକୁ ସମୀକ୍ଷା କରାଯାଇଥିବା ବୈଜ୍ଞାନିକ ପତ୍ରିକାରେ ପ୍ରକାଶ କରାଯାଇପାରିବ, ଏକାଡେମିକ ସମ୍ମିଳନୀରେ ଉପସ୍ଥାପିତ କରାଯାଇପାରିବ ଏବଂ ଭାରତରେ ସ୍ତନ କର୍କଟ ସ୍କ୍ରିନିଂ ଅଭ୍ୟାସକୁ ଉନ୍ନତ କରିବା ପାଇଁ ସ୍ୱାସ୍ଥ୍ୟସେବା ସଂସ୍ଥା ଏବଂ ନୀତି ନିର୍ଦ୍ଧାରକମାନଙ୍କ ସହିତ ଅଂଶୀଦାର କରାଯାଇପାରିବ । ପ୍ରକାଶିତ ସମସ୍ତ ଫଳାଫଳ ଏକ ସମୂହ ସ୍ୱରୂପରେ ହେବ ।"}]},{"heading":"ଗବେଷଣାକୁ କିଏ ଆୟୋଜନ କରୁଛି ଏବଂ କିଏ ଏହାକୁ ଅର୍ଥ ପ୍ରଦାନ କରୁଛି?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"କିଏ ଏହି ଅଧ୍ୟୟନକୁ ସମୀକ୍ଷା କରିଛି?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ଅଧିକ ସୂଚନା ପାଇଁ ମୁଁ କାହାକୁ ଯୋଗାଯୋଗ କରିପାରିବି?","paragraphs":[{"text":"ଯୋଗାଯୋଗ ବିବରଣୀ: ଡଃ ଅଶ୍ୱିନ ରାଜକୁମାର, ପ୍ରକଳ୍ପ ପରିଚାଳକ"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ଯଦି ଆପଣ ଏହି ଅଧ୍ୟୟନରୁ କୌଣସି ସ୍ୱାଧୀନ ବ୍ୟକ୍ତିଙ୍କ ସହିତ କଥା ହେବାକୁ ଚାହୁଁଛନ୍ତି, ତେବେ ଆପଣ ନିମ୍ନଲିଖିତ ବ୍ୟକ୍ତିଙ୍କ ସହିତ ଯୋଗାଯୋଗ କରିପାରିବେଃ"},{"text":"ସଂସ୍ଥାଗତ ନୈତିକତା ସମିତି (ଆଇଇସି)"},{"text":"ନାମ: ଡଃ ଶ୍ରୀ ବିଦ୍ୟା ଜଗଦୀଶ, ଆଇଇସି ସଚିବ, ତନୁ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ଅଧ୍ୟୟନ ପାଇଁ ଧନ୍ୟବାଦ!"}]}],"checkboxLabel":"ମୁଁ ଅଂଶଗ୍ରହଣକାରୀ ସୂଚନା ପତ୍ରକୁ ପଢ଼ିଛି ଏବଂ ବୁଝିଛି ଏବଂ ସ୍ୱେଚ୍ଛାକୃତ ଭାବେ ଏହି ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ରାଜି ହୋଇଛି ।","buttonText":"ଗ୍ରହଣ କର ଏବଂ ଆଗକୁ ବଢ଼"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'pa','{"title":"ਭਾਗੀਦਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਸ਼ੀਟ","headernames":{"studyTitle":"ਅਧਿਐਨ ਦਾ ਸਿਰਲੇਖ","sponsor":"ਸੰਗਠਕ ਅਤੇ ਫੰਡਿੰਗ","iecApproval":"ਨੈਤਿਕਤਾ ਸਮੀਖਿਆ"},"header":{"studyTitle":"ਭਾਰਤੀ ਆਬਾਦੀ ਲਈ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਟੂਲ ਦਾ ਵਿਕਾਸ","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ਇਸ ਅਧਿਐਨ ਬਾਰੇ","paragraphs":[{"text":"ਇਹ ਅਧਿਐਨ ਸਿਹਤ ਸੰਭਾਲ ਲਈ ਭਾਰਤੀ ਏਆਈ ਹੱਲ਼ ਵਿਕਸਿਤ ਕਰਨ ਲਈ ਸਿੱਖਿਆ ਮੰਤਰਾਲੇ ਦੁਆਰਾ ਫੰਡ ਕੀਤੇ ਪ੍ਰੋਜੈਕਟ ਦਾ ਹਿੱਸਾ ਹੈ। ਟੈਨੂਹ ਫਾਊਂਡੇਸ਼ਨ ਇੱਕ ਸੈਕਸ਼ਨ 8 ਕੰਪਨੀ ਹੈ ਜਿਸਦੀ ਮੇਜ਼ਬਾਨੀ ਇੰਡੀਅਨ ਇੰਸਟੀਚਿਊਟ ਆਫ ਸਾਇੰਸ ਕਰਦੀ ਹੈ। ਇਹ ਮਾਣ ਨਾਲ ਮੰਨਦੀ ਹੈ ਕਿ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਖੋਜ ਵਿੱਚ ਇਸ ਨਾਜ਼ੁਕ ਰਾਸ਼ਟਰੀ ਪਹਿਲਕਦਮੀ ਦੀ ਅਗਵਾਈ ਕਰਨ ਲਈ, ਛੇਤੀ, ਡਾਟਾ-ਅਧਾਰਿਤ ਖੋਜ ਸਿਹਤ ਨਤੀਜਿਆਂ ਵਿੱਚ ਸੁਧਾਰ ਲਈ ਜ਼ਰੂਰੀ ਹੈ। ਅਸੀਂ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਦੀ ਬਹੁਤ ਪ੍ਰਸ਼ੰਸਾ ਕਰਦੇ ਹਾਂ ਅਤੇ ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਔਰਤਾਂ ਦੇ ਲਾਭ ਲਈ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਅਧਿਐਨ ਨੂੰ ਅੱਗੇ ਵਧਾਉਣ ਦੇ ਇਸ ਯਤਨ ਦਾ ਇੱਕ ਜ਼ਰੂਰੀ ਹਿੱਸਾ ਹੋਣ ਲਈ ਤੁਹਾਡਾ ਧੰਨਵਾਦ ਕਰਦੇ ਹਾਂ। ਭਾਰਤ ਵਿੱਚ ਏਆਈ ਬਣਾਓ ਅਤੇ ਭਾਰਤ ਲਈ ਏਆਈ ਨੂੰ ਕੰਮ ਕਰੋ।"}]},{"heading":"ਅਧਿਐਨ ਦਾ ਮਕਸਦ ਕੀ ਹੈ?","paragraphs":[{"text":"ਭਾਰਤੀ ਆਬਾਦੀ ਲਈ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਟੂਲ ਦਾ ਵਿਕਾਸ"}]},{"heading":"ਮੈਨੂੰ ਕਿਉਂ ਚੁਣਿਆ ਗਿਆ ਹੈ?","paragraphs":[{"text":"ਤੁਹਾਨੂੰ ਏਆਈ ਸਮਰੱਥ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੇ ਸਾਧਨਾਂ ਦੇ ਅਧਿਐਨ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਉਣ ਲਈ ਚੁਣਿਆ ਗਿਆ ਹੈ ਕਿਉਂਕਿ ਤੁਹਾਨੂੰ ਮੈਮੋਗ੍ਰਾਫੀ ਜਾਂ ਰੁਟੀਨ ਮੈਮੋਗ੍ਰਾਫੀ ਲਈ ਭੇਜਿਆ ਗਿਆ ਹੈ। ਅਸੀਂ ਇੱਕ ਏਆਈ ਸਮਰੱਥ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੇ ਸਾਧਨ ਦਾ ਵਿਕਾਸ ਕਰ ਰਹੇ ਹਾਂ ਜੋ ਕੁਝ ਪ੍ਰਸ਼ਨਾਵਲੀ ਦੁਆਰਾ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਪਛਾਣ ਕਰਨ ਦੇ ਯੋਗ ਬਣਾਉਂਦਾ ਹੈ।"}]},{"heading":"ਕੀ ਮੈਨੂੰ ਹਿੱਸਾ ਲੈਣਾ ਚਾਹੀਦਾ ਹੈ?","paragraphs":[{"text":"ਤੁਸੀਂ ਆਪਣੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਵਲੰਟੀਅਰਤਾ ਨਾਲ ਇਸ ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਨਹੀਂ ਲੈਣਾ ਅਤੇ ਆਪਣੀ ਆਮ ਰੁਟੀਨ ਨਾਲ ਜਾਰੀ ਰਹਿਣਾ ਚੁਣ ਸਕਦੇ ਹੋ।"}]},{"heading":"ਅਧਿਐਨ ਵਿਚ ਕੀ ਹੋਵੇਗਾ ਜੇ ਤੁਸੀਂ ਹਿੱਸਾ ਲੈਣ ਲਈ ਸਹਿਮਤ ਹੋ, ਤਾਂ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਸਰਵੇਖਣਃ ਤੁਹਾਨੂੰ ਇੱਕ ਵਾਰ ਇੱਕ ਪ੍ਰਸ਼ਨਨਾਮਾ (ਟੈਬਲੇਟ/ਡਿਜੀਟਲ ਉਪਕਰਣ ''ਤੇ) ਭਰਨ ਲਈ ਕਿਹਾ ਜਾਵੇਗਾ ਜਿਸ ਵਿੱਚ ਤੁਹਾਡੀ ਜਨਸੰਖਿਆ, ਸਿਹਤ ਇਤਿਹਾਸ, ਜੀਵਨ ਸ਼ੈਲੀ ਅਤੇ ਪਰਿਵਾਰਕ ਕੈਂਸਰ ਦੇ ਇਤਿਹਾਸ ਬਾਰੇ ਦੱਸਿਆ ਗਿਆ ਹੈ।"},{"text":"ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀਃ ਸਰਵੇਖਣ ਦੇ ਅੰਤ ''ਤੇ, ਤੁਹਾਨੂੰ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਤੁਰੰਤ ਭਵਿੱਖਬਾਣੀ ਦਿੱਤੀ ਜਾਵੇਗੀ (ਜੋ ਇਹ ਪਤਾ ਲਗਾਉਂਦਾ ਹੈ ਕਿ ਕੀ ਤੁਹਾਡਾ ਜੋਖਮ ਆਮ ਜਾਂ ਵਧੇਰੇ ਹੈ)."},{"text":"ਮਾਰਗਦਰਸ਼ਨਃ ਜੋਖਮ ਦੇ ਪੱਧਰ ਦੇ ਆਧਾਰ ਤੇ, ਤੁਹਾਨੂੰ ਮਾਰਗਦਰਸ਼ਨ ਮਿਲੇਗਾ. ਜੇ ਤੁਹਾਨੂੰ ਵਧੇਰੇ ਜੋਖਮ ਪਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਤੁਹਾਨੂੰ ਮੈਮੋਗ੍ਰਾਫੀ ਲਈ ਭੇਜਿਆ ਜਾ ਸਕਦਾ ਹੈ. ਜੇ ਤੁਸੀਂ ਆਮ / ਘੱਟ ਜੋਖਮ ਵਿੱਚ ਹੋ, ਤਾਂ ਤੁਹਾਨੂੰ ਨਿਯਮਤ ਜਾਂਚ ਪ੍ਰੋਟੋਕੋਲ ਜਾਰੀ ਰੱਖਣ ਲਈ ਕਿਹਾ ਜਾਵੇਗਾ."},{"text":"ਡਾਟਾ ਉਪਯੋਗਤਾ: ਤੁਹਾਡੇ ਅਤੇ ਹਸਪਤਾਲ ਤੋਂ ਇਕੱਠਾ ਕੀਤੇ ਗਏ ਡਾਟਾ ਦੀ ਵਰਤੋਂ ਭਾਰਤੀ ਔਰਤਾਂ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਬਿਹਤਰ ਭਵਿੱਖਬਾਣੀ ਕਰਨ ਲਈ ਇੱਕ ਆਰਟੀਫੀਸ਼ੀਅਲ ਇੰਟੈਲੀਜੈਂਸ (ਏਆਈ) ਮਾਡਲ ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਕੀਤੀ ਜਾਵੇਗੀ।"}]},{"heading":"ਜੇ ਮੈਂ ਹਿੱਸਾ ਲੈਂਦਾ ਹਾਂ ਤਾਂ ਮੇਰੇ ਨਾਲ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਵਿਅਕਤੀਗਤ ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀ ਤੁਹਾਨੂੰ ਭਵਿੱਖ ਵਿੱਚ ਸਿਹਤ ਨਿਗਰਾਨੀ ਲਈ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਸੰਭਾਵਿਤ ਲੱਛਣਾਂ ਅਤੇ ਤੁਹਾਡੇ ਵਿਅਕਤੀਗਤ ਜੋਖਮ ਕਾਰਕਾਂ ਬਾਰੇ ਵਧੇਰੇ ਜਾਣੂ ਹੋਣ ਵਿੱਚ ਸਹਾਇਤਾ ਕਰੇਗੀ."}]},{"heading":"ਮੈਨੂੰ ਕੀ ਕਰਨਾ ਹੈ?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ਭਾਗ ਲੈਣ ਦੇ ਕੀ ਖ਼ਤਰੇ ਹਨ?","paragraphs":[{"text":"ਇਸ ਖੋਜ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਵਿੱਚ ਕੋਈ ਵੱਡਾ ਜੋਖਮ ਨਹੀਂ ਹੈ।"},{"text":"ਕੋਈ/ ਘੱਟੋ ਘੱਟ ਜੋਖਮ ਨਹੀਂਃ ਇਹ ਅਧਿਐਨ \\"ਕੋਈ/ ਘੱਟੋ ਘੱਟ ਜੋਖਮ\\" ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ।"},{"text":"ਪਰਦੇਦਾਰੀਃ ਪਰਦੇਦਾਰੀ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਇੱਕ ਬਹੁਤ ਹੀ ਘੱਟ ਜੋਖਮ ਹੈ, ਪਰ ਇਹ ਘੱਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਕਿਉਂਕਿ ਅਸੀਂ ਨਿੱਜੀ ਤੌਰ ''ਤੇ ਪਛਾਣਨ ਯੋਗ ਜਾਣਕਾਰੀ ਇਕੱਠੀ ਨਹੀਂ ਕਰਦੇ, ਅਤੇ ਡੇਟਾ ਗੁਮਨਾਮ ਰੂਪ ਵਿੱਚ ਪ੍ਰਾਪਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ."},{"text":"ਸਵੈਇੱਛੁਕ: ਇਹ ਪ੍ਰਸ਼ਨਨਾਮਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਵੈਇੱਛੁਕ ਹੈ; ਜੇਕਰ ਤੁਸੀਂ ਦਿਲਚਸਪੀ ਨਹੀਂ ਰੱਖਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਇਸ ਦੀ ਬਜਾਏ ਰੁਟੀਨ ਕਲਿਨੀਕ ਦੇਖਭਾਲ ਦੀ ਪਾਲਣਾ ਕਰ ਸਕਦੇ ਹੋ।"},{"text":"ਕੋਈ ਹਮਲਾਵਰ ਪ੍ਰਕਿਰਿਆਵਾਂ ਨਹੀਂਃ ਇਹ ਇੱਕ ਡਿਜੀਟਲ ਅਤੇ ਵਰਕਫਲੋ ਇਨੋਵੇਸ਼ਨ ਅਧਿਐਨ ਹੈ; ਖੋਜ ਭਾਗ ਵਿੱਚ ਕੋਈ ਪ੍ਰਯੋਗਾਤਮਕ ਦਵਾਈਆਂ ਜਾਂ ਹਮਲਾਵਰ ਥੈਰੇਪੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹਨ।"}]},{"heading":"ਹਿੱਸਾ ਲੈਣ ਦੇ ਕੀ ਲਾਭ ਹੋ ਸਕਦੇ ਹਨ?","paragraphs":[{"text":"ਨਿੱਜੀ ਲਾਭਃ ਵਿਅਕਤੀਗਤ ਭਾਗੀਦਾਰਾਂ ਲਈ ਸਿੱਧਾ ਲਾਭ ਨਹੀਂ ਹੋਵੇਗਾ। ਹਾਲਾਂਕਿ, ਤੁਹਾਨੂੰ ਇੱਕ ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀ ਮਿਲੇਗੀ ਜੋ ਤੁਹਾਡੀ ਸਕ੍ਰੀਨਿੰਗ ਰਣਨੀਤੀ ਨੂੰ ਸੂਚਿਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦੀ ਹੈ।"},{"text":"ਸਮਾਜਿਕ ਲਾਭਃ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਵਿਗਿਆਨਕ ਲਾਭਾਂ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਏਗੀ, ਜਿਸ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਛੇਤੀ ਖੋਜ ਵਿੱਚ ਸੁਧਾਰ ਅਤੇ ਭਾਰਤ ਭਰ ਵਿੱਚ ਔਰਤਾਂ ਲਈ ਬਿਹਤਰ ਸਰੋਤ ਨਿਰਧਾਰਨ ਸ਼ਾਮਲ ਹੈ।"}]},{"heading":"ਕੀ ਇਸ ਅਧਿਐਨ ਵਿਚ ਮੇਰੀ ਭਾਗੀਦਾਰੀ ਗੁਪਤ ਰੱਖੀ ਜਾਵੇਗੀ?","paragraphs":[{"text":"ਹਾਂ. ਇਸ ਅਧਿਐਨ ਦੌਰਾਨ ਇਕੱਠੀ ਕੀਤੀ ਗਈ ਸਾਰੀ ਜਾਣਕਾਰੀ ਸਖਤੀ ਨਾਲ ਗੁਪਤ ਰੱਖੀ ਜਾਵੇਗੀ. ਸਾਰੇ ਨਿੱਜੀ ਡੇਟਾ ਲਾਗੂ ਡੇਟਾ ਸੁਰੱਖਿਆ ਨਿਯਮਾਂ ਦੇ ਅਨੁਸਾਰ ਅਗਿਆਤ ਕੀਤੇ ਜਾਣਗੇ ਅਤੇ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਸਟੋਰ ਕੀਤੇ ਜਾਣਗੇ. ਸਿਰਫ ਅਧਿਕਾਰਤ ਖੋਜ ਟੀਮ ਦੇ ਮੈਂਬਰਾਂ ਨੂੰ ਡੇਟਾ ਤੱਕ ਪਹੁੰਚ ਹੋਵੇਗੀ, ਅਤੇ ਤੁਹਾਡੀ ਸਪੱਸ਼ਟ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਨਿੱਜੀ ਤੌਰ ''ਤੇ ਪਛਾਣਨ ਯੋਗ ਜਾਣਕਾਰੀ ਤੀਜੀ ਧਿਰ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਵੇਗੀ. ਅਧਿਐਨ ਦੇ ਨਤੀਜੇ ਸਿਰਫ ਸਮੁੱਚੇ ਰੂਪ ਵਿੱਚ ਪੇਸ਼ ਕੀਤੇ ਜਾਣਗੇ, ਇਹ ਸੁਨਿਸ਼ਚਿਤ ਕਰਦੇ ਹੋਏ ਕਿ ਵਿਅਕਤੀਗਤ ਭਾਗੀਦਾਰਾਂ ਦੀ ਪਛਾਣ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ."},{"text":"ਕੁੱਲ ਡਾਟਾ ਦਾ ਲਗਭਗ 20%, ਇੱਕ ਅਟੱਲ ਅਗਿਆਤ ਢੰਗ ਨਾਲ ਇਕੱਠਾ ਕੀਤਾ ਜਾਵੇਗਾ, AI ਐਲਗੋਰਿਦਮ ਦੇ ਮੁਲਾਂਕਣ ਲਈ TANUH ਦੇ ਬੈਂਚਮਾਰਕਿੰਗ ਅਤੇ ਓਪਨ ਡਾਟਾ ਪਹਿਲ ਦਾ ਹਿੱਸਾ ਹੋਵੇਗਾ। ਇਕੱਠਾ ਕੀਤਾ ਡਾਟਾ ਭਵਿੱਖ ਵਿੱਚ ਖੋਜ ਵਿੱਚ ਵਰਤਿਆ ਜਾਵੇਗਾ, ਜਿਸ ਵਿੱਚ ਹੋਰ ਫਾਊਂਡੇਸ਼ਨ ਮਾਡਲਾਂ ਦੇ ਵਿਕਾਸ ਵੀ ਸ਼ਾਮਲ ਹੈ।"}]},{"heading":"ਸਵੈਇੱਛੁਕ ਭਾਗੀਦਾਰੀ ਕੀ ਹੈ?","paragraphs":[{"text":"ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਪੂਰੀ ਤਰ੍ਹਾਂ ਸਵੈਇੱਛੁਕ ਹੈ। ਤੁਸੀਂ ਬਿਨਾਂ ਕਿਸੇ ਜੁਰਮਾਨੇ ਜਾਂ ਲਾਭਾਂ ਦੇ ਨੁਕਸਾਨ ਦੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸਰਵੇਖਣ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਤੋਂ ਇਨਕਾਰ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਇਸ ਨੂੰ ਰੋਕ ਸਕਦੇ ਹੋ।"}]},{"heading":"ਕੀ ਖੋਜ ਨਾਲ ਜੁੜੇ ਜ਼ਖਮਾਂ ਲਈ ਕੋਈ ਮੁਆਵਜ਼ਾ ਅਤੇ ਡਾਕਟਰੀ ਦੇਖਭਾਲ ਹੈ?","paragraphs":[{"text":"ਮੁਆਵਜ਼ਾਃ ਤੁਹਾਨੂੰ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਭੁਗਤਾਨ ਨਹੀਂ ਕੀਤਾ ਜਾਵੇਗਾ। ਕੋਈ ਮੁਆਵਜ਼ਾ ਨਹੀਂ ਦਿੱਤਾ ਜਾਂਦਾ ਕਿਉਂਕਿ ਇਹ ਇੱਕ ਘੱਟੋ ਘੱਟ/ਕੋਈ ਜੋਖਮ-ਮੁਕਤ ਅਧਿਐਨ ਹੈ।"},{"text":"ਜ਼ਖਮਃ ਕਿਉਂਕਿ ਇਹ ਇੱਕ ਸਰਵੇਖਣ/ਏਆਈ ਅਧਾਰਤ ਸਕ੍ਰੀਨਿੰਗ ਅਧਿਐਨ ਹੈ ਜਿਸ ਵਿੱਚ ਕੋਈ ਹਮਲਾਵਰ ਦਖਲਅੰਦਾਜ਼ੀ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ, ਜ਼ਖਮ ਲਈ ਕੋਈ ਡਾਕਟਰੀ ਇਲਾਜ ਜਾਂ ਮੁਆਵਜ਼ਾ ਦੀ ਯੋਜਨਾ ਨਹੀਂ ਹੈ।"},{"text":"ਖਰਚੇਃ ਇਸ ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਤੁਹਾਡੇ ਲਈ ਕੋਈ ਖਰਚਾ ਨਹੀਂ ਹੈ।"}]},{"heading":"ਖੋਜ ਅਧਿਐਨ ਦੇ ਨਤੀਜਿਆਂ ਦਾ ਕੀ ਹੋਵੇਗਾ?","paragraphs":[{"text":"ਇਸ ਖੋਜ ਅਧਿਐਨ ਦੇ ਨਤੀਜਿਆਂ ਦੀ ਵਰਤੋਂ ਏਆਈ ਸਮਰੱਥ ਬ੍ਰੈਸਟ ਕੈਂਸਰ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਕਰਨ ਵਾਲੇ ਸਾਧਨ ਨੂੰ ਵਿਕਸਤ ਕਰਨ ਅਤੇ ਪ੍ਰਮਾਣਿਤ ਕਰਨ ਲਈ ਕੀਤੀ ਜਾਵੇਗੀ। ਨਤੀਜੇ ਪੀਅਰ-ਰੀਵਿਊ ਕੀਤੇ ਵਿਗਿਆਨਕ ਰਸਾਲਿਆਂ ਵਿੱਚ ਪ੍ਰਕਾਸ਼ਤ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ, ਅਕਾਦਮਿਕ ਕਾਨਫਰੰਸਾਂ ਵਿੱਚ ਪੇਸ਼ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ, ਅਤੇ ਭਾਰਤ ਵਿੱਚ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੀ ਜਾਂਚ ਦੀਆਂ ਪ੍ਰਥਾਵਾਂ ਵਿੱਚ ਸੁਧਾਰ ਲਈ ਸਿਹਤ ਸੰਭਾਲ ਸੰਸਥਾਵਾਂ ਅਤੇ ਨੀਤੀ ਨਿਰਮਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੇ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ। ਸਾਰੇ ਪ੍ਰਕਾਸ਼ਤ ਨਤੀਜੇ ਵਿਅਕਤੀਗਤ ਪਛਾਣ ਦੇ ਬਿਨਾਂ ਸਮੁੱਚੇ ਰੂਪ ਵਿੱਚ ਹੋਣਗੇ।"}]},{"heading":"ਖੋਜ ਦਾ ਪ੍ਰਬੰਧਨ ਅਤੇ ਵਿੱਤ ਕੌਣ ਕਰ ਰਿਹਾ ਹੈ?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ਇਸ ਅਧਿਐਨ ਦੀ ਸਮੀਖਿਆ ਕਿਸਨੇ ਕੀਤੀ ਹੈ?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ਮੈਂ ਹੋਰ ਜਾਣਕਾਰੀ ਲਈ ਕਿਸ ਨਾਲ ਸੰਪਰਕ ਕਰ ਸਕਦਾ ਹਾਂ?","paragraphs":[{"text":"ਸੰਪਰਕ ਵੇਰਵੇਃ ਡਾ. ਅਸ਼ਵਿਨ ਰਾਜਕੁਮਾਰ, ਪ੍ਰੋਜੈਕਟ ਮੈਨੇਜਰ"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"ਜੇਕਰ ਤੁਸੀਂ ਅਧਿਐਨ ਤੋਂ ਸੁਤੰਤਰ ਕਿਸੇ ਨਾਲ ਗੱਲ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਹੇਠ ਲਿਖੇ ਨੰਬਰ ''ਤੇ ਸੰਪਰਕ ਕਰ ਸਕਦੇ ਹੋਃ"},{"text":"ਸੰਸਥਾਗਤ ਨੈਤਿਕਤਾ ਕਮੇਟੀ (ਆਈਈਸੀ)"},{"text":"ਨਾਮਃ ਡਾ. ਸ਼੍ਰੀ ਵਿਦਿਆ ਜਗਾਡੀਸ਼, ਆਈਈਸੀ, ਟੈਨੂਹ ਦੇ ਸਕੱਤਰ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ਅਧਿਐਨ ਵਿਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਤੁਹਾਡਾ ਧੰਨਵਾਦ!"}]}],"checkboxLabel":"ਮੈਂ ਭਾਗੀਦਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਸ਼ੀਟ ਪੜ੍ਹੀ ਅਤੇ ਸਮਝੀ ਹੈ ਅਤੇ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਹਿੱਸਾ ਲੈਣ ਲਈ ਸਵੈਇੱਛਤ ਤੌਰ ''ਤੇ ਸਹਿਮਤ ਹਾਂ।","buttonText":"ਸਵੀਕਾਰ ਕਰੋ ਅਤੇ ਜਾਰੀ ਰੱਖੋ"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'ta','{"title":"பங்கேற்பாளர் தகவல் தாள்","headernames":{"studyTitle":"ஆய்வு தலைப்பு","sponsor":"அமைப்பாளர் மற்றும் நிதி","iecApproval":"நெறிமுறைகள்"},"header":{"studyTitle":"இந்திய மக்களுக்கான மார்பக புற்றுநோய் அபாயத்தை கணிக்க AI இயக்கப்பட்ட கருவியை உருவாக்குதல்","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"இந்த ஆய்வு பற்றி","paragraphs":[{"text":"இந்த ஆய்வு சுகாதாரத்துறைக்கான இந்திய AI தீர்வுகளை உருவாக்குவதற்கான கல்வி அமைச்சின் நிதியுதவியுடன் மேற்கொள்ளப்படும் திட்டத்தின் ஒரு பகுதியாகும். இந்திய அறிவியல் நிறுவனத்தால் நடத்தப்படும் TANUH அறக்கட்டளை ஒரு பிரிவு 8 நிறுவனமாகும். மார்பக புற்றுநோய் ஆராய்ச்சியில் இந்த முக்கியமான தேசிய முயற்சியை முன்னெடுத்து வருவதில் பெருமிதம் கொள்கிறது. சுகாதார முடிவுகளை மேம்படுத்துவதற்கு ஆரம்பகால, தரவு அடிப்படையிலான கண்டறிதல் மிக முக்கியமானது என்பதை அங்கீகரிக்கிறது. உங்கள் பங்கேற்பை நாங்கள் மிகவும் பாராட்டுகிறோம், இந்தியா முழுவதும் பெண்களின் நலனுக்காக மார்பக புற்றுநோய் ஆய்வுகளை மேம்படுத்துவதற்கான இந்த முயற்சியின் ஒரு முக்கிய பகுதியாக இருப்பதற்கு நன்றி. இந்தியாவில் AI ஐ உருவாக்குங்கள் மற்றும் AI ஐ இந்தியாவுக்கு வேலை செய்யுங்கள்."}]},{"heading":"ஆய்வின் நோக்கம் என்ன?","paragraphs":[{"text":"இந்திய மக்களுக்கான மார்பக புற்றுநோய் அபாயத்தை கணிக்க AI இயக்கப்பட்ட கருவியை உருவாக்குதல்"}]},{"heading":"ஏன் என்னைத் தேர்ந்தெடுத்தார்கள்?","paragraphs":[{"text":"நீங்கள் மார்பக புற்றுநோய் பரிசோதனை கருவிகள் ஆய்வு செய்ய தேர்ந்தெடுக்கப்பட்டீர்கள், ஏனெனில் நீங்கள் மார்பக புற்றுநோய் பரிசோதனை அல்லது வழக்கமான மார்பக புற்றுநோய் பரிசோதனைக்கு பரிந்துரைக்கப்பட்டீர்கள். சில கேள்வித்தாள்களால் மார்பக புற்றுநோய் அபாயத்தை அடையாளம் காணக்கூடிய ஒரு AI-யை இயக்கிய மார்பக புற்றுநோய் பரிசோதனை கருவியை நாங்கள் உருவாக்கி வருகிறோம்."}]},{"heading":"நான் பங்கேற்க வேண்டுமா?","paragraphs":[{"text":"நீங்கள் முழுமையாக தன்னார்வ ரீதியாகப் பங்கேற்கலாம். நீங்கள் ஆய்வில் பங்கேற்காமல், வழக்கமான வழக்கமான வழக்கத்தை தொடரலாம்."}]},{"heading":"நீங்கள் கலந்து கொள்ள ஒப்புக்கொண்டால், பின்வருவன ஏற்படும்.","paragraphs":[{"text":"ஆய்வுஃ உங்கள் மக்கள்தொகை, உடல்நலம் வரலாறு, வாழ்க்கை முறை மற்றும் குடும்ப வரலாறு ஆகியவற்றைப் பற்றிய ஒரு முறை கேள்வித்தாளை (தொகுப்பு / டிஜிட்டல் சாதனத்தில்) நிரப்ப நீங்கள் கேட்கப்படுவீர்கள்."},{"text":"ஆபத்து கணிப்புஃ ஆய்வு முடிவில், உங்களுக்கு உடனடி மார்பக புற்றுநோய் ஆபத்து கணிப்பு வழங்கப்படும் (நீங்கள் சாதாரணமான அல்லது அதிக ஆபத்தில் இருக்கிறீர்களா என்பதை அடையாளம் காணும்)."},{"text":"வழிகாட்டுதல்ஃ ஆபத்து அளவை அடிப்படையாகக் கொண்டு, உங்களுக்கு வழிகாட்டுதல் வழங்கப்படும். நீங்கள் அதிக ஆபத்தில் இருப்பதாகக் கண்டறியப்பட்டால், நீங்கள் மாம்மோகிராபிக்கு அனுப்பப்படலாம். நீங்கள் சாதாரணமான / குறைந்த ஆபத்தில் இருந்தால், வழக்கமான சோதனை நெறிமுறைகளைத் தொடர வேண்டும்."},{"text":"தரவு பயன்பாடுஃ உங்களிடமிருந்தும் மருத்துவமனையிடமிருந்தும் சேகரிக்கப்பட்ட தரவு, இந்திய பெண்களில் மார்பக புற்றுநோய் அபாயத்தை சிறப்பாக கணிப்பதற்காக செயற்கை நுண்ணறிவு (AI) மாதிரியை பயிற்சி செய்யப் பயன்படுத்தப்படும்."}]},{"heading":"நான் பங்கேற்றால் என்ன நடக்கும்?","paragraphs":[{"text":"தனிப்பட்ட அபாய கணிப்பு உங்களுக்கு மார்பக புற்றுநோய் அறிகுறிகள் மற்றும் எதிர்கால சுகாதார கண்காணிப்புக்கான உங்கள் தனிப்பட்ட ஆபத்து காரணிகளை நன்கு அறிய உதவும்."}]},{"heading":"நான் என்ன செய்ய வேண்டும்?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"பங்கேற்பு என்ன ஆபத்துகளை ஏற்படுத்துகிறது?","paragraphs":[{"text":"இந்த ஆராய்ச்சி ஆய்வில் பங்கேற்பதில் எந்த பெரிய ஆபத்தும் இல்லை."},{"text":"இல்லை/ குறைந்தபட்ச ஆபத்துஃ இந்த ஆய்வு \\"இல்லை/ குறைந்தபட்ச ஆபத்து\\" என்று கருதப்படுகிறது."},{"text":"தனியுரிமைஃ தனியுரிமை தொடர்பாக அரிதான ஆபத்து உள்ளது, ஆனால் இது குறைக்கப்படுகிறது, ஏனெனில் நாங்கள் தனிப்பட்ட முறையில் அடையாளம் காணக்கூடிய தகவல்களை சேகரிக்கவில்லை, மேலும் தரவு அநாமதேயமாகப் பிடிக்கப்படுகிறது."},{"text":"தன்னார்வ: வினாத்தாள் முற்றிலும் தன்னார்வமானது; நீங்கள் ஆர்வம் காட்டவில்லை என்றால், அதற்கு பதிலாக வழக்கமான மருத்துவமனை பராமரிப்பை மேற்கொள்ளலாம்."},{"text":"எந்த ஆக்கிரமிப்பு நடைமுறைகளும் இல்லைஃ இது ஒரு டிஜிட்டல் மற்றும் பணிப்பாய்வு கண்டுபிடிப்பு ஆய்வு; ஆராய்ச்சி கூறுகளில் பரிசோதனை மருந்துகள் அல்லது ஆக்கிரமிப்பு சிகிச்சைகள் எதுவும் ஈடுபடவில்லை."}]},{"heading":"பங்கேற்பதில் என்ன நன்மைகள் உள்ளன?","paragraphs":[{"text":"தனிப்பட்ட நன்மைஃ தனிப்பட்ட பங்கேற்பாளர்களுக்கு நேரடி நன்மை இல்லை. இருப்பினும், உங்கள் புலனாய்வு மூலோபாயத்தை விளக்க உதவும் ஒரு ஆபத்து கணிப்பு உங்களுக்கு வழங்கப்படும்."},{"text":"சமூக நன்மைஃ உங்கள் பங்கேற்பு, மார்பக புற்றுநோயை ஆரம்பகாலமாக கண்டறிதல் மற்றும் இந்தியா முழுவதும் பெண்களுக்கு சிறந்த வள ஒதுக்கீடு உள்ளிட்ட அறிவியல் நன்மைகளுக்கு பங்களிக்கும்."}]},{"heading":"இந்த ஆய்வில் நான் பங்கேற்பது இரகசியமாகவே இருக்கப் போகிறதா?","paragraphs":[{"text":"ஆம். இந்த ஆய்வின் போது சேகரிக்கப்பட்ட அனைத்து தகவல்களும் கண்டிப்பாக ரகசியமாக வைக்கப்படும். அனைத்து தனிப்பட்ட தரவுகளும் பொருந்தக்கூடிய தரவு பாதுகாப்பு ஒழுங்குமுறைகளின்படி அநாமதேயப்படுத்தப்பட்டு பாதுகாப்பாக சேமிக்கப்படும். அங்கீகரிக்கப்பட்ட ஆராய்ச்சி குழு உறுப்பினர்கள் மட்டுமே தரவுகளை அணுக முடியும், மேலும் உங்கள் வெளிப்படையான ஒப்புதல் இல்லாமல் தனிப்பட்ட முறையில் அடையாளம் காணக்கூடிய எந்த தகவலும் மூன்றாம் தரப்பினருடன் பகிரப்படாது. ஆய்வின் முடிவுகள் ஒட்டுமொத்த வடிவத்தில் மட்டுமே வழங்கப்படும், தனிப்பட்ட பங்கேற்பாளர்களை அடையாளம் காண முடியாது என்பதை உறுதிசெய்கிறது."},{"text":"மொத்த தரவுகளில் சுமார் 20% ஐ, மாற்றமுடியாத அநாமதேய முறையில் சேகரிக்கப்படும், இது AI வழிமுறைகளை மதிப்பீடு செய்வதற்கான TANUH இன் ஒப்பீட்டு மதிப்பீடு மற்றும் திறந்த தரவு முன்முயற்சியின் ஒரு பகுதியாக இருக்கும். சேகரிக்கப்பட்ட தரவு எதிர்கால ஆராய்ச்சியில் பயன்படுத்தப்படும், இதில் பிற அடித்தள மாதிரிகள் உருவாக்கப்படும்."}]},{"heading":"தன்னார்வ பங்கேற்பு என்றால் என்ன?","paragraphs":[{"text":"நீங்கள் எந்த நேரத்திலும், எந்தவொரு தண்டனையும் அல்லது நன்மை இழப்பும் இல்லாமல், இந்த ஆய்வில் பங்கேற்க மறுக்கலாம் அல்லது நிறுத்தலாம்."}]},{"heading":"ஆராய்ச்சி தொடர்பான காயங்களுக்கு இழப்பீடு மற்றும் மருத்துவ சிகிச்சைகள் ஏதேனும் உள்ளதா?","paragraphs":[{"text":"இழப்பீடுஃ இந்த ஆய்வில் பங்கேற்பதற்காக உங்களுக்கு பணம் செலுத்தப்படாது. இது குறைந்தபட்ச / எந்த ஆபத்தும் இல்லாத ஆய்வாக இருப்பதால் எந்த இழப்பீடும் வழங்கப்படவில்லை."},{"text":"காயம்ஃ இது ஒரு ஆய்வு/AI அடிப்படையிலான ஆய்வு ஆகும், இதில் எந்த ஆக்கிரமிப்பு நடவடிக்கைகளும் இல்லை, எனவே காயம் தொடர்பான மருத்துவ சிகிச்சை அல்லது இழப்பீடு எதுவும் திட்டமிடப்படவில்லை."},{"text":"செலவுகள்ஃ இந்த ஆய்வில் பங்கேற்பதற்கு நீங்கள் எந்த செலவும் செலுத்த முடியாது."}]},{"heading":"ஆராய்ச்சி முடிவுகள் என்னவாக இருக்கும்?","paragraphs":[{"text":"இந்த ஆராய்ச்சி ஆய்வின் முடிவுகள் AI இயக்கப்பட்ட மார்பக புற்றுநோய் அபாய கணிப்பு கருவியை உருவாக்கவும் சரிபார்க்கவும் பயன்படுத்தப்படும். கண்டுபிடிப்புகள் சமநிலை மதிப்பாய்வு செய்யப்பட்ட அறிவியல் இதழ்களில் வெளியிடப்படலாம், கல்வி மாநாடுகளில் வழங்கப்படலாம், மேலும் இந்தியாவில் மார்பக புற்றுநோய் பரிசோதனை நடைமுறைகளை மேம்படுத்த சுகாதார நிறுவனங்கள் மற்றும் கொள்கை வகுப்பாளர்களுடன் பகிரப்படலாம். வெளியிடப்பட்ட அனைத்து முடிவுகளும் தனிப்பட்ட அடையாளம் காணப்படாமல் கூட்டு வடிவத்தில் இருக்கும்."}]},{"heading":"இந்த ஆராய்ச்சியை யார் ஏற்பாடு செய்து நிதியளிக்கிறார்கள்?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"யார் இந்த ஆய்வை ஆய்வு செய்தார்கள்?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"மேலும் தகவலுக்கு நான் யாரை தொடர்பு கொள்ளலாம்?","paragraphs":[{"text":"தொடர்பு விவரங்கள்ஃ டாக்டர் அஸ்வின் ராகுமார், திட்ட மேலாளர்"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"நீங்கள் ஆய்வுக்கு உட்பட்ட ஒருவரைப் பற்றி பேச விரும்பினால், பின்வரும் முகவரிகளை தொடர்பு கொள்ளலாம்ஃ"},{"text":"நிறுவன நெறிமுறைகள் குழு (IEC)"},{"text":"பெயர்ஃ டாக்டர் ஸ்ரீ வித்யா ஜகதிஷ், ஐ. இ. சி செயலாளர், TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"இந்த ஆய்வில் பங்கேற்றதற்கு நன்றி!"}]}],"checkboxLabel":"பங்கேற்பாளர் தகவல் தாள்களை நான் படித்து புரிந்து கொண்டேன், இந்த ஆய்வில் பங்கேற்க தன்னார்வமாக ஒப்புக்கொண்டேன்.","buttonText":"ஏற்றுக்கொள் & தொடரவும்"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
INSERT INTO participant_information_translations (version_number,language_code,content_json,is_active) VALUES (2,'te','{"title":"పాల్గొనేవారికి సమాచారం","headernames":{"studyTitle":"అధ్యయన శీర్షిక","sponsor":"వ్యవస్థాపకుడు మరియు నిధులు","iecApproval":"నైతికత సమీక్ష"},"header":{"studyTitle":"భారతీయ జనాభాకు కృత్రిమ మేధస్సుతో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి ఒక సాధనం అభివృద్ధి","sponsor":"AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012","iecApproval":"Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012"},"sections":[{"heading":"ఈ అధ్యయనము గురించి","paragraphs":[{"text":"ఈ అధ్యయనం ఆరోగ్య సంరక్షణ కోసం భారతీయ AI పరిష్కారాలను అభివృద్ధి చేయడానికి విద్యా మంత్రిత్వ శాఖ నిధులతో నిధులు సమకూర్చే ప్రాజెక్టులో భాగం. భారతీయ సైన్స్ ఇన్స్టిట్యూట్ నిర్వహించిన TANUH ఫౌండేషన్ ఈ కీలకమైన జాతీయ చొరవను రొమ్ము క్యాన్సర్ పరిశోధనలో నాయకత్వం వహించడం గర్వంగా ఉంది. ఆరోగ్య ఫలితాలను మెరుగుపరచడానికి ప్రారంభ, డేటా ఆధారిత గుర్తింపు చాలా కీలకం అని గుర్తించింది. భారతదేశం అంతటా మహిళల ప్రయోజనం కోసం రొమ్ము క్యాన్సర్ అధ్యయనాలను ముందుకు తీసుకురావడానికి మీ భాగస్వామ్యాన్ని మేము తీవ్రంగా అభినందిస్తున్నాము మరియు ఈ ప్రయత్నంలో ముఖ్యమైన భాగం కావడం కోసం ధన్యవాదాలు. భారతదేశంలో AI ను తయారు చేయండి మరియు AI ను భారతదేశం కోసం పని చేయండి."}]},{"heading":"అధ్యయనానికి ఉద్దేశ్యం ఏమిటి?","paragraphs":[{"text":"భారతీయ జనాభాకు కృత్రిమ మేధస్సుతో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి ఒక సాధనం అభివృద్ధి"}]},{"heading":"నన్ను ఎందుకు ఎన్నుకున్నారు?","paragraphs":[{"text":"మీరు మామ్మోగ్రఫీకి లేదా సాధారణ మామ్మోగ్రఫీకి పంపబడినందున మీరు AI- ప్రారంభించబడిన రొమ్ము క్యాన్సర్ స్క్రీనింగ్ సాధనాల అధ్యయనానికి సహకరించడానికి ఎంపిక చేయబడ్డారు. కొన్ని ప్రశ్నాపత్రాల ద్వారా రొమ్ము క్యాన్సర్ ప్రమాదాన్ని గుర్తించడానికి వీలు కల్పించే AI- ప్రారంభించబడిన రొమ్ము క్యాన్సర్ స్క్రీనింగ్ సాధనాన్ని మేము అభివృద్ధి చేస్తున్నాము."}]},{"heading":"నేను పాల్గొనవలసి ఉందా?","paragraphs":[{"text":"మీరు పూర్తిగా స్వచ్ఛందంగా పాల్గొనవచ్చు. మీరు అధ్యయనంలో పాల్గొనకుండా మీ సాధారణ దినచర్యను కొనసాగించవచ్చు."}]},{"heading":"మీరు పాల్గొనడానికి అంగీకరిస్తే, ఈ క్రింది సంఘటనలు జరుగుతాయి.","paragraphs":[{"text":"సర్వేః మీ జనాభా, ఆరోగ్య చరిత్ర, జీవనశైలి, కుటుంబ చరిత్రకు సంబంధించిన ఒక ప్రశ్నపత్రాన్ని (టాబ్లెట్/డిజిటల్ పరికరంలో) ఒకసారి పూరించమని అడుగుతారు."},{"text":"ప్రమాదం అంచనాః సర్వే ముగింపులో, మీకు వెంటనే రొమ్ము క్యాన్సర్ ప్రమాదం అంచనా ఇవ్వబడుతుంది (మీరు సాధారణ లేదా అధిక ప్రమాదం ఉన్నారో గుర్తించడం)."},{"text":"మార్గదర్శకత్వంః ప్రమాదం స్థాయి ఆధారంగా మీకు మార్గదర్శకత్వం లభిస్తుంది. మీకు ఎక్కువ ప్రమాదం ఉన్నట్లు గుర్తించినట్లయితే, మీరు మామోగ్రఫీకి పంపబడవచ్చు. మీరు సాధారణ / తక్కువ ప్రమాదం ఉన్నట్లయితే, మీరు సాధారణ తనిఖీ ప్రోటోకాల్లను కొనసాగించమని అడుగుతారు."},{"text":"డేటా వినియోగం: మీ నుండి మరియు ఆసుపత్రి నుండి సేకరించిన డేటా భారతీయ మహిళల్లో రొమ్ము క్యాన్సర్ ప్రమాదాన్ని బాగా అంచనా వేయడానికి కృత్రిమ మేధస్సు (AI) నమూనాను శిక్షణ ఇవ్వడానికి ఉపయోగించబడుతుంది."}]},{"heading":"నేను పాల్గొంటే నాకు ఏమి జరుగుతుంది?","paragraphs":[{"text":"వ్యక్తిగత ప్రమాదం అంచనా మీరు భవిష్యత్తులో ఆరోగ్య పర్యవేక్షణ కోసం సాధ్యం రొమ్ము క్యాన్సర్ లక్షణాలు మరియు మీ వ్యక్తిగత ప్రమాద కారకాలు మరింత తెలుసుకోవడంలో సహాయపడుతుంది."}]},{"heading":"నేను ఏమి చేయాలి?","paragraphs":[{"text":"You need to complete a one-time questionnaire about lifestyle, family history, and demographics health-related factors at https://bc-portal-dev.tanuh.ai/. It will also involve you following a video-based tutorial on self-breast examination and answering questions. At any point of time, the nurse staff will be able to guide you through the process and complete the questionnaire."}]},{"heading":"ఈ కార్యక్రమంలో పాల్గొనడం వల్ల కలిగే నష్టాలు ఏమిటి?","paragraphs":[{"text":"ఈ పరిశోధనలో పాల్గొనడం వల్ల పెద్ద ప్రమాదం లేదు."},{"text":"సంఖ్య/ కనీస ప్రమాదంః ఈ అధ్యయనం \\"నో/ మినిమల్ రిస్క్\\" గా పరిగణించబడుతుంది."},{"text":"గోప్యతః గోప్యతకు సంబంధించి అరుదైన ప్రమాదం ఉంది, కానీ మేము వ్యక్తిగతంగా గుర్తించదగిన సమాచారాన్ని సేకరించడం లేదు మరియు డేటా అనామకంగా సంగ్రహించబడుతుంది."},{"text":"స్వచ్ఛందంగాః ఈ ప్రశ్నాపత్రం పూర్తిగా స్వచ్ఛందంగా ఉంటుంది. మీకు ఆసక్తి లేకపోతే, మీరు సాధారణ క్లినిక్ చికిత్సను కొనసాగించవచ్చు."},{"text":"ఏ ఇన్వాసివ్ విధానాలుః ఇది డిజిటల్ మరియు వర్క్ఫ్లో ఆవిష్కరణ అధ్యయనం; పరిశోధన భాగంలో ప్రయోగాత్మక మందులు లేదా ఇన్వాసివ్ చికిత్సలు పాల్గొనలేదు."}]},{"heading":"పాల్గొనడం వల్ల కలిగే ప్రయోజనాలు ఏమిటి?","paragraphs":[{"text":"వ్యక్తిగత ప్రయోజనంః పాల్గొనేవారికి ప్రత్యక్ష ప్రయోజనం ఉండదు. అయితే, మీ స్క్రీనింగ్ వ్యూహాన్ని తెలియజేయడానికి సహాయపడే ప్రమాదం అంచనాను మీరు అందుకుంటారు."},{"text":"సామాజిక ప్రయోజనం: మీ భాగస్వామ్యం రొమ్ము క్యాన్సర్ ను ప్రారంభంలో గుర్తించడం, భారతదేశం లో మహిళలకు మెరుగైన వనరుల కేటాయింపు వంటి శాస్త్రీయ ప్రయోజనాలకు దోహదం చేస్తుంది."}]},{"heading":"ఈ అధ్యయనంలో నా పాల్గొనడం రహస్యంగా ఉంచుకోబడుతుందా?","paragraphs":[{"text":"అవును. ఈ అధ్యయనంలో సేకరించిన మొత్తం సమాచారం ఖచ్చితంగా గోప్యంగా ఉంటుంది. అన్ని వ్యక్తిగత డేటా వర్తించే డేటా రక్షణ నిబంధనలకు అనుగుణంగా అనామకపరచబడుతుంది మరియు సురక్షితంగా నిల్వ చేయబడుతుంది. అధికారం కలిగిన పరిశోధనా బృందం సభ్యులు మాత్రమే డేటాకు ప్రాప్యత కలిగి ఉంటారు, మరియు మీ వ్యక్తీకరణ అనుమతి లేకుండా వ్యక్తిగత గుర్తింపు సమాచారాన్ని మూడవ పార్టీలతో పంచుకోరు. అధ్యయన ఫలితాలు సంయుక్త రూపంలో మాత్రమే ప్రదర్శించబడతాయి, వ్యక్తిగత పాల్గొనేవారిని గుర్తించలేదని నిర్ధారిస్తుంది."},{"text":"ఐఐ అల్గోరిథంల అంచనా కోసం టానూహే యొక్క బెంచర్మార్కింగ్ మరియు ఓపెన్ డేటా కార్యక్రమంలో భాగంగా, మొత్తం డేటాలో 20% వరకు తిరిగి చెల్లించలేని అనామక పద్ధతిలో సేకరించబడుతుంది. సేకరించిన డేటా భవిష్యత్తులో పరిశోధనలో ఉపయోగించబడుతుంది, ఇందులో ఇతర ఫౌండేషన్ మోడళ్ల అభివృద్ధి కూడా ఉంటుంది."}]},{"heading":"స్వచ్ఛంద భాగస్వామ్యం అంటే ఏమిటి?","paragraphs":[{"text":"మీరు పూర్తిగా స్వచ్ఛందంగా పాల్గొనవచ్చు. మీరు ఎటువంటి జరిమానా లేదా ప్రయోజనాల నష్టం లేకుండా ఎప్పుడైనా పాల్గొనడానికి నిరాకరించవచ్చు లేదా సర్వేను నిలిపివేయవచ్చు."}]},{"heading":"పరిశోధన సంబంధిత గాయాలకు ఏదైనా పరిహారం మరియు వైద్య సంరక్షణ ఉందా?","paragraphs":[{"text":"పరిహారంః ఈ అధ్యయనంలో పాల్గొనడానికి మీకు చెల్లించరు. ఇది కనీస/అపాయం లేని అధ్యయనంగా ఉన్నందున పరిహారం అందించబడదు."},{"text":"గాయంః ఇది సర్వే/AI ఆధారిత స్క్రీనింగ్ అధ్యయనం కాబట్టి, ఇది ఏ విధమైన ఆక్రమణ చర్యలను కలిగి ఉండదు, గాయం కోసం వైద్య చికిత్స లేదా పరిహారం అందించడం ప్రణాళిక చేయబడదు."},{"text":"ఖర్చులుః ఈ అధ్యయనంలో పాల్గొనడానికి మీకు ఎటువంటి ఖర్చు లేదు."}]},{"heading":"పరిశోధన ఫలితాల గురించి ఏమి జరుగుతుంది?","paragraphs":[{"text":"ఈ పరిశోధన అధ్యయనం యొక్క ఫలితాలు AI ప్రారంభించిన రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి సాధనం అభివృద్ధి చేయడానికి మరియు ధృవీకరించడానికి ఉపయోగించబడతాయి. ఫలితాలు పీర్-రివ్యూ చేసిన శాస్త్రీయ పత్రికలలో ప్రచురించబడతాయి, విద్యా సమావేశాలలో ప్రదర్శించబడతాయి మరియు భారతదేశంలో రొమ్ము క్యాన్సర్ స్క్రీనింగ్ పద్ధతులను మెరుగుపరచడానికి ఆరోగ్య సంరక్షణ సంస్థలు మరియు విధాన నిర్మాతలతో పంచుకోవచ్చు. ప్రచురించిన ఫలితాలు ఏ వ్యక్తి గుర్తింపు లేకుండా సంయుక్త రూపంలో ఉంటాయి."}]},{"heading":"పరిశోధన ను ఎవరు నిర్వహిస్తున్నారు, ఎవరు నిధులు సమకూర్చుతున్నారు?","paragraphs":[{"text":"This research is being organized and funded by the AI Centre of Excellence in Healthcare at TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"ఈ అధ్యయనాన్ని ఎవరు సమీక్షించారు?","paragraphs":[{"text":"This study has been reviewed by the Institutional Ethics Committee (IEC), TANUH Foundation, Indian Institute of Science, Bangalore 560012."}]},{"heading":"మరిన్ని సమాచారం కోసం నేను ఎవరిని సంప్రదించగలను?","paragraphs":[{"text":"సంప్రదింపు వివరాలుః ప్రాజెక్ట్ మేనేజర్ డాక్టర్ అశ్విన్ రాజ్ కుమార్"},{"text":"Email: breastcancerscreening@tanuh.ai"},{"text":"Phone: 080 - 2293 4106 / 2293 4107"},{"text":"మీరు ఈ అధ్యయనానికి సంబంధించి ఒక వ్యక్తితో మాట్లాడాలనుకుంటే, మీరు ఈ క్రింది వాటికి సంప్రదించవచ్చుః"},{"text":"సంస్థాగత నైతిక కమిటీ (ఐఇసి)"},{"text":"పేరు: డాక్టర్ శ్రీ విద్యా జగదీష్, ఐఇసి కార్యదర్శి, తన్యుహ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"},{"text":"ఈ అధ్యయనంలో పాల్గొన్నందుకు ధన్యవాదాలు!"}]}],"checkboxLabel":"నేను పాల్గొనేవారి సమాచార పత్రాన్ని చదివాను మరియు అర్థం చేసుకున్నాను మరియు ఈ అధ్యయనంలో పాల్గొనడానికి స్వచ్ఛందంగా అంగీకరిస్తున్నాను.","buttonText":"అంగీకరించు & కొనసాగించు"}',1) AS incoming ON DUPLICATE KEY UPDATE content_json=incoming.content_json,is_active=incoming.is_active;
