-- Approved Participant Information Sheet plus locally generated translations.
-- Production-safe: review the final SELECT and explicitly COMMIT or ROLLBACK.
SET NAMES utf8mb4;
USE bcd_application2;
START TRANSACTION;


SELECT version_number,language_code,is_active,
       JSON_LENGTH(content_json,'$.sections') AS section_count
FROM participant_information_translations
WHERE version_number IN (1,2)
ORDER BY version_number,language_code;
-- Deliberately no COMMIT.
